def potd_view(pid: int) -> discord.ui.View:
    v = discord.ui.View(timeout=None)
    v.add_item(PotdButton(pid, "over"))
    v.add_item(PotdButton(pid, "under"))
    return v


async def create_potd(guild_id: int, channel, now: datetime, cand: dict, line: Optional[float] = None):
    values = []
    try:
        games = await trend_games(cand["path"], cand["athlete_id"], need=10)
        values = [v for _, v in trend_values(games, cand["stat_key"])[:10]]
    except Exception:
        log.warning("POTD game log failed")
    use = line if line is not None else potd_line(values)
    trend = ""
    if values:
        o = sum(1 for v in values if v > use)
        trend = f"Over {use:g} in {o} of {len(values)} · avg {sum(values) / len(values):.1f}"
    ev = cand["event"]
    away = next(t for t in ev["teams"] if not t["home"])["short"]
    home = next(t for t in ev["teams"] if t["home"])["short"]
    cur = db().execute("""INSERT INTO potd (guild_id, day, player, athlete_id, path, stat_key, line, event_id, start, game,
                          trend, channel_id, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                       (guild_id, now.astimezone(TZ).date().isoformat(), cand["name"], cand["athlete_id"], cand["path"],
                        cand["stat_key"], use, ev["id"], iso(event_time(ev)), f"{away} @ {home}", trend,
                        channel.id if channel else None, now_iso()))
    db().commit()
    pd = db().execute("SELECT * FROM potd WHERE id = ?", (cur.lastrowid,)).fetchone()
    if channel is not None:
        msg = await channel.send(embed=potd_embed(pd), view=potd_view(pd["id"]))
        db().execute("UPDATE potd SET message_id = ? WHERE id = ?", (msg.id, pd["id"]))
        db().commit()
    return pd


async def post_potd(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = (now or datetime.now(TZ)).astimezone(TZ)
    if now.hour < TODAY_HOUR:
        return
    import random
    for r in db().execute("SELECT guild_id, value FROM settings WHERE key = 'potd_channel'").fetchall():
        gid, day = r["guild_id"], now.date().isoformat()
        if get_setting(gid, "last_potd") == day:
            continue
        set_setting(gid, "last_potd", day)
        channel = client.get_channel(int(r["value"]))
        cands = await potd_candidates(gid, now.astimezone(timezone.utc))
        if not cands or channel is None:
            continue
        rng = random.Random(f"{gid}:{day}")
        await create_potd(gid, channel, now.astimezone(timezone.utc), rng.choice(cands))


async def grade_potd(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    for pd in db().execute("SELECT * FROM potd WHERE result IS NULL AND start <= ?", (iso(now),)).fetchall():
        leg = {"player": norm_name(pd["player"]), "stats": [pd["stat_key"]], "side": "over", "line": pd["line"],
               "negate": False}
        try:
            st = await prop_status(leg, [pd["path"]], datetime.fromisoformat(pd["start"]) - timedelta(hours=1))
        except Exception:
            continue
        if not st or st["state"] != "post" or st["value"] is None:
            gone = datetime.fromisoformat(pd["start"]) < now - timedelta(hours=12)
            if (st and st["state"] == "post" and st["result"] == "push" and st["value"] is None) or \
                    (gone and (st is None or st["state"] == "post")):     # didn't play / not in the box score
                db().execute("UPDATE potd SET result = 'push', value = 0 WHERE id = ?", (pd["id"],))
                db().commit()
            continue
        v = st["value"]
        result = "push" if v == pd["line"] else ("over" if v > pd["line"] else "under")
        db().execute("UPDATE potd SET result = ?, value = ? WHERE id = ?", (result, v, pd["id"]))
        db().commit()
        right = [r for r in db().execute("SELECT * FROM potd_votes WHERE potd_id = ?", (pd["id"],)) if r["side"] == result]
        for r in right:
            award(pd["guild_id"], r["user_id"], COIN_RULES["potd"], "Prop of the Day", f"potd:{pd['id']}:{r['user_id']}")
        pd = db().execute("SELECT * FROM potd WHERE id = ?", (pd["id"],)).fetchone()
        channel = client.get_channel(pd["channel_id"]) if pd["channel_id"] else None
        if channel is None:
            continue
        if pd["message_id"]:
            try:
                await channel.get_partial_message(pd["message_id"]).edit(embed=potd_embed(pd), view=None)
            except Exception:
                pass
        total = db().execute("SELECT COUNT(*) FROM potd_votes WHERE potd_id = ?", (pd["id"],)).fetchone()[0]
        word = {"over": "MORE", "under": "LESS", "push": "a PUSH"}[result]
        await channel.send(f"🎯 Prop of the Day: {pd['player']} had **{v:g}** {STATS[pd['stat_key']][0]} "
                           f"(line {pd['line']:g}) → **{word}**. {len(right)} of {total} got it"
                           + (": " + ", ".join(r["user_name"] for r in right[:10]) if right else "") + ".",
                           allowed_mentions=discord.AllowedMentions.none())


def potd_standings(guild_id: int) -> list[tuple[str, int, int]]:
    rows = db().execute("""SELECT v.user_name, v.side, p.result FROM potd_votes v JOIN potd p ON p.id = v.potd_id
                           WHERE p.guild_id = ? AND p.result IN ('over', 'under')""", (guild_id,)).fetchall()
    rec: dict[str, list[int]] = {}
    for r in rows:
        x = rec.setdefault(r["user_name"], [0, 0])
        x[0 if r["side"] == r["result"] else 1] += 1
    return sorted(((n, w, l) for n, (w, l) in rec.items()), key=lambda t: (t[1] / max(1, t[1] + t[2]), t[1]), reverse=True)


# ---- hidden picks ---------------------------------------------------------------------------

async def reveal_hidden(client: discord.Client, now: Optional[datetime] = None) -> None:
    for p in db().execute("""SELECT * FROM picks WHERE hidden = 1 AND status != 'open' AND revealed_at IS NULL""").fetchall():
        db().execute("UPDATE picks SET revealed_at = ? WHERE id = ?", (now_iso(), p["id"]))
        db().commit()
        channel = await recap_channel_for(client, p["guild_id"])
        if channel is None:
            continue
        locked = local_day(p["created_at"]) + datetime.fromisoformat(p["created_at"]).astimezone(TZ).strftime(" %-I:%M %p")
        await channel.send(f"🔓 **Revealed:** {p['bettor_name']}'s hidden pick `#{p['id']}`, locked in {locked}.",
                           embed=pick_embed(p), allowed_mentions=discord.AllowedMentions.none())


def private_card(p) -> discord.Embed:
    """The owner's own view of a hidden pick."""
    e = pick_embed(dict(p) | {"hidden": 0})
    e.set_author(name="🔒 Hidden from everyone else until it settles")
    return e


# ---- logging from a DM ------------------------------------------------------------------------

def home_guild_for(client: discord.Client, user) -> Optional[int]:
    if GUILD_ID:
        return int(GUILD_ID)
    mutual = list(getattr(user, "mutual_guilds", None) or [])
    return mutual[0].id if mutual else None


async def handle_dm_slip(client: discord.Client, message: discord.Message, attachment: discord.Attachment) -> None:
    gid = home_guild_for(client, message.author)
    if gid is None:
        await message.reply("I don't share a server with you, so I can't log that.")
        return
    until = cooling_until(gid, message.author.id)
    if until:
        await message.reply(cooloff_message(until))
        return
    if not slip_reader_on():
        await message.reply("Reading slips isn't set up here. In the server, use "
                            "`/pick` with `hidden: True` to log it privately.")
        return
    wait = sec_wait(message.author.id, "slip_read", "slip")
    if wait:
        await message.reply(sec_slow_text(wait))
        return
    slip, reason = await read_slip_best(attachment)
    await keep_slip_photo(attachment, getattr(message, "id", 0) or 0)
    if slip is not None and slip.get("_unsure"):
        await message.reply("I read part of that, but not cleanly enough to log it privately ("
                            + ", ".join(slip["_unsure"][:3]) + "). Try a clearer screenshot, or use `/pick hidden:True` "
                            "in the server.")
        return
    if slip is None or slip.get("cost") is None:
        await message.reply(f"I couldn't read that one{': ' + reason if reason else ''}. Try a clearer screenshot, "
                            "or use `/pick hidden:True` in the server.")
        return
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()]
    pid = insert_pick(guild_id=gid, bettor_key=str(message.author.id), bettor_name=message.author.display_name,
                      bettor_id=message.author.id, logged_by=message.author.id,
                      platform=str(slip.get("platform") or "Other")[:40],
                      sport=(str(slip["sport"])[:60] if slip.get("sport") else None),
                      description=str(slip.get("description") or "Slip")[:200], legs="\n".join(legs) or None,
                      cost=slip["cost"], payout=slip["payout"] or 0.0)
    apply_slip_meta(pid, slip)
    db().execute("UPDATE picks SET hidden = 1 WHERE id = ?", (pid,))
    db().commit()
    bind_slip_shot(pid, getattr(message, "id", None), getattr(attachment, "id", None), len(legs))
    if slip["status"] != "open":
        settle_pick(gid, pid, slip["status"], slip["returned"])
    p = get_pick(gid, pid)
    await message.reply(f"🔒 Logged privately as pick `#{pid}`. Nobody sees the details until it settles, then it's "
                        "revealed with the result. I'll grade it like any other pick.", embed=private_card(p))


# ---- right-click menus -------------------------------------------------------------------------

def pick_from_message(guild_id: int, message) -> Optional[sqlite3.Row]:
    for e in getattr(message, "embeds", None) or []:
        m = re.match(r"^(?:Pick|🥵 Sweat · Pick) #(\d+)", e.title or "")
        if m:
            return get_pick(guild_id, int(m.group(1)))
    url = getattr(message, "jump_url", None)
    if url:
        return db().execute("SELECT * FROM picks WHERE guild_id = ? AND slip_url = ? ORDER BY id DESC LIMIT 1",
                            (guild_id, url)).fetchone()
    return None


async def log_message_as_pick(interaction: discord.Interaction, message: discord.Message):
    images = [a for a in getattr(message, "attachments", []) or []
              if image_type(a)]
    mine = message.author.id == interaction.user.id
    if not images:
        if not mine:
            await interaction.response.send_message("That only works on slip screenshots, or on your own messages.",
                                                    ephemeral=True)
            return
        modal = SlipModal(message.jump_url)
        modal.description.default = clip(message.content or "", 200) or None
        await interaction.response.send_modal(modal)
        return
    existing = db().execute("SELECT id FROM picks WHERE guild_id = ? AND slip_url = ?",
                            (interaction.guild_id, message.jump_url)).fetchone()
    if existing:
        await interaction.response.send_message(f"That slip is already pick `#{existing['id']}`.", ephemeral=True)
        return
    if not ai_enabled():
        if not mine:
            await interaction.response.send_message("Reading slips needs the Claude key. Ask them to log it.", ephemeral=True)
            return
        await interaction.response.send_modal(SlipModal(message.jump_url))
        return
    wait = sec_wait(interaction.user.id, "slip_read", "slip")
    if wait:
        await interaction.response.send_message(sec_slow_text(wait), ephemeral=True)
        return
    await interaction.response.defer(ephemeral=True, thinking=True)
    try:
        slip = await read_slip(images[0])
        await keep_slip_photo(images[0], message.id)
    except Exception:
        log.exception("Context-menu slip read failed")
        slip = None
    if slip is None or slip.get("cost") is None:
        await interaction.followup.send("I couldn't read that one cleanly. They can log it with `/pick`.", ephemeral=True)
        return
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()]
    pid = insert_pick(guild_id=interaction.guild_id, bettor_key=str(message.author.id),
                      bettor_name=message.author.display_name, bettor_id=message.author.id,
                      logged_by=interaction.user.id, platform=str(slip.get("platform") or "Other")[:40],
                      sport=(str(slip["sport"])[:60] if slip.get("sport") else None),
                      description=str(slip.get("description") or "Slip")[:200], legs="\n".join(legs) or None,
                      cost=slip["cost"], payout=slip["payout"] or 0.0, slip_url=message.jump_url)
    apply_slip_meta(pid, slip)
    bind_slip_shot(pid, message.id, getattr(images[0], "id", None), len(legs))
    mark_staff_test(interaction.guild_id, getattr(message.channel, "id", None), pid)
    if slip["status"] != "open":
        settle_pick(interaction.guild_id, pid, slip["status"], slip["returned"])
    p = get_pick(interaction.guild_id, pid)
    await interaction.followup.send(f"Logged as pick `#{pid}` for {message.author.display_name}.", ephemeral=True)
    await message.reply(embed=pick_embed(p), view=settle_view(pid) if p["status"] == "open" else None,
                        mention_author=False)


async def copy_from_message(interaction: discord.Interaction, message: discord.Message):
    p = pick_from_message(interaction.guild_id, message)
    if p is None:
        await interaction.response.send_message("I can't find a pick on that message.", ephemeral=True)
        return
    if p["status"] != "open" or p["hidden"]:
        await interaction.response.send_message("That pick can't be copied right now.", ephemeral=True)
        return
    if str(interaction.user.id) == p["bettor_key"]:
        await interaction.response.send_message("That's already your pick.", ephemeral=True)
        return
    await interaction.response.send_modal(CopyModal(p))


# ---- player research: averages, history vs a team, back-to-backs ----------------------------------

MAIN_STATS = {"basketball": ["points", "rebounds", "assists", "pra", "pr", "pa", "ra", "threes", "threes_att",
                             "fgm", "fga", "ftm", "oreb", "steals", "blocks", "stocks", "turnovers", "fantasy", "pts50"],
              "football": ["pass_yds", "pass_td", "rush_yds", "rush_td", "rec", "rec_yds", "rush_rec_yds", "anytime_td"],
              "baseball": ["hits", "hrr", "home_runs", "pitcher_k", "pitching_outs", "earned_runs"],
              "hockey": ["goals", "nhl_assists", "nhl_points", "sog", "saves"]}
B2B_PATHS = ("basketball/nba", "basketball/wnba", "hockey/nhl", "basketball/mens-college-basketball")


def avg_embed(cand: dict, games: list[dict]) -> discord.Embed:
    fam = FAMILY_OF_PATH[cand["path"]]
    e = discord.Embed(title=f"📊 {cand['name']} · averages", color=BRAND,
                      description=(cand["team"] or "") + f"\n{len(games)} games on file (preseason left out)")
    rows = []
    for k in MAIN_STATS[fam]:
        vals = [v for _, v in trend_values(games, k)]
        if not vals or not any(vals):
            continue
        def avg(n):
            part = vals[:n]
            return f"{sum(part) / len(part):.1f}" if part else "-"
        rows.append(f"**{STATS[k][0]}** · L5 {avg(5)} · L10 {avg(10)} · all {avg(len(vals))}")
    e.add_field(name="Stat · last 5 · last 10 · everything on file", value="\n".join(rows) or "No stats yet.", inline=False)
    if games:
        g = games[0]
        when = datetime.fromisoformat(g["date"].replace("Z", "+00:00")).astimezone(TZ).strftime("%b %-d") if g["date"] else ""
        e.set_footer(text=f"Last game: {when} {'@' if g['at'] == '@' else 'vs'} {g['opp']} · pick a stat below for its trend")
    return e


class AvgView(discord.ui.View):
    def __init__(self, owner_id: int, cand: dict, games: list[dict]):
        super().__init__(timeout=900)
        self.owner_id, self.cand, self.games = owner_id, cand, games
        fam = FAMILY_OF_PATH[cand["path"]]
        opts = [discord.SelectOption(label=f"Trend: {STATS[k][0]}", value=k) for k in MAIN_STATS[fam]]
        sel = discord.ui.Select(placeholder="Open a trend chart", options=opts)
        sel.callback = self._cb(sel)
        self.add_item(sel)

    def _cb(self, sel):
        async def cb(interaction):
            if interaction.user.id != self.owner_id:
                await interaction.response.send_message("Run `/player avg` yourself.", ephemeral=True)
                return
            k = sel.values[0]
            values = trend_values(self.games, k)
            line = default_line([v for _, v in values[:10]])
            tv = TrendView(self.owner_id, self.cand, self.games, k, line, "10")
            await tv.redraw(interaction)
        return cb


def vs_embed(cand: dict, games: list[dict], opp: str) -> discord.Embed:
    o = opp.strip().lower()
    hits = [g for g in games if o in (g["opp"] or "").lower() or o in (g.get("opp_name") or "").lower()]
    fam = FAMILY_OF_PATH[cand["path"]]
    e = discord.Embed(title=f"🆚 {cand['name']} vs {opp.upper() if len(opp) <= 4 else opp.title()}", color=BRAND)
    if not hits:
        e.description = "No games against them on file (this season and last)."
        return e
    keys = [k for k in MAIN_STATS[fam] if any(v for _, v in trend_values(hits, k))][:5]
    lines = []
    for g in hits[:10]:
        when = datetime.fromisoformat(g["date"].replace("Z", "+00:00")).astimezone(TZ).strftime("%b %-d, %Y") if g["date"] else ""
        parts = []
        for k in keys:
            got = stat_value(g["groups"], k)
            if got is not None:
                parts.append(f"{got[0]:g} {STATS[k][0]}")
        lines.append(f"{when} {'@' if g['at'] == '@' else 'vs'} {g['opp']} {g['result']} · " + " · ".join(parts))
    e.description = "\n".join(lines)
    avgs = []
    for k in keys:
        vals = [v for _, v in trend_values(hits, k)]
        if vals:
            avgs.append(f"**{STATS[k][0]}** {sum(vals) / len(vals):.1f}")
    e.add_field(name=f"Average in {len(hits)} games", value=" · ".join(avgs) or "-", inline=False)
    return e


async def b2b_team_ids(path: str, day: datetime) -> set[str]:
    """Teams that played the day before `day` (local)."""
    if path not in B2B_PATHS:
        return set()
    out = set()
    for ev in await fetch_scoreboard(path, day.astimezone(TZ) - timedelta(days=1)):
        out |= {t["id"] for t in ev["teams"]}
    return out


# ---- web dashboard ------------------------------------------------------------------------------

WEB_PORT = env("PORT", "")
PUBLIC_DOMAIN = env("RAILWAY_PUBLIC_DOMAIN", "")


def dashboard_key() -> str:
    """Stable cookie secret. Never shown. Env DASHBOARD_KEY still works as a master sign-in."""
    key = env("DASHBOARD_KEY", "")
    if key:
        return key
    key = get_setting(0, "dashboard_key")
    if not key:
        key = secrets.token_urlsafe(18)
        set_setting(0, "dashboard_key", key)
    return key


DASH_ANSWERED: dict = {"at": None}


def dashboard_url() -> Optional[str]:
    if not PUBLIC_DOMAIN:
        return None
    return f"https://{PUBLIC_DOMAIN}/"


def _dash_key_match(a: Optional[str], b: str) -> bool:
    if not a or not b or len(a) > 128:
        return False
    ae, be = a.encode(), b.encode()
    if len(ae) != len(be):
        hmac.compare_digest(ae, ae)
        return False
    return hmac.compare_digest(ae, be)


def dash_gate_state() -> dict:
    """Today's unused access code. Minted at midnight and again each time someone signs in with it."""
    day = datetime.now(TZ).date().isoformat()
    try:
        d = json.loads(get_setting(0, "dash_gate") or "{}")
    except Exception:
        d = {}
    if not isinstance(d, dict):
        d = {}
    if d.get("day") != day or not d.get("code") or len(str(d.get("code") or "")) > 40:
        d = {"day": day, "code": secrets.token_urlsafe(10), "used": int(d.get("used") or 0)}
        set_setting(0, "dash_gate", json.dumps(d))
    return d


def dash_gate_code() -> str:
    return str(dash_gate_state().get("code") or "")


def dash_gate_rotate() -> str:
    day = datetime.now(TZ).date().isoformat()
    prev = dash_gate_state()
    d = {"day": day, "code": secrets.token_urlsafe(10), "used": int(prev.get("used") or 0) + 1}
    set_setting(0, "dash_gate", json.dumps(d))
    return d["code"]


def dash_take_key(candidate: Optional[str]) -> bool:
    """True when this key may sign in. A one-time staff code is spent and a fresh one is minted."""
    if _dash_key_match(candidate, dashboard_key()):
        return True
    if _dash_key_match(candidate, dash_gate_code()):
        dash_gate_rotate()
        return True
    return False


def central_stamp(when: datetime) -> str:
    """A time of day labeled Central. No slip list is attached."""
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    return when.astimezone(TZ).strftime("%b %-d, %-I:%M %p") + " Central"


def dash_this_week(guild_id: int) -> dict:
    """Open slips, plus what settled since Monday: count, net, and coins earned."""
    now = datetime.now(TZ)
    start = (now - timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    settled, net = 0, 0.0
    try:
        rows = db().execute(
            """SELECT cost, returned, settled_at, created_at, hidden, revealed_at, test, bettor_name
               FROM picks WHERE guild_id = ? AND status != 'open'""", (guild_id,)).fetchall()
    except Exception:
        rows = []
    for p in rows:
        if p["hidden"] and not p["revealed_at"]:
            continue
        if p["test"]:
            continue
        if dashboard_hidden_pick(p):
            continue
        raw = p["settled_at"] or p["created_at"] or ""
        try:
            when = datetime.fromisoformat(raw)
        except Exception:
            continue
        if when.tzinfo is None:
            when = when.replace(tzinfo=timezone.utc)
        if when.astimezone(TZ) < start:
            continue
        settled += 1
        net += (p["returned"] or 0.0) - (p["cost"] or 0.0)
    open_n = 0
    try:
        for p in db().execute(
                """SELECT bettor_name FROM picks WHERE guild_id = ? AND status = 'open'
                   AND (hidden IS NULL OR hidden = 0) AND (test IS NULL OR test = 0)""",
                (guild_id,)):
            if dashboard_hidden_pick(p):
                continue
            open_n += 1
    except Exception:
        open_n = 0
    coins = 0
    names = {}
    try:
        for person in db().execute(
                "SELECT bettor_id, bettor_name FROM picks WHERE guild_id = ? AND bettor_id IS NOT NULL",
                (guild_id,)):
            names[person["bettor_id"]] = person["bettor_name"]
    except Exception:
        names = {}
    try:
        for tx in db().execute(
                "SELECT user_id, delta, created_at FROM coin_tx WHERE guild_id = ?", (guild_id,)):
            if dashboard_hidden_name(names.get(tx["user_id"])):
                continue
            try:
                when = datetime.fromisoformat(tx["created_at"])
            except Exception:
                continue
            if when.tzinfo is None:
                when = when.replace(tzinfo=timezone.utc)
            if when.astimezone(TZ) >= start and int(tx["delta"] or 0) > 0:
                coins += int(tx["delta"])
    except Exception:
        coins = 0
    return {"open": int(open_n or 0), "settled": settled, "net": round(net, 2), "coins": coins}


def dash_week_plays(guild_id: int) -> list[dict]:
    """Slips logged since Monday, for the small board of what the crew put in this week."""
    now = datetime.now(TZ)
    start = (now - timedelta(days=now.weekday())).strftime("%Y-%m-%d")
    out = []
    try:
        rows = db().execute(
            """SELECT * FROM picks WHERE guild_id = ? ORDER BY id DESC LIMIT 40""", (guild_id,)).fetchall()
    except Exception:
        return []
    for p in rows:
        if p["hidden"] and not p["revealed_at"]:
            continue
        if pick_is_test(p):
            continue
        if dashboard_hidden_pick(p):
            continue
        if local_stamp(p["created_at"] or "") < start:
            continue
        uid = p["bettor_id"]
        key = str(uid) if uid and str(uid).isdigit() else (p["bettor_key"] if str(p["bettor_key"] or "").isdigit() else "")
        net = None if p["status"] == "open" else round(pick_net(p), 2)
        out.append({"id": p["id"], "who": clip(p["bettor_name"], 40), "key": key,
                    "what": clip(p["description"] or "", 80), "net": net, "status": p["status"] or "open"})
        if len(out) >= 12:
            break
    return out


def dash_prop_name(text: str) -> str:
    """Player display name when this line is a player prop. Empty for parlays, totals, and team bets."""
    try:
        pr = parse_prop_leg(text or "")
    except Exception:
        pr = None
    if not isinstance(pr, dict) or pr.get("kind") != "prop" or pr.get("combo"):
        return ""
    return clip(str(pr.get("display") or ""), 40)


def dash_commands() -> list:
    """The same groups /help uses, so More can list every command on one page."""
    try:
        fields = help_embed().fields
    except Exception:
        return []
    return [{"name": clip(f.name, 48), "text": f.value} for f in fields]


def dashboard_data(guild_id: int) -> dict:
    season = current_season(guild_id)
    def board(stats):
        return [{"key": s["key"], "name": s["name"], "record": record_line(s), "net": round(s["net"], 2),
                 "roi": round(s["roi"], 1), "streak": current_streak(guild_id, s["key"]), "open": s["open"]}
                for s in stats
                if s["wins"] + s["losses"] + s["pushes"] > 0 and not dashboard_hidden_name(s.get("name"))]
    series = dashboard_profit_series(chart_series(guild_id, 3650))
    recent = []
    for p in db().execute("""SELECT * FROM picks WHERE guild_id = ? AND status != 'open' AND
                                       (hidden IS NULL OR hidden = 0 OR revealed_at IS NOT NULL)
                                       AND (test IS NULL OR test = 0)
                                       ORDER BY settled_at DESC LIMIT 80""", (guild_id,)):
        if dashboard_hidden_pick(p):
            continue
        recent.append({"id": p["id"], "who": p["bettor_name"], "key": str(p["bettor_id"] or ""),
                       "what": shown_desc(p), "platform": p["platform"],
                       "sport": clip(p["sport"] or "", 24), "status": p["status"], "net": round(pick_net(p), 2),
                       "cost": p["cost"], "payout": p["payout"], "when": local_day(p["settled_at"] or p["created_at"]),
                       "stamp": local_stamp(p["settled_at"] or p["created_at"] or "")})
        if len(recent) >= 25:
            break
    open_ = []
    for p in db().execute("""SELECT * FROM picks WHERE guild_id = ? AND status = 'open'
                                       AND (hidden IS NULL OR hidden = 0)
                                       AND (future_due IS NULL OR future_due = '')
                                       AND (test IS NULL OR test = 0)
                                       ORDER BY id DESC LIMIT 120""", (guild_id,)):
        if dashboard_hidden_pick(p):
            continue
        open_.append({"id": p["id"], "who": p["bettor_name"], "key": str(p["bettor_id"] or ""),
                      "what": shown_desc(p), "platform": p["platform"],
                      "sport": clip(p["sport"] or "", 24), "cost": p["cost"], "payout": p["payout"],
                      "logged": local_stamp(p["created_at"] or ""),
                      "slate": local_day(p["slate_date"]) if _rg(p, "slate_date") else "",
                      "slate_on": local_stamp(p["slate_date"]) if _rg(p, "slate_date") else "",
                      "side": (_rg(p, "kalshi_side") or "").strip().lower()[:8],
                      "logger": int(p["logged_by"] or 0),
                      "player": dash_prop_name(shown_desc(p)) or None})
        if len(open_) >= 40:
            break
    legmap: dict[int, list] = {}
    if open_:
        marks = ",".join("?" * len(open_))
        for leg in db().execute(
                f"SELECT pick_id, status, text FROM legs WHERE pick_id IN ({marks})",
                [row["id"] for row in open_]):
            legmap.setdefault(int(leg["pick_id"]), []).append((leg["status"] or "open", leg["text"] or ""))
    for row in open_:
        sts = legmap.get(row["id"]) or []
        row["nlegs"] = len(sts)
        row["wait"] = sum(1 for st, _text in sts if st == "open")
        row["first"] = clip(sts[0][1], 80) if len(sts) == 1 else ""
        blob = " ".join([str(row.get("what") or "")] + [text for _st, text in sts]).lower()
        if re.search(r"\bdemon\b", blob):
            row["demon"] = 1
        if re.search(r"\bgoblin\b", blob):
            row["goblin"] = 1
    futures = []
    for p in db().execute("""SELECT * FROM picks WHERE guild_id = ? AND status = 'open'
                                        AND (hidden IS NULL OR hidden = 0)
                                        AND future_due IS NOT NULL AND future_due != ''
                                        AND (test IS NULL OR test = 0)
                                        ORDER BY future_due LIMIT 60""", (guild_id,)):
        if dashboard_hidden_pick(p):
            continue
        futures.append({"id": p["id"], "who": clip(p["bettor_name"], 40), "what": clip(shown_desc(p), 90),
                        "due": local_day(p["future_due"]) if p["future_due"] else "",
                        "cost": p["cost"], "payout": p["payout"]})
        if len(futures) >= 20:
            break
    r = gp_round(guild_id, create=False)
    gp = [{"who": x["user_name"], "leg": x["text"], "status": x["status"]}
          for x in (gp_legs(r["id"]) if r else [])
          if not dashboard_hidden_name(x["user_name"])]
    names = {}
    for p in db().execute("SELECT bettor_id, bettor_name FROM picks WHERE guild_id = ? AND bettor_id IS NOT NULL", (guild_id,)):
        names[p["bettor_id"]] = p["bettor_name"]
    for row in open_:
        logger = int(row.pop("logger", 0) or 0)
        bettor = int(row["key"]) if str(row.get("key") or "").isdigit() else 0
        if logger and bettor and logger != bettor:
            who = names.get(logger) or ""
            if who and who != row.get("who") and not dashboard_hidden_name(who):
                row["filer"] = clip(who, 40)
    coins = []
    coin_split: dict[int, tuple[int, int]] = {}
    try:
        for tx in db().execute("SELECT user_id, delta FROM coin_tx WHERE guild_id = ?", (guild_id,)):
            delta = int(tx["delta"] or 0)
            earned, spent = coin_split.get(tx["user_id"], (0, 0))
            if delta > 0:
                earned += delta
            elif delta < 0:
                spent += -delta
            coin_split[tx["user_id"]] = (earned, spent)
    except Exception:
        coin_split = {}
    for u in coins_top(guild_id, 30):
        who = names.get(u["user_id"], "Member")
        if dashboard_hidden_name(who):
            continue
        why = ""
        try:
            last = db().execute(
                "SELECT reason FROM coin_tx WHERE guild_id = ? AND user_id = ? ORDER BY id DESC LIMIT 1",
                (guild_id, u["user_id"])).fetchone()
            why = clip(last["reason"], 48) if last else ""
        except Exception:
            why = ""
        game = ""
        try:
            lastp = db().execute(
                """SELECT description, sport FROM picks WHERE guild_id = ? AND bettor_id = ? AND status != 'open'
                   ORDER BY settled_at DESC LIMIT 1""", (guild_id, u["user_id"])).fetchone()
            if lastp:
                game = clip(((lastp["sport"] or "") + " " + (lastp["description"] or "")).strip(), 48)
        except Exception:
            game = ""
        earned, spent = coin_split.get(u["user_id"], (0, 0))
        coins.append({"who": who, "coins": int(u["bal"]), "why": why, "game": game,
                      **({"earned": earned, "spent": spent} if earned and spent else {})})
        if len(coins) >= 10:
            break
    rec = dash30_safe_records(guild_id, records_embed(guild_id).description or "")
    record_lines = [re.sub(r"\*\*", "", line) for line in rec.split("\n")
                    if line and not dashboard_hidden_line(line)]
    markets = []
    for p in db().execute(
            """SELECT * FROM picks WHERE guild_id = ? AND status = 'open'
               AND (hidden IS NULL OR hidden = 0)
               AND (LOWER(COALESCE(platform,'')) = 'kalshi'
                    OR (kalshi_ticker IS NOT NULL AND kalshi_ticker != ''))
               ORDER BY id DESC LIMIT 40""", (guild_id,)):
        if dashboard_hidden_pick(p):
            continue
        markets.append({"id": p["id"], "who": clip(p["bettor_name"], 40), "what": clip(shown_desc(p), 80),
                        "platform": clip(p["platform"] or "Kalshi", 20),
                        "ticker": clip(p["kalshi_ticker"] or "", 32),
                        "side": clip(p["kalshi_side"] or "", 8)})
        if len(markets) >= 12:
            break
    visible_stats = [s for s in compute_stats(guild_id) if not dashboard_hidden_name(s.get("name"))]
    return {"version": BOT_VERSION, "update": ROADMAP_NOW, "season": season["name"] if season else None, "people": dashboard_people(guild_id),
            "settled24": dashboard_recent(guild_id),
            "settledWeek": dashboard_settled_week(guild_id),
            "lastSettle": dashboard_last_settle(guild_id),
            "leaderboard": board(season_stats(guild_id, season) if season else compute_stats(guild_id)),
            "alltime": board(compute_stats(guild_id)),
            "series": {k: [[x.astimezone(TZ).strftime("%Y-%m-%d %H:%M"), round(y, 2)] for x, y in v] for k, v in series.items()},
            "recent": recent, "open": open_, "futures": futures, "tickets": list(open_[:12]), "markets": markets,
            "commands": dash_commands(),
            "groupparlay": gp, "coins": coins,
            "records": record_lines,
            "roadmap": BOT_ROADMAP, "plan": BOT_PLAN, "later": BOT_LATER, "thousand": BOT_THOUSAND,
            "updates": [{"ver": v, "text": t} for v, t in reversed(MEMBER_NEWS[-5:])],
            "week": dash_this_week(guild_id),
            "netmode": "group" if get_setting(guild_id, "kpi_net") == "group" else "week",
            "groupnet": round(sum(s["net"] for s in visible_stats), 2),
            "h2h": dash_h2h_board(guild_id), "weekplays": dash_week_plays(guild_id),
            "weekboard": clip(get_setting(guild_id, "week_board") or "", 280),
            "booted": central_stamp(STARTED_AT),
            "books": [name for _pat, name in PLATFORM_WORDS],
            "sports": list(dict.fromkeys(LEAGUE_NAMES.values()))}


