VOICE: dict[int, dict] = {}
GREETINGS = {"default": "Pimp is in. Ask me about the games.",
             "hype": "LET'S GOOO! PIMP-BOT IS IN THE BUILDING! Who's cashing tonight?",
             "analyst": "PIMP-BOT connected. Monitoring open positions.",
             "trash": "Alright, I'm here. Try not to embarrass yourselves.",
             "announcer": "Good evening and welcome to tonight's sweat, brought to you by PIMP-BOT!"}
VOICE_MAX_HOURS = 8
# Neural voice, then a gTTS accent if that voice is unavailable. One male voice per mood.
TTS_VOICES = {
    "default": ("en-US-ChristopherNeural", "us"),
    "hype": ("en-US-GuyNeural", "com.au"),
    "analyst": ("en-GB-RyanNeural", "co.uk"),
    "trash": ("en-US-EricNeural", "ca"),
    "announcer": ("en-US-AndrewNeural", "ie"),
}
_TTS_PICK: contextvars.ContextVar = contextvars.ContextVar("tts_pick", default=TTS_VOICES["default"])


def voice_ready() -> tuple[bool, str]:
    """Whether this install can talk in voice, and what's missing if not."""
    try:
        import nacl  # noqa: F401
    except Exception:
        return False, "PyNaCl isn't installed (it comes with `discord.py[voice]` in requirements.txt)"
    try:
        import davey  # noqa: F401
    except Exception:
        return False, "the `davey` package isn't installed (Discord's encrypted voice needs it)"
    import shutil
    if not shutil.which("ffmpeg"):
        return False, "ffmpeg isn't installed (the included Dockerfile installs it)"
    try:
        if not discord.opus.is_loaded():
            discord.opus._load_default()
    except Exception:
        pass
    try:
        if not discord.opus.is_loaded():
            return False, "the opus audio library isn't installed (the included Dockerfile installs libopus0)"
    except Exception:
        pass
    return True, ""


def espeak_file(text: str, folder: str) -> str:
    """A local male voice. Empty string when espeak is not installed."""
    import subprocess
    exe = shutil.which("espeak-ng") or shutil.which("espeak")
    if not exe:
        return ""
    path = os.path.join(folder, "say.wav")
    spoken = (text or ".").lstrip("- ") or "."
    try:
        subprocess.run([exe, "-v", "en-us+m3", "-s", "150", "-w", path, spoken], check=True, timeout=20,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        try:
            subprocess.run([exe, "-s", "150", "-w", path, spoken], check=True, timeout=20,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            return ""
    if os.path.isfile(path) and os.path.getsize(path) > 44:
        return path
    return ""


def tts_to_file(text: str) -> str:
    """Speak text into a temp audio file. Neural voice first, then the local voice, then Google TTS.
    The caller deletes the file's folder."""
    folder = tempfile.mkdtemp()
    neural, tld = _TTS_PICK.get()
    path = os.path.join(folder, "say.mp3")
    try:
        import edge_tts

        async def _go():
            await asyncio.wait_for(edge_tts.Communicate(text, neural).save(path), timeout=5)
        asyncio.run(_go())
        if os.path.isfile(path) and os.path.getsize(path) > 1000:
            return path
    except Exception:
        log.warning("Neural voice failed; using the local voice")
    local = espeak_file(text, folder)
    if local:
        return local
    try:
        from gtts import gTTS
        gTTS(text=text, lang="en", tld=tld or "us").save(path)
        if os.path.isfile(path) and os.path.getsize(path) > 1000:
            return path
    except Exception:
        log.warning("Google voice failed", exc_info=True)
    shutil.rmtree(folder, ignore_errors=True)
    raise RuntimeError("no text-to-speech available (install espeak-ng or gTTS)")


def pcm_source(path: str):
    """Audio ffmpeg will actually play. -nostdin keeps it from waiting on a keyboard that isn't there."""
    import subprocess
    try:
        return discord.FFmpegPCMAudio(path, before_options="-nostdin", options="-vn", stderr=subprocess.DEVNULL)
    except TypeError:
        return discord.FFmpegPCMAudio(path)


def _stop_audio(vc) -> None:
    """Stop the current clip. Leave the microphone open when the hearing client has its own stop."""
    if vc is None or not getattr(vc, "is_playing", lambda: False)():
        return
    fn = getattr(vc, "stop_playing", None) or getattr(vc, "stop", None)
    if not fn:
        return
    try:
        fn()
    except Exception:
        pass


def _voice_finish(fut, err: str, st=None) -> None:
    if st is not None:
        st["last_error"] = err or ""
    if fut is not None and not getattr(fut, "done", lambda: True)():
        fut.set_result(err or "")


async def _wait_encrypt(vc) -> str:
    """Wait until call audio is sealed. Unsealed packets never reach the room."""
    state = getattr(vc, "_connection", None)
    if state is None or not hasattr(state, "can_encrypt"):
        return ""
    for _ in range(32):
        try:
            if state.can_encrypt:
                return ""
        except Exception:
            return ""
        await asyncio.sleep(0.25)
    try:
        if state.can_encrypt:
            return ""
    except Exception:
        return ""
    return "Discord has not finished the call encryption, so the room cannot hear me yet."


async def _play_path(vc, path: str) -> str:
    why = await _wait_encrypt(vc)
    if why:
        return why
    done = asyncio.Event()
    loop = asyncio.get_running_loop()
    failed = []

    def _after(err):
        if err:
            failed.append(err)
        loop.call_soon_threadsafe(done.set)

    _stop_audio(vc)
    try:
        vc.play(pcm_source(path), after=_after)
    except Exception as exc:
        return f"The player failed ({type(exc).__name__}: {exc})"[:220]
    try:
        await asyncio.wait_for(done.wait(), timeout=90)
    except asyncio.TimeoutError:
        _stop_audio(vc)
        return "The audio ran too long and was stopped."
    if failed:
        err = failed[0]
        return f"Playback failed ({type(err).__name__}: {err})"[:220]
    return ""


def speakable(text: str) -> str:
    t = re.sub(r"<a?:\w+:\d+>|<[@#&!]+\d+>|https?://\S+", "", text)
    t = re.sub(r"[*_`~>|#]", "", t)
    t = re.sub(r"[\U0001F000-\U0001FAFF☀-➿️]", "", t)
    t = re.sub(r"\$([\d,]+)(?:\.00\b)?(\.\d\d)?", lambda m: f"{m.group(1)}{m.group(2) or ''} dollars", t)
    t = t.replace("→", " to ").replace("$", "")
    return " ".join(t.split())[:300]


def spoken_take(text: str) -> str:
    """The first two sentences, cleaned for the voice channel."""
    raw = re.sub(r"(?im)^-#.*$|sources:.*$", "", text or "")
    t = speakable(raw)
    bits = [b.strip() for b in re.split(r"(?<=[.!?])\s+", t) if b.strip()]
    out, n = [], 0
    for b in bits:
        out.append(b)
        n += len(b)
        if len(out) >= 2 or n > 220:
            break
    return " ".join(out)[:280]


async def voice_answer(client, guild_id: int, text: str) -> bool:
    """Say the answer out loud when Pimp is already in this server's voice channel."""
    line = spoken_take(text)
    if not line:
        return False
    return await voice_say(client, guild_id, line)


async def _voice_worker(gid: int):
    st = VOICE.get(gid)
    while st is not None:
        item = await st["queue"].get()
        if isinstance(item, tuple):
            text, fut = item
        else:
            text, fut = item, None
        vc = st["vc"]
        for _ in range(40):   # ride out a voice reconnect instead of going silent for good
            if vc and vc.is_connected():
                break
            await asyncio.sleep(0.25)
        if not vc or not vc.is_connected():
            _voice_finish(fut, "I was in the channel, but the call dropped before I could speak.", st)
            st = VOICE.get(gid)
            continue
        paths = []
        err = ""
        try:
            _TTS_PICK.set(st.get("tts") or TTS_VOICES["default"])
            path = await asyncio.wait_for(asyncio.to_thread(tts_to_file, text), timeout=20)
            paths.append(path)
            err = await _play_path(vc, path)
            if err:
                log.warning("Voice line failed: %s", err)
                folder = tempfile.mkdtemp()
                wav = await asyncio.to_thread(espeak_file, text, folder)
                if wav and wav != path:
                    paths.append(wav)
                    err = await _play_path(vc, wav)
                    if err:
                        log.warning("Local voice failed too: %s", err)
        except Exception as exc:
            log.warning("Voice line failed", exc_info=True)
            err = f"The audio failed ({type(exc).__name__})."
        finally:
            if VOICE.get(gid) is st:
                st["quiet_until"] = time.monotonic() + 0.8
            for path in paths:
                if path and os.path.dirname(path) not in ("", "/", "/dev"):
                    shutil.rmtree(os.path.dirname(path), ignore_errors=True)
        _voice_finish(fut, err, st)
        if VOICE.get(gid) is st:
            st["last"] = time.monotonic()
        st = VOICE.get(gid)


def heard_command(text: str) -> Optional[tuple[str, str]]:
    """('wake', question) when a spoken line starts with a wake phrase. None when it does not."""
    t = " ".join((text or "").split())
    if not t or not wake_hit(t):
        return None
    return ("wake", wake_strip(t))


def hear_mode() -> str:
    """'on' when this install can hear the call, 'key' when a speech key is missing, 'package' otherwise."""
    try:
        from discord.ext import voice_recv  # noqa: F401
    except Exception:
        return "package"
    if not (GROQ_API_KEY or GEMINI_API_KEY):
        return "key"
    return "on"


def pcm_seconds(pcm: bytes) -> float:
    return len(pcm) / (48000 * 2 * 2)


def pcm_loud(pcm: bytes) -> bool:
    """True when the clip is speech, not a quiet room. Quiet audio makes a transcriber invent words."""
    if len(pcm) < 4000:
        return False
    step = max(2, (len(pcm) // 8000) * 2)
    acc = n = 0
    for i in range(0, len(pcm) - 1, step):
        v = int.from_bytes(pcm[i:i + 2], "little", signed=True)
        acc += v * v
        n += 1
    return n > 0 and (acc / n) ** 0.5 > 300


def pcm_wav(pcm: bytes) -> bytes:
    import wave
    bio = io.BytesIO()
    with wave.open(bio, "wb") as handle:
        handle.setnchannels(2)
        handle.setsampwidth(2)
        handle.setframerate(48000)
        handle.writeframes(pcm)
    return bio.getvalue()


_DAVE_HEAR = False


def install_dave_hear() -> bool:
    """Open call audio before it is turned into sound. Without this, he can talk and still hear nothing."""
    global _DAVE_HEAR
    if _DAVE_HEAR:
        return True
    try:
        import davey
        from discord.ext.voice_recv import opus as vr_opus
        from discord.ext.voice_recv.rtp import OPUS_SILENCE
        orig = vr_opus.PacketDecoder._decode_packet
    except Exception:
        log.warning("Voice hearing isn't available on this install")
        return False
    fails = {"n": 0}
    media = getattr(getattr(davey, "MediaType", None), "audio", None)

    def _decode(self, packet):
        if packet and len(getattr(packet, "decrypted_data", b"") or b"") > 3 and media is not None:
            vc = getattr(getattr(self, "sink", None), "voice_client", None)
            state = getattr(vc, "_connection", None)
            session = getattr(state, "dave_session", None)
            version = getattr(state, "dave_protocol_version", 0) or 0
            if session is not None and version > 0:
                user_id = getattr(self, "_cached_id", None)
                if not user_id and hasattr(vc, "_get_id_from_ssrc"):
                    try:
                        user_id = vc._get_id_from_ssrc(self.ssrc)
                    except Exception:
                        user_id = None
                try:
                    if not user_id:
                        raise LookupError("no speaker")
                    packet.decrypted_data = session.decrypt(int(user_id), media, packet.decrypted_data)
                except Exception as exc:
                    packet.decrypted_data = OPUS_SILENCE
                    fails["n"] += 1
                    if fails["n"] % 50 == 1:
                        log.warning("Voice decrypt missed a packet (%s)", type(exc).__name__)
        return orig(self, packet)

    vr_opus.PacketDecoder._decode_packet = _decode
    _DAVE_HEAR = True
    return True


class HearEar:
    """Keeps a few seconds of each person's speech. The clip is dropped after it is read."""

    def __init__(self, gid: int):
        self.gid = gid
        self.lock = threading.Lock()
        self.bufs: dict[int, bytearray] = {}
        self.last: dict[int, float] = {}
        self.names: dict[int, str] = {}

    def write(self, user, data) -> None:
        if user is None or getattr(user, "bot", False):
            return
        pcm = getattr(data, "pcm", None)
        if not pcm:
            return
        st = VOICE.get(self.gid) or {}
        now = time.monotonic()
        if now < st.get("quiet_until", 0):
            return
        vc = st.get("vc")
        if vc is not None and getattr(vc, "is_playing", lambda: False)():
            return
        uid = getattr(user, "id", None)
        if not uid:
            return
        name = getattr(user, "display_name", None) or getattr(user, "name", None) or "there"
        with self.lock:
            buf = self.bufs.setdefault(int(uid), bytearray())
            if pcm_seconds(buf) > 8:
                keep = int(48000 * 2 * 2 * 6)
                del buf[:-keep]
            buf.extend(pcm)
            self.last[int(uid)] = now
            self.names[int(uid)] = name

    def take_ready(self) -> list[tuple[int, str, bytes]]:
        now = time.monotonic()
        ready = []
        with self.lock:
            for uid, buf in list(self.bufs.items()):
                if now - self.last.get(uid, now) < 0.7:
                    continue
                pcm = bytes(buf)
                self.bufs.pop(uid, None)
                if pcm_seconds(pcm) < 0.45 or not pcm_loud(pcm):
                    continue
                ready.append((uid, self.names.get(uid) or "there", pcm))
        return ready


async def _hear_groq(wav: bytes) -> str:
    import aiohttp
    form = aiohttp.FormData()
    form.add_field("file", wav, filename="ear.wav", content_type="audio/wav")
    form.add_field("model", "whisper-large-v3-turbo")
    form.add_field("language", "en")
    form.add_field("response_format", "json")
    form.add_field("temperature", "0")
    timeout = aiohttp.ClientTimeout(total=12)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.post("https://api.groq.com/openai/v1/audio/transcriptions", data=form,
                                headers={"Authorization": f"Bearer {GROQ_API_KEY}"}) as resp:
            if resp.status != 200:
                log.warning("Hearing transcription failed: HTTP %s", resp.status)
                return ""
            data = await resp.json(content_type=None)
    return " ".join(str((data or {}).get("text") or "").split())


async def _hear_gemini(wav: bytes) -> str:
    import aiohttp
    body = {"contents": [{"parts": [
        {"text": "Transcribe the English speech. Reply with only the words spoken."},
        {"inline_data": {"mime_type": "audio/wav", "data": base64.standard_b64encode(wav).decode()}},
    ]}]}
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"
    timeout = aiohttp.ClientTimeout(total=14)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.post(url, json=body, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
            if resp.status != 200:
                log.warning("Hearing transcription failed: HTTP %s", resp.status)
                return ""
            data = await resp.json(content_type=None)
    parts = (((data.get("candidates") or [{}])[0].get("content") or {}).get("parts") or [])
    return " ".join(str(p.get("text") or "") for p in parts if isinstance(p, dict)).strip()


async def hear_text(pcm: bytes) -> str:
    """Turn one spoken clip into words, then drop the clip. Nothing is saved."""
    if not pcm_loud(pcm):
        return ""
    wav = pcm_wav(pcm)
    if GROQ_API_KEY:
        try:
            text = await _hear_groq(wav)
            if text:
                return text
        except Exception:
            log.warning("Hearing transcription failed", exc_info=True)
    if GEMINI_API_KEY:
        try:
            return await _hear_gemini(wav)
        except Exception:
            log.warning("Hearing transcription failed", exc_info=True)
    return ""


def _voice_listen(guild_id: int, st: dict) -> bool:
    """Start hearing this call. Speaking still works when this returns False."""
    vc = st.get("vc")
    if vc is None or not hasattr(vc, "listen") or st.get("ear"):
        return bool(st.get("ear"))
    if hear_mode() != "on" or not install_dave_hear():
        return False
    try:
        from discord.ext import voice_recv
        ear = HearEar(guild_id)
        st["ear"] = ear
        vc.listen(voice_recv.BasicSink(ear.write))
        if st.get("hear") is None or st["hear"].done():
            st["hear"] = asyncio.create_task(_hear_watch(guild_id))
        log.info("Voice hearing is on in guild %s", guild_id)
        return True
    except Exception:
        log.warning("Joined voice, but hearing failed", exc_info=True)
        st.pop("ear", None)
        return False


async def _say_in_room(guild_id: int, text: str) -> None:
    channel = (VOICE.get(guild_id) or {}).get("text")
    if channel is None or not text:
        return
    try:
        chunks = split_message(text)
        for chunk in chunks[:3]:
            await channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())
    except Exception:
        log.warning("Couldn't post the spoken answer")


async def answer_spoken(client, guild_id: int, user, question: str) -> None:
    """Answer a question spoken in the call, and say it out loud."""
    name = getattr(user, "display_name", None) or getattr(user, "name", None) or "there"
    uid = int(getattr(user, "id", 0) or 0)
    question = (question or "").strip()
    if not question:
        await voice_say(client, guild_id, _random.choice(WAKE_ACKS))
        return
    if not ask_enabled():
        await voice_say(client, guild_id, "Questions aren't switched on yet.")
        return
    gate = ask_gate(guild_id, uid) if uid else None
    if gate:
        await voice_say(client, guild_id, gate)
        return
    channel = (VOICE.get(guild_id) or {}).get("text")
    answer = None
    try:
        answer = assistant_board_answer(
            guild_id, str(uid), name, question, channel_id=getattr(channel, "id", None))
    except Exception:
        log.exception("Board answer failed")
        answer = None
    if not answer and question_is_weather(question):
        try:
            pack = await asyncio.wait_for(answer_weather(question), timeout=14)
        except Exception:
            pack = None
        if pack and pack.get("hours"):
            answer = weather_spoken(pack, rain_only=bool(re.search(r"\b(delay|delayed)\b", question, re.I)))
        else:
            answer = "I couldn't find that place."
    if not answer:
        user_text = f"Question from {name}: {question}"
        try:
            context = build_ask_context(guild_id, str(uid), question)
        except Exception:
            log.warning("Spoken context failed", exc_info=True)
            context = ""
        if context:
            user_text += "\n\nThe group's own data:\n" + context
        bot_name = getattr(getattr(client, "user", None), "display_name", None) or "Pimp"
        system = ASK_SYSTEM.format(bot_name=bot_name, today=datetime.now(TZ).strftime("%A, %B %d, %Y"))
        system += "\n\n" + pimp_voice_block(guild_id) + "\n"
        system += ("They asked out loud in the voice channel. Two to six sentences. Address them by name. "
                   "On a sports question, name the player, the number, or the game.")
        ctx = {"guild_id": guild_id, "asker_key": str(uid), "chart": None}
        token = ASK_DATA.set(ctx)
        try:
            searching = question_needs_search(question)
            got, sources = await asyncio.wait_for(
                ask_any(system, user_text, search=searching), timeout=18 if searching else 12)
            answer = got
            if sources and answer:
                answer += "\n\n-# Sources: " + " · ".join(f"<{u}>" for u in sources)
        except Exception:
            log.exception("Spoken question failed")
            answer = "I couldn't get an answer just now. Try again in a minute."
        finally:
            ASK_DATA.reset(token)
    spoken = spoken_take(answer or "")
    if spoken:
        await voice_say(client, guild_id, spoken)
    if answer:
        await _say_in_room(guild_id, f"**{name}:** {question}\n\n{answer}")


async def _hear_utterance(gid: int, uid: int, name: str, pcm: bytes) -> None:
    st = VOICE.get(gid)
    if not st or st.get("hearing"):
        return
    st["hearing"] = True
    try:
        text = await hear_text(pcm)
        st = VOICE.get(gid)
        if not st or not text:
            return
        cmd = heard_command(text)
        opens = st.setdefault("open_ears", {})
        if cmd is None:
            if time.monotonic() > opens.get(uid, 0):
                return
            question = text
            opens.pop(uid, None)
        else:
            question = cmd[1]
            if not question:
                opens[uid] = time.monotonic() + 12
                await voice_say(st.get("client"), gid, _random.choice(WAKE_ACKS))
                return
            opens.pop(uid, None)
        log.info("Heard a wake phrase from %s", name)
        user = type("Speaker", (), {"id": uid, "display_name": name, "bot": False})()
        await answer_spoken(st.get("client"), gid, user, question)
    except Exception:
        log.warning("Hearing a line failed", exc_info=True)
    finally:
        live = VOICE.get(gid)
        if live is not None:
            live["hearing"] = False


async def _hear_watch(gid: int) -> None:
    try:
        while gid in VOICE:
            await asyncio.sleep(0.3)
            st = VOICE.get(gid)
            ear = st.get("ear") if st else None
            if ear is None:
                continue
            for uid, name, pcm in ear.take_ready():
                asyncio.create_task(_hear_utterance(gid, uid, name, pcm))
    except asyncio.CancelledError:
        return


def voice_missing(channel) -> str:
    """Connect or Speak missing on this channel. Empty string when the role can talk, or when we cannot tell."""
    guild = getattr(channel, "guild", None)
    me = getattr(guild, "me", None) if guild is not None else None
    if me is None or not hasattr(channel, "permissions_for"):
        return ""
    try:
        perms = channel.permissions_for(me)
    except Exception:
        return ""
    missing = []
    if not getattr(perms, "connect", True):
        missing.append("Connect")
    if not getattr(perms, "speak", True):
        missing.append("Speak")
    if not missing:
        return ""
    return ("I need " + " and ".join(missing) + " on my role in this channel. "
            "Channel settings, Permissions, PIMP-BOT, turn those on.")


def voice_muted(channel) -> str:
    me = getattr(getattr(channel, "guild", None), "me", None)
    vs = getattr(me, "voice", None)
    if getattr(vs, "mute", False):
        return "I'm in the channel, but Discord has me muted. Right-click PIMP-BOT in the call and unmute me."
    return ""


async def _channel_connect(channel):
    """Join able to talk. Hearing is extra, and a hearing failure still leaves him in the call."""
    base = {"self_deaf": False, "self_mute": False}
    recv_cls = None
    try:
        from discord.ext import voice_recv
        recv_cls = voice_recv.VoiceRecvClient
    except Exception:
        recv_cls = None
    if recv_cls is not None:
        try:
            return await channel.connect(cls=recv_cls, **base)
        except Exception:
            log.warning("Hearing connect failed; joining so I can still talk", exc_info=True)
    return await channel.connect(**base)


async def voice_join(guild_id: int, channel, text=None, client=None) -> str:
    ok, why = voice_ready()
    if not ok:
        return f"I can't talk in voice on this install: {why}."
    missing = voice_missing(channel)
    if missing:
        return missing
    st = VOICE.get(guild_id)
    try:
        if st and st["vc"].is_connected():
            await st["vc"].move_to(channel)
        else:
            vc = await _channel_connect(channel)
            st = {"vc": vc, "queue": asyncio.Queue(), "joined": time.monotonic(), "last": time.monotonic()}
            VOICE[guild_id] = st
            st["task"] = asyncio.create_task(_voice_worker(guild_id))
        if text is not None:
            st["text"] = text
        if client is not None:
            st["client"] = client
        kind = str(getattr(getattr(channel, "type", None), "name", "") or "")
        me = getattr(getattr(channel, "guild", None), "me", None)
        if "stage" in kind and me is not None and hasattr(me, "request_to_speak"):
            try:
                await me.request_to_speak()
            except Exception:
                log.warning("Couldn't ask to speak on the stage")
        _voice_listen(guild_id, st)
    except Exception as exc:
        log.exception("Voice connect failed")
        detail = f"{type(exc).__name__}: {exc}"
        return ("I couldn't join voice (" + detail[:160] + "). "
                "I need Connect and Speak on my role in that channel.")
    muted = voice_muted(channel)
    if muted:
        return muted
    return ""


async def voice_leave(guild_id: int) -> bool:
    st = VOICE.pop(guild_id, None)
    if not st:
        return False
    fut = st.get("last_fut")
    if fut is not None and not fut.done():
        fut.set_result("I left the call.")
    for key in ("hear", "task"):
        job = st.get(key)
        if job:
            job.cancel()
    vc = st.get("vc")
    try:
        if vc is not None and hasattr(vc, "stop_listening"):
            vc.stop_listening()
    except Exception:
        pass
    try:
        if vc is not None:
            await vc.disconnect(force=True)
    except Exception:
        pass
    return True


async def pull_up(message, client=None) -> str:
    """Join the author's voice channel so the next line can be said. Empty string when he is in."""
    guild = getattr(message, "guild", None)
    if guild is None:
        return "no server"
    channel = getattr(getattr(getattr(message, "author", None), "voice", None), "channel", None)
    if channel is not None:
        return await voice_join(guild.id, channel, text=getattr(message, "channel", None), client=client)
    st = VOICE.get(guild.id)
    vc = st.get("vc") if st else None
    if vc is not None and vc.is_connected():
        if st is not None and getattr(message, "channel", None) is not None:
            st["text"] = message.channel
        if st is not None and client is not None:
            st["client"] = client
        return ""
    return "not in a voice channel"


async def voice_say(client, guild_id: int, text: str) -> bool:
    st = VOICE.get(guild_id)
    if not st or not st.get("vc"):
        return False
    line = speakable(text)
    if not line:
        return False
    st["tts"] = TTS_VOICES.get(persona(guild_id), TTS_VOICES["default"])
    if st.get("task") is None or st["task"].done():
        st["task"] = asyncio.create_task(_voice_worker(guild_id))
    if st["queue"].qsize() >= 6:
        return False
    fut = asyncio.get_running_loop().create_future()
    st["last_fut"] = fut
    st["queue"].put_nowait((line, fut))
    return True


async def voice_wait(guild_id: int, timeout: float = 22) -> str:
    """Empty string when the latest line finished. Otherwise the reason the room heard nothing."""
    st = VOICE.get(guild_id)
    if not st:
        return "I'm not in the call."
    fut = st.get("last_fut")
    if fut is None:
        return st.get("last_error") or ""
    try:
        return await asyncio.wait_for(asyncio.shield(fut), timeout)
    except asyncio.TimeoutError:
        return "The audio did not finish. I need Speak on my role in that channel."


def voice_humans(vc) -> list:
    """People in his voice channel. Bots, including him, do not count."""
    channel = getattr(vc, "channel", None)
    me = getattr(getattr(vc, "guild", None), "me", None)
    my_id = getattr(me, "id", None)
    out = []
    for m in list(getattr(channel, "members", []) or []):
        if getattr(m, "bot", False) or (my_id and getattr(m, "id", None) == my_id):
            continue
        their = getattr(getattr(m, "voice", None), "channel", None)
        if their is not None and their is not channel:
            continue
        out.append(m)
    return out


async def voice_idle(client: discord.Client, now: Optional[datetime] = None) -> None:
    """Leave once the channel has been empty of people for a short moment, or the shift is over."""
    for gid, st in list(VOICE.items()):
        vc = st["vc"]
        if not vc.is_connected() or time.monotonic() - st["joined"] > VOICE_MAX_HOURS * 3600:
            await voice_leave(gid)
            continue
        if voice_humans(vc):
            st.pop("empty_since", None)
            continue
        st.setdefault("empty_since", time.monotonic())
        if time.monotonic() - st["empty_since"] > 20:
            await voice_leave(gid)


