def _athlete_hand(ath: dict) -> str:
    """Bats, throws, or hand, only when the athlete page already has that field."""
    bits = []
    for key, label in (("bats", "Bats"), ("throws", "Throws"), ("hand", "Hand")):
        obj = ath.get(key)
        val = ""
        if isinstance(obj, dict):
            val = str(obj.get("abbreviation") or obj.get("displayValue") or "").strip()
        elif isinstance(obj, str):
            val = obj.strip()
        if not val or val.lower() in {"none", "null"}:
            continue
        if key == "hand" and bits:
            continue
        bits.append(clip(f"{label} {val}", 20))
    return " · ".join(bits)


def _athlete_conference(path: str, team: dict, ath: dict) -> str:
    """A conference name only on a college path, and only when the bio already has one."""
    if "college" not in (path or ""):
        return ""
    for src in (team, ath):
        if not isinstance(src, dict):
            continue
        for key in ("conference", "conferenceName"):
            raw = src.get(key)
            if isinstance(raw, dict):
                raw = raw.get("shortName") or raw.get("abbreviation") or raw.get("name") or raw.get("displayName") or ""
            if isinstance(raw, str) and raw.strip() and raw.strip().lower() not in {"none", "null"}:
                return clip(raw.strip(), 24)
    return ""


async def espn_athlete_bio(path: str, aid: str) -> dict:
    """Jersey, size, age, home team from ESPN's athlete page. Empty dict when ESPN didn't answer."""
    key = (path, str(aid))
    hit = _BIO_CACHE.get(key)
    if hit and hit[0] > time.monotonic():
        return dict(hit[1])
    try:
        raw = await _get_json(ESPN_ATHLETE.format(path=path, athlete_id=aid), {})
    except Exception:
        raw = {}
    ath = raw.get("athlete") if isinstance(raw, dict) else None
    if not isinstance(ath, dict):
        ath = raw if isinstance(raw, dict) else {}
    team = ath.get("team") if isinstance(ath.get("team"), dict) else {}
    pos = ath.get("position") if isinstance(ath.get("position"), dict) else {}
    jersey = str(ath.get("jersey") or "").lstrip("#")[:4]
    out = {
        "name": clip(str(ath.get("displayName") or ath.get("fullName") or ""), 40),
        "jersey": jersey if jersey.isdigit() else "",
        "height": clip(str(ath.get("displayHeight") or ""), 12),
        "weight": clip(str(ath.get("displayWeight") or ""), 12),
        "age": str(ath.get("age") or "")[:3],
        "pos": clip(str(pos.get("abbreviation") or pos.get("displayName") or ""), 8),
        "team": clip(str(team.get("displayName") or team.get("name") or ""), 40),
        "abbr": clip(str(team.get("abbreviation") or ""), 8),
        "hand": _athlete_hand(ath),
        "conference": _athlete_conference(path, team, ath),
    }
    _BIO_CACHE[key] = (time.monotonic() + (600 if out.get("name") else 45), out)
    if len(_BIO_CACHE) > 400:
        cut = time.monotonic()
        for k, (exp, _) in list(_BIO_CACHE.items()):
            if exp < cut:
                _BIO_CACHE.pop(k, None)
    return dict(out)


def path_from_league_slug(slug: str) -> Optional[str]:
    s = str(slug or "").lower().strip()
    if not s or len(s) > 28:
        return None
    for path, v in LEAGUE_SLUGS.items():
        if v == s or path.endswith("/" + s):
            return path
    return None


def dash_player_keys(path: str) -> list[str]:
    fam = FAMILY_OF_PATH.get(path) or ""
    keys = [k for k in (MAIN_STATS.get(fam) or []) if k in STATS]
    if fam == "football":
        for k in ("rush_att", "pass_att", "targets", "sacks", "tackles", "fg_made", "kick_pts"):
            if k in STATS and k not in keys:
                keys.append(k)
    return keys


_PITCH_POS = {"p", "sp", "rp", "cp", "lhp", "rhp"}
_GOALIE_POS = {"g", "gk"}


def dash_sheet_keys(path: str, pos: str) -> list[str]:
    """Stat chips for this sheet. Hitters and pitchers stay apart. Skaters and goalies stay apart."""
    fam = FAMILY_OF_PATH.get(path) or ""
    p = (pos or "").strip().lower()
    if fam == "baseball":
        want = (["pitcher_k", "pitching_outs", "earned_runs", "hits_allowed", "walks_allowed"] if p in _PITCH_POS
                else ["hits", "hrr", "home_runs", "rbis", "runs", "walks", "hitter_k"])
        return [k for k in want if k in STATS]
    if fam == "hockey":
        want = (["saves", "nhl_goals_allowed"] if p in _GOALIE_POS else
                ["goals", "nhl_assists", "nhl_points", "sog", "shots", "blocked_shots", "nhl_hits", "faceoffs"])
        return [k for k in want if k in STATS]
    return dash_player_keys(path)


def dash_event_score(m: dict) -> str:
    """Final score from an ESPN game-log event, when the feed included one."""
    if not isinstance(m, dict):
        return ""
    raw = re.sub(r"\s+", " ", str(m.get("score") or "")).strip()
    if raw and raw.lower() not in {"none", "null"}:
        return clip(raw, 18)
    opp = m.get("opponent") if isinstance(m.get("opponent"), dict) else {}
    team = m.get("team") if isinstance(m.get("team"), dict) else {}
    ours = str((team or {}).get("score") or "").strip()
    theirs = str((opp or {}).get("score") or "").strip()
    if ours.isdigit() and theirs.isdigit():
        return clip(f"{ours}-{theirs}", 18)
    return ""


def dash_game_when(g: dict) -> str:
    raw = g.get("date") or ""
    if not raw:
        return ""
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00")).astimezone(TZ).strftime("%b %-d")
    except Exception:
        return ""


def dash_pack_games(games: list, keys: list[str], limit: int = 20) -> list[dict]:
    """Last N games with the projection stats already numbered, no raw ESPN groups."""
    out = []
    for g in games[:limit]:
        groups = g.get("groups") or {}
        vals = {}
        for k in keys:
            try:
                got = stat_value(groups, k)
            except Exception:
                got = None
            if got is not None:
                vals[k] = round(got[0], 1)
        result = str(g.get("result") or "")
        label = str(g.get("label") or "")
        out.append({"date": g.get("date") or "", "when": dash_game_when(g),
                    "opp": clip(str(g.get("opp") or "?"), 8),
                    "opp_name": clip(str(g.get("opp_name") or ""), 32),
                    "at": "@" if g.get("at") == "@" else "vs",
                    "result": clip(result, 12), "score": clip(str(g.get("score") or ""), 18),
                    "vals": vals,
                    "pre": bool(g.get("preseason")),
                    "ot": "OT" in result.upper() or "OT" in label.upper(),
                    "dnp": not vals})
    return out


def dash_pack_stats(games_payload: list, keys: list[str]) -> list[dict]:
    out = []
    for k in keys:
        vals = [g["vals"][k] for g in games_payload if k in (g.get("vals") or {}) and not g.get("pre")]
        if not vals:
            continue

        def avg(n, rows=vals):
            part = rows[:n]
            return round(sum(part) / len(part), 1) if part else 0.0

        out.append({"key": k, "label": STATS[k][0], "last": round(vals[0], 1),
                    "avg5": avg(5), "avg10": avg(10), "avg20": avg(20), "n": len(vals),
                    "line": default_line(vals[:10])})
    out.sort(key=lambda s: (s["key"] == "minutes", -s["n"]))
    return out


def dash_with_without(player_games: list, teammate_games: list, stat_key: str) -> Optional[dict]:
    """This player's stat in games the teammate also logged vs games they did not."""
    days = {(g.get("date") or "")[:10] for g in (teammate_games or []) if g.get("date")}
    if not days or not stat_key:
        return None
    with_v, without_v = [], []
    for g in player_games or []:
        try:
            got = stat_value(g.get("groups") or {}, stat_key)
        except Exception:
            got = None
        if got is None:
            continue
        day = (g.get("date") or "")[:10]
        (with_v if day in days else without_v).append(got[0])
    out: dict = {}
    if without_v:
        out["without"] = round(sum(without_v) / len(without_v), 1)
        out["wn"] = len(without_v)
    if with_v:
        out["with"] = round(sum(with_v) / len(with_v), 1)
        out["hn"] = len(with_v)
    return out or None


def dash_ww_line(ww: Optional[dict], who: str = "") -> str:
    if not ww or (ww.get("without") is None and ww.get("with") is None):
        return "No recent games apart to compare"
    label = who or "them"
    bits = []
    if ww.get("without") is not None:
        bits.append(f"Without {label}: {ww['without']:g} in {int(ww.get('wn') or 0)}")
    if ww.get("with") is not None:
        bits.append(f"with {label}: {ww['with']:g} in {int(ww.get('hn') or 0)}")
    return " · ".join(bits)


def dash_last_recap(packed: list, keys: list[str]) -> str:
    if not packed:
        return ""
    g = packed[0]
    bits = []
    for k in keys:
        if k in (g.get("vals") or {}) and k in STATS:
            bits.append(f"{STATS[k][0]} {g['vals'][k]:g}")
            if len(bits) >= 3:
                break
    match = f"{g.get('at') or 'vs'} {g.get('opp') or '?'}"
    when = g.get("when") or ""
    head = " ".join(x for x in ("Last game", when, match) if x).strip()
    if bits:
        return head + ": " + ", ".join(bits) + "."
    return head + "." if head else ""


def dash_schedule_gap(last_iso: str, nxt) -> Optional[int]:
    """Days between the last logged game and the next one, minus the game day. 0 is a back-to-back."""
    if not last_iso or nxt is None:
        return None
    try:
        last = datetime.fromisoformat(str(last_iso).replace("Z", "+00:00"))
        if last.tzinfo is None:
            last = last.replace(tzinfo=timezone.utc)
        return (nxt.astimezone(TZ).date() - last.astimezone(TZ).date()).days - 1
    except Exception:
        return None


def dash_rest_days(last_iso: str, nxt) -> Optional[int]:
    """Days off between the last logged game and the next one. None when the schedule has no gap."""
    gap = dash_schedule_gap(last_iso, nxt)
    return gap if gap is not None and gap >= 1 else None


def dash_team_hit(label: str, team: dict) -> bool:
    return team_matches(label, team)


def dash_score_bit(v) -> str:
    try:
        n = float(v)
    except (TypeError, ValueError):
        return ""
    return str(int(n)) if n == int(n) else str(round(n, 1))


async def dash_opp_last(path: str, team: dict) -> str:
    """One line for the opponent's most recent final on this league's scoreboard."""
    if not path or not isinstance(team, dict):
        return ""
    label = str(team.get("abbr") or team.get("short") or team.get("name") or "")
    if not label:
        return ""
    now = datetime.now(TZ)
    for offset in range(1, 6):
        try:
            events = await fetch_scoreboard(path, now - timedelta(days=offset))
        except Exception:
            continue
        for ev in events or []:
            if not ev.get("final"):
                continue
            teams = ev.get("teams") or []
            if len(teams) != 2:
                continue
            hit = next((i for i, t in enumerate(teams) if dash_team_hit(label, t)), None)
            if hit is None:
                continue
            me, them = teams[hit], teams[1 - hit]
            a, b = dash_score_bit(me.get("score")), dash_score_bit(them.get("score"))
            if not a or not b:
                continue
            try:
                af, bf = float(me["score"]), float(them["score"])
            except (TypeError, ValueError, KeyError):
                continue
            verb = "beat" if af > bf else "lost to" if af < bf else "tied"
            return f"{me.get('abbr') or label} {verb} {them.get('abbr') or '?'} {a}–{b}"
    return ""


_BRIEF_FACTS: dict = {}


def brief_facts_get(key):
    hit = _BRIEF_FACTS.get(key)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    return None


def brief_facts_put(key, facts: dict) -> None:
    _BRIEF_FACTS[key] = (time.monotonic() + 600, facts)


async def _dash_brief_facts(path: str, name: str, team: str, abbr: str, packed: list) -> dict:
    """Next game and the out list. Weather cannot block the injuries. Indoor venues skip the forecast."""

    async def _ng():
        try:
            return await next_game(team or abbr, [path] if path else [])
        except Exception:
            return None

    async def _inj():
        global _INJURY_MAX_AGE
        old = _INJURY_MAX_AGE
        _INJURY_MAX_AGE = 300
        try:
            return await fetch_injuries(path)
        except Exception:
            return {}
        finally:
            _INJURY_MAX_AGE = old

    async def _raw():
        try:
            return await cached_json(ESPN_INJURIES.format(path=path), {}, 900)
        except Exception:
            return {}

    ng_task = asyncio.create_task(_ng())
    inj_task = asyncio.create_task(_inj())
    raw_task = asyncio.create_task(_raw())
    ng = await ng_task
    nxt, weather_task, sub = None, None, ""
    if ng:
        _pth, ev, idx = ng
        teams = ev.get("teams") or []
        other = teams[1 - idx] if len(teams) == 2 else {}
        opp = clip(str(other.get("abbr") or other.get("short") or ""), 8)
        away = next((t for t in teams if not t.get("home")), teams[0] if teams else {})
        home = next((t for t in teams if t.get("home")), teams[-1] if teams else {})
        line = f"{away.get('short') or '?'} @ {home.get('short') or '?'}"
        when = event_time(ev)
        if when:
            line += f" · {when.astimezone(TZ):%a %-I:%M %p} Central · group default"
        v = ev.get("venue") or {}
        sub = v.get("name") or ""
        if v.get("indoor"):
            sub = (sub + " · indoors") if sub else "indoors"
        elif when and v.get("city") and ev.get("state") == "pre":
            weather_task = asyncio.create_task(kickoff_weather(v.get("city") or "", v.get("state") or "", when))
        me = teams[idx] if 0 <= idx < len(teams) else {}
        ha = "home" if me.get("home") else "away"
        ct = when.astimezone(TZ).strftime("%a %-I:%M %p") if when else ""
        postponed = "postpon" in f"{ev.get('detail') or ''} {ev.get('status_name') or ''}".lower()
        nxt = {"line": clip(line, 120), "sub": clip(sub, 90), "opp": opp,
               "ha": ha, "ct": ct, "postponed": postponed}
        gap = dash_schedule_gap((packed[0].get("date") if packed else "") or "", when)
        if gap == 0:
            nxt["b2b"] = "Back-to-back"
        elif gap is not None and gap >= 1:
            nxt["rest"] = "Rest" if gap == 1 else f"Rest · {gap} days"
        try:
            last_line = await asyncio.wait_for(dash_opp_last(_pth, other), 2)
        except Exception:
            last_line = ""
        if last_line:
            nxt["opp_last"] = clip(last_line, 80)
    inj_map, raw = await asyncio.gather(inj_task, raw_task)
    ids_by_name: dict[str, str] = {}
    team_nn = norm_team(team or "")
    for tm in (raw.get("injuries") or []) if isinstance(raw, dict) else []:
        if team_nn and norm_team(tm.get("displayName") or "") != team_nn:
            continue
        for inj in tm.get("injuries") or []:
            if not isinstance(inj, dict):
                continue
            ath = inj.get("athlete") or {}
            nm, aid = ath.get("displayName") or "", str(ath.get("id") or "")
            if nm and aid.isdigit():
                ids_by_name[norm_name(nm)] = aid
    mine = norm_name(name)
    active_note, mates = "", []
    for rec in (inj_map or {}).values():
        if team_nn and norm_team(rec.get("team") or "") != team_nn:
            continue
        status = str(rec.get("status") or "")
        if norm_name(rec.get("name") or "") == mine:
            if status.lower() == "active" and rec.get("comment"):
                active_note = rec["comment"]
            elif status.lower() != "active":
                mates.insert(0, rec)
            continue
        if status.lower() == "active":
            continue
        mates.append(rec)
    shown = []
    for rec in mates[:12]:
        tid = ids_by_name.get(norm_name(rec.get("name") or "")) or ""
        shown.append({"name": rec.get("name") or "", "status": str(rec.get("status") or ""), "tid": tid})
    return {"next": nxt, "active_note": active_note, "mates": shown}, weather_task, sub


def dash_group_open_line(gid: int, name: str) -> str:
    """The line on an open, visible slip for this player. Empty once that slip is settled or hidden."""
    who = norm_name(name or "")
    if not gid or not who:
        return ""
    rows = db().execute(
        """SELECT l.text FROM legs l JOIN picks p ON p.id = l.pick_id
           WHERE p.guild_id = ? AND p.status = 'open' AND l.status = 'open'
             AND COALESCE(p.hidden, 0) = 0 AND COALESCE(p.test, 0) = 0""",
        (gid,)).fetchall()
    found: list[float] = []
    for r in rows:
        prop = prop_of(r["text"] or "")
        if not prop or prop.get("kind") != "prop":
            continue
        if who not in {norm_name(prop.get("display") or ""), norm_name(prop.get("player") or "")}:
            continue
        try:
            found.append(float(prop.get("line")))
        except (TypeError, ValueError):
            continue
    if not found:
        return ""
    best = max(set(found), key=found.count)
    return f"{best:g}"


async def dash_player_brief(path: str, name: str, team: str, abbr: str, games: list,
                            packed: list, keys: list[str], gid: int, stat_key: str,
                            fresh: bool = False) -> dict:
    """Next game, injuries, group hit/miss. Line math stays on the phone. Facts cache for ten minutes."""
    fact_key = (path, norm_name(name), norm_team(team or abbr))
    facts = None if fresh else brief_facts_get(fact_key)
    weather_task, venue_sub = None, ""
    if facts is None:
        facts, weather_task, venue_sub = await _dash_brief_facts(path, name, team, abbr, packed)
    nxt = facts.get("next")
    active_note = facts.get("active_note") or ""
    mates = facts.get("mates") or []
    jobs = [(m, m.get("tid") or "") for m in mates if m.get("tid") and stat_key]

    async def _one(mate, tid):
        who = norm_name(mate.get("name") or "")
        try:
            tg = await trend_games(path, tid, need=16)
            return who, dash_with_without(games, tg, stat_key)
        except Exception:
            return who, None

    async def _ww():
        if not jobs:
            return {}
        try:
            got = await asyncio.wait_for(asyncio.gather(*(_one(m, t) for m, t in jobs)), 6)
            return {k: v for k, v in got}
        except Exception:
            return {}

    async def _wx():
        if weather_task is None:
            return None
        try:
            return await asyncio.wait_for(weather_task, 3)
        except Exception:
            if not weather_task.done():
                weather_task.cancel()
            return None

    ww_map, w = await asyncio.gather(_ww(), _wx())
    if w and nxt is not None:
        nxt["sub"] = clip(((venue_sub + " · ") if venue_sub else "") + weather_line(w), 90)
    if weather_task is not None or fresh or brief_facts_get(fact_key) is None:
        brief_facts_put(fact_key, facts)

    injuries = []
    if active_note:
        injuries.append({"name": "Last game", "status": "", "note": clip(active_note, 420), "ww": None})
    else:
        recap = dash_last_recap(packed, keys)
        if recap:
            injuries.append({"name": "Last game", "status": "", "note": clip(recap, 420), "ww": None})
    for mate in mates:
        who = clip(mate.get("name") or "", 40)
        key = norm_name(mate.get("name") or "")
        if not mate.get("tid"):
            note = "Split unavailable"
            ww = None
        else:
            ww = ww_map.get(key)
            note = dash_ww_line(ww, who)
        injuries.append({"name": who, "status": clip(str(mate.get("status") or ""), 24),
                         "note": clip(note, 160), "ww": ww})

    group = None
    if gid:
        try:
            grp = run_group_stats(gid, "0", {"player": name})
            rows = grp.get("groups") or []
            if rows:
                g0 = rows[0]
                group = {"hit": int(g0.get("hit") or 0), "miss": int(g0.get("miss") or 0)}
        except Exception:
            group = None
    open_line = ""
    if gid and name:
        try:
            open_line = dash_group_open_line(gid, name)
        except Exception:
            open_line = ""
    return {"next": nxt, "injuries": injuries, "group": group, "openLine": open_line}


def _png_square(png: bytes, size: int) -> bool:
    """True when these bytes are a PNG whose width and height are both `size`."""
    if not png or not png.startswith(b"\x89PNG\r\n\x1a\n") or len(png) < 24:
        return False
    return int.from_bytes(png[16:20], "big") == size and int.from_bytes(png[20:24], "big") == size


def design_face_file(raw: bytes, size: int = 72) -> tuple:
    """(bytes, content-type). Always a square of `size`, never the original headshot."""
    size = 120 if int(size) == 120 else 72
    for make in (design_head_web_png, design_head_box_png, _design_plain_square):
        try:
            png = make(raw, size) or b""
        except Exception:
            png = b""
        if _png_square(png, size):
            return png, "image/png"
    return b"", ""


def espn_face_url(league, aid, size: int = 72) -> str:
    """ESPN's own square crop. The browser loads this itself. Nothing is fetched or cropped here."""
    league = str(league or "")
    aid = str(aid or "")
    size = 120 if int(size) == 120 else 72
    if not league or not aid.isdigit() or not design_headshot_url(f"{league}:{aid}"):
        return ""
    return (f"https://a.espncdn.com/combiner/i?img=/i/headshots/{league}/players/full/{aid}.png"
            f"&w={size}&h={size}&scale=crop")


async def dash_face_data(league, aid, size: int = 72) -> str:
    """The square face address. No download, so a missed server fetch cannot turn the box into an initial."""
    return espn_face_url(league, aid, size)


async def dash_team_roster(q: str) -> list[dict]:
    """Players on the team when the query is that team's name. Empty when it isn't a team we know."""
    nq = norm_team(q)
    if len(nq) < 3:
        return []
    try:
        raw = await asyncio.wait_for(_get_json(ESPN_SEARCH, {"query": q, "limit": 5, "type": "team"}), 3)
    except Exception:
        return []
    items = raw.get("items") if isinstance(raw, dict) else None
    hit = None
    for it in items or []:
        if not isinstance(it, dict):
            continue
        name = norm_team(it.get("displayName") or "")
        nick = norm_team(it.get("name") or "")
        abbr = norm_team(it.get("abbreviation") or "")
        if nq == name or nq == nick or nq == abbr or (name.endswith(" " + nq) and nick):
            hit = it
            break
    if not hit:
        return []
    slug = str(hit.get("defaultLeagueSlug") or hit.get("league") or "").lower()
    path = path_from_league_slug(slug)
    tid = str(hit.get("id") or "")
    if not path or not tid.isdigit():
        return []
    try:
        roster = await asyncio.wait_for(
            _get_json(f"https://site.api.espn.com/apis/site/v2/sports/{path}/teams/{tid}/roster", {}), 3)
    except Exception:
        return []
    blocks = roster.get("athletes") if isinstance(roster, dict) else None
    flat = []
    for block in blocks or []:
        if not isinstance(block, dict):
            continue
        if isinstance(block.get("items"), list):
            flat.extend(x for x in block["items"] if isinstance(x, dict))
        elif block.get("displayName") or block.get("id"):
            flat.append(block)
    league_slug = design_head_league(path) or slug
    team_name = clip(str(hit.get("displayName") or ""), 40)
    abbr_out = clip(str(hit.get("abbreviation") or ""), 8)
    out = []
    for ath in flat:
        aid = str(ath.get("id") or "")
        name = str(ath.get("displayName") or ath.get("fullName") or "")
        if not aid.isdigit() or not name:
            continue
        pos = ath.get("position") if isinstance(ath.get("position"), dict) else {}
        jersey = str(ath.get("jersey") or "").lstrip("#")[:4]
        out.append({"id": aid, "slug": league_slug, "path": path, "name": clip(name, 40),
                    "team": team_name, "abbr": abbr_out,
                    "league": clip(path.split("/")[-1].replace("-", " ").upper(), 24),
                    "pos": clip(str(pos.get("abbreviation") or pos.get("displayName") or ""), 8),
                    "jersey": jersey if jersey.isdigit() else "",
                    "height": "", "weight": "", "age": "",
                    "photo": espn_face_url(league_slug, aid), "stats": []})
        if len(out) >= 4:
            break
    return out


async def dash_api_player(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    q = clip(str(request.query.get("q") or "").strip(), 40)
    if len(q) < 3:
        return web.json_response({"q": q, "players": []})
    out = []
    try:
        found = await espn_search_players(q, list(LEAGUE_SLUGS))
    except Exception:
        found = []
    for f in (found or [])[:4]:
        fam = FAMILY_OF_PATH.get(f.get("path") or "") or ""
        keys = [k for k in (MAIN_STATS.get(fam) or []) if k in STATS][:4]
        stats = []
        async def _games():
            try:
                return await trend_games(f["path"], f["id"], need=8)
            except Exception:
                return []
        async def _bio():
            try:
                return await espn_athlete_bio(f["path"], f["id"])
            except Exception:
                return {}
        league = design_head_league(f.get("path"))
        aid = str(f.get("id") or "")
        photo = espn_face_url(league, aid)
        try:
            games, bio, photo = await asyncio.wait_for(
                asyncio.gather(_games(), _bio(), dash_face_data(league, aid)), 4)
        except Exception:
            games, bio = [], {}
        try:
            for k in keys:
                rows = trend_values(games, k)
                if not rows:
                    continue
                vals = [v for _, v in rows[:8]]
                stats.append({"stat": STATS[k][0], "last": round(vals[0], 1), "avg": round(sum(vals) / len(vals), 1),
                              "n": len(vals)})
        except Exception:
            pass
        out.append({"id": aid, "slug": league or "", "path": f.get("path") or "",
                    "name": clip(f.get("name") or bio.get("name") or "", 40),
                    "team": clip(bio.get("team") or f.get("team") or "", 40),
                    "abbr": clip(bio.get("abbr") or f.get("team_abbr") or "", 8),
                    "league": clip((f.get("path") or "").split("/")[-1].replace("-", " ").upper(), 24),
                    "pos": clip(bio.get("pos") or f.get("position") or "", 8),
                    "jersey": clip(bio.get("jersey") or f.get("jersey") or "", 4),
                    "height": bio.get("height") or "", "weight": bio.get("weight") or "",
                    "age": bio.get("age") or "", "hand": bio.get("hand") or "",
                    "conference": bio.get("conference") or "", "photo": photo, "stats": stats})
    if not out:
        try:
            out = await dash_team_roster(q)
        except Exception:
            out = []
    return web.json_response({"q": q, "players": out})


async def dash_api_player_one(request):
    """One player: last games, projection stats, plus the next-game / splits / injury brief."""
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    league = str(request.match_info.get("league") or "")
    aid = str(request.match_info.get("aid") or "")
    path = path_from_league_slug(league)
    if not path or not aid.isdigit():
        return dash_error(web, request, 404)

    async def _games():
        try:
            return await trend_games(path, aid, need=30)
        except Exception:
            return []

    async def _bio():
        try:
            return await espn_athlete_bio(path, aid)
        except Exception:
            return {}

    slug = design_head_league(path) or league
    games, bio, photo = await asyncio.gather(_games(), _bio(), dash_face_data(slug, aid, 120))
    name = clip(bio.get("name") or "", 40)
    if not name:
        return dash_error(web, request, 404)
    keys = dash_sheet_keys(path, bio.get("pos") or "")
    xref = ""
    lead = next((k for k in keys if k != "minutes"), keys[0] if keys else "")
    if lead:
        try:
            games, xref = await deepen_games(path, aid, name, lead, games, fast=False)
        except Exception:
            log.debug("Deeper player log skipped", exc_info=True)
            xref = ""
        if path in ("baseball/mlb", "hockey/nhl") and lead and "MLB" not in xref and "NHL" not in xref:
            try:
                official, label = await asyncio.wait_for(xref_official(name, path, lead), 5)
                a = [v for _, v in trend_values(games, lead)[:8]]
                b = [v for _, v in trend_values(official, lead)[:8]]
                n = min(len(a), len(b))
                if label and n:
                    same = sum(1 for i in range(n) if abs(a[i] - b[i]) < 0.2)
                    extra = f"{label} matches {same} of {n} recent games"
                    xref = f"{xref} · {extra}".strip(" ·") if xref else extra
            except Exception:
                log.debug("Cross-check skipped", exc_info=True)
    pack_keys = keys + [k for k in ("pass_cmp", "pass_att", "pass_int", "rush_yds", "rush_att", "minutes", "targets", "threes_att")
                        if k in STATS and k not in keys]
    packed = dash_pack_games(games, pack_keys, 30)
    stats = dash_pack_stats(packed, keys)
    default = next((s["key"] for s in stats if s["key"] != "minutes"), stats[0]["key"] if stats else "")
    brief = {"next": None, "injuries": [], "group": None}
    fresh = str(request.query.get("fresh") or "") == "1"
    try:
        brief = await asyncio.wait_for(
            dash_player_brief(path, name, bio.get("team") or "", bio.get("abbr") or "",
                              games, packed, keys, int((prm or {}).get("guild") or 0), default, fresh),
            8)
    except Exception:
        log.debug("Player brief skipped", exc_info=True)
    return web.json_response({
        "id": aid, "slug": slug, "path": path, "name": name,
        "team": clip(bio.get("team") or "", 40), "abbr": clip(bio.get("abbr") or "", 8),
        "league": clip(path.split("/")[-1].replace("-", " ").upper(), 24),
        "pos": clip(bio.get("pos") or "", 8), "jersey": clip(bio.get("jersey") or "", 4),
        "height": bio.get("height") or "", "weight": bio.get("weight") or "",
        "age": bio.get("age") or "", "hand": bio.get("hand") or "",
        "conference": bio.get("conference") or "", "photo": photo, "stat": default,
        "stats": stats, "games": packed,
        "next": brief.get("next"), "injuries": brief.get("injuries") or [],
        "group": brief.get("group"), "openLine": brief.get("openLine") or "", "xref": xref,
    })


async def dash_head_img(request):
    from aiohttp import web
    league = str(request.match_info.get("league") or "")
    aid = str(request.match_info.get("aid") or "")
    url = design_headshot_url(f"{league}:{aid}")
    if not url:
        return dash_error(web, request, 404)
    got = await design_fetch_images([url])
    raw = got.get(url)
    if not raw:
        return dash_error(web, request, 404)
    try:
        size = int(request.query.get("s") or 72)
    except (TypeError, ValueError):
        size = 72
    if size not in (72, 120):
        size = 72
    body, kind = design_face_file(raw, size)
    if not body or not kind:
        return dash_error(web, request, 404)
    return web.Response(body=body, content_type=kind,
                        headers={"Cache-Control": "private, no-store"})


