def intro_collage_jpeg() -> bytes:
    return base64.b64decode(INTRO_COLLAGE_B64)


async def dash_intro_collage(request):
    from aiohttp import web
    if not dash_authed(request):
        return dash_error(web, request, 403)
    return web.Response(body=intro_collage_jpeg(), content_type="image/jpeg",
                        headers={"Cache-Control": "private, max-age=86400"})


async def dash_look_img(request):
    from aiohttp import web
    name = request.match_info.get("name", "")
    if name not in LOOK_IDS and name != "default":
        return dash_error(web, request, 404)
    return web.Response(text=look_svg(name), content_type="image/svg+xml",
                        headers={"Cache-Control": "public, max-age=86400"})


async def dash_csv_out(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    kind = request.match_info.get("kind", "")
    if kind not in ("picks", "leaderboard"):
        return dash_error(web, request, 404)
    return web.Response(text=dashboard_csv(prm["guild"], kind), content_type="text/csv")


async def dash_shot_img(request):
    """The original screenshot, only for a slip this server can open."""
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    try:
        pid = int(request.match_info["pid"])
    except (KeyError, ValueError):
        return dash_error(web, request, 404)
    p = get_pick(prm["guild"], pid)
    if p is None or dash_secret(p) or not slip_has_shot(pid):
        return dash_error(web, request, 404)
    try:
        with open(slip_shot_pick_path(pid), "rb") as fh:
            raw = fh.read()
    except OSError:
        return dash_error(web, request, 404)
    if not raw:
        return dash_error(web, request, 404)
    if raw.startswith(b"\x89PNG"):
        kind = "image/png"
    elif raw.startswith(b"\xff\xd8"):
        kind = "image/jpeg"
    elif raw.startswith(b"GIF8"):
        kind = "image/gif"
    elif raw.startswith(b"RIFF"):
        kind = "image/webp"
    else:
        try:
            from PIL import Image, ImageOps
            im = ImageOps.exif_transpose(Image.open(io.BytesIO(raw))).convert("RGB")
            buf = io.BytesIO()
            im.save(buf, "JPEG", quality=85)
            raw, kind = buf.getvalue(), "image/jpeg"
        except Exception:
            return dash_error(web, request, 404)
    return web.Response(body=raw, content_type=kind, headers={"Cache-Control": "private, max-age=300"})


async def dash_image(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    kind, arg = request.match_info.get("kind", ""), request.match_info.get("arg")
    if arg is None and kind in DASH_POSTERS:
        arg = (prm["period"] or "season") if kind == "standings" else ""
    elif not ((kind == "card" and arg and _DASH_NUM.fullmatch(arg)) or
              (kind == "receipt" and arg and re.fullmatch(r"\d{1,10}", arg))):
        return dash_error(web, request, 404)
    try:
        png = await dashboard_image(kind, prm["guild"], arg, back=prm["back"] == "1")
    except Exception:
        log.exception("Dashboard image %s failed", kind)
        png = None
    if png is None:
        return web.Response(text="nothing to show", status=404, content_type="text/plain")
    return web.Response(body=png, content_type="image/png", headers={"Cache-Control": "private, max-age=60"})


async def dash_health(request):
    from aiohttp import web
    return web.Response(text="ok", content_type="text/plain")


def _dash_brand_path(name: str) -> str:
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "dash-brand", name)


def _poster_square(size: int):
    """The full Pimps Dashboard poster, squared. This is the page logo."""
    from PIL import Image
    size = max(16, min(1024, int(size)))
    src = Image.open(_dash_brand_path("splash.jpg")).convert("RGB")
    side = min(src.size)
    left = (src.width - side) // 2
    top = (src.height - side) // 2
    return src.crop((left, top, left + side, top + side)).resize((size, size), Image.LANCZOS)


def app_icon_png(size: int) -> bytes:
    """Home-screen / tab mark: the Pimps Dashboard poster."""
    img = _poster_square(size)
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    return buf.getvalue()


def app_splash_jpeg() -> bytes:
    with open(_dash_brand_path("splash.jpg"), "rb") as fh:
        return fh.read()


def dash_mark_data_uri(size: int = 240) -> str:
    """The poster inside the page, so the header does not wait on a second request."""
    import base64
    buf = io.BytesIO()
    _poster_square(size).save(buf, format="JPEG", quality=76, optimize=True)
    return "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode()


# Header and tab icon are the poster. Home Screen icons stay on /icon-*.png.
DASH_FAVICON = dash_mark_data_uri(240)
DASH_LOGO_HTML = '<img src="' + DASH_FAVICON + '" alt="" width="88" height="88">'


async def dash_favicon(request):
    from aiohttp import web
    return web.Response(body=app_icon_png(64), content_type="image/png",
                        headers={"Cache-Control": "public, max-age=86400"})


def dash_manifest_body() -> str:
    v = APP_MARK_V
    return json.dumps({
        "name": "Pimp's Dashboard", "short_name": "PIMP-BOT",
        "description": "The group's sports picks.",
        "start_url": "/", "scope": "/", "display": "standalone",
        "background_color": "#14003A", "theme_color": "#1a0f33",
        "icons": [
            {"src": "/pimp-mark-180.png", "sizes": "180x180", "type": "image/png", "purpose": "any"},
            {"src": "/pimp-mark-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"},
            {"src": "/pimp-mark-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"},
        ],
    }, separators=(",", ":"))


async def dash_manifest(request):
    from aiohttp import web
    return web.Response(text=dash_manifest_body(), content_type="application/manifest+json",
                        headers={"Cache-Control": "no-cache"})


SW_JS = (
    "const CACHE='pb-shell-156';"
    "self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/manifest.webmanifest'])).then(()=>self.skipWaiting()))});"
    "self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});"
    "self.addEventListener('fetch',e=>{const req=e.request;if(req.method!=='GET')return;"
    "const u=new URL(req.url);if(u.origin!==location.origin)return;"
    "if(u.pathname.startsWith('/api/')||u.pathname.startsWith('/img/')||u.pathname.indexOf('icon')>=0||u.pathname.indexOf('favicon')>=0||u.pathname.indexOf('apple-touch')>=0||u.pathname.indexOf('pimp-mark')>=0)return;"
    "e.respondWith(fetch(req).then(r=>{try{const copy=r.clone();caches.open(CACHE).then(c=>c.put(req,copy))}catch(x){}"
    "return r}).catch(()=>caches.match(req)))});"
)


async def dash_sw(request):
    from aiohttp import web
    return web.Response(text=SW_JS, content_type="application/javascript",
                        headers={"Cache-Control": "no-cache", "Service-Worker-Allowed": "/"})


async def dash_touch_icon(request):
    from aiohttp import web
    path = request.path or ""
    size = 512 if "512" in path else 192 if "192" in path else 180
    try:
        raw = app_icon_png(size)
    except Exception:
        return dash_error(web, request, 404)
    return web.Response(body=raw, content_type="image/png",
                        headers={"Cache-Control": "no-cache"})


async def dash_app_splash(request):
    from aiohttp import web
    try:
        raw = app_splash_jpeg()
    except Exception:
        return dash_error(web, request, 404)
    return web.Response(body=raw, content_type="image/jpeg",
                        headers={"Cache-Control": "public, max-age=86400"})


async def dash_logout(request):
    from aiohttp import web
    resp = web.Response(status=303, headers={"Location": "/"})
    resp.del_cookie(DASH_COOKIE, path="/")
    resp.del_cookie(DASH_DEV_COOKIE, path="/")
    resp.del_cookie(DASH_STAFF_COOKIE, path="/")
    resp.del_cookie(DASH_ACCT_COOKIE, path="/")
    return resp


async def dash_not_found(request):
    from aiohttp import web
    return dash_error(web, request, 404)


def slip_history_sources(guild_id: int) -> list[dict]:
    """Stored slips for the history page. Hidden and test slips stay off it."""
    if not guild_id:
        return []
    rows = db().execute(
        """SELECT * FROM picks WHERE guild_id = ?
           ORDER BY COALESCE(NULLIF(settled_at, ''), created_at) DESC, id DESC""",
        (guild_id,)).fetchall()
    kept = [p for p in rows if not dash_secret(p) and not pick_is_test(p)]
    ids = [int(p["id"]) for p in kept]
    legs_by: dict[int, list] = {}
    if ids:
        marks = ",".join("?" * len(ids))
        for leg in db().execute(
                f"SELECT * FROM legs WHERE pick_id IN ({marks}) ORDER BY idx", ids):
            legs_by.setdefault(int(leg["pick_id"]), []).append({k: leg[k] for k in leg.keys()})
    out = []
    for p in kept:
        item = {k: p[k] for k in p.keys()}
        text = item.get("legs")
        item["leg_text"] = text if isinstance(text, str) else ""
        item["legs"] = legs_by.get(int(p["id"]), [])
        out.append(item)
    return out


async def dash_slip_history(request):
    """Past slips, on the same board as the picks list: a table, then one slip."""
    from aiohttp import web
    from slip_history import render_slip_history_page
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    raw_page = request.query.get("page") or "1"
    raw_slip = str(request.query.get("slip") or "").strip()
    try:
        page = int(raw_page)
    except (TypeError, ValueError):
        page = 1
    slip_id = int(raw_slip) if raw_slip.isdigit() else None
    page_html = render_slip_history_page(
        slip_history_sources(prm["guild"]), filt=request.query.get("filter") or "all",
        page=page, slip_id=slip_id)
    return dash_html(web, page_html)


def dash_app(web):
    """The aiohttp app: every route goes through dash_guard."""
    @web.middleware
    async def guard(request, handler):
        return await dash_guard(request, handler)

    app = web.Application(middlewares=[guard], client_max_size=64 * 1024)
    app.add_routes([web.get("/", dash_index), web.get("/login", dash_index), web.get("/app", dash_index),
                    web.get("/live", dash_index), web.get("/news", dash_index), web.get("/open", dash_index),
                    web.get("/history", dash_slip_history),
                    web.get("/people", dash_index), web.get("/posters", dash_index), web.get("/more", dash_index),
                    web.get("/api/data", dash_api_data), web.get("/api/player.json", dash_api_player),
                    web.get(r"/api/player/{league:[a-z0-9-]{2,28}}/{aid:[0-9]{1,12}}.json", dash_api_player_one),
                    web.get("/health", dash_health), web.get("/img/app-splash.jpg", dash_app_splash),
                    web.get("/img/intro-collage.jpg", dash_intro_collage),
                    web.get(r"/img/look/{name:[a-z]+}.svg", dash_look_img),
                    web.get(r"/img/head/{league:[a-z0-9-]+}/{aid:[0-9]{1,12}}.png", dash_head_img),
                    web.get(r"/img/face/{league:[a-z0-9-]+}/{aid:[0-9]{1,12}}.png", dash_head_img),
                    web.get(r"/api/person/{key:\d+}.json", dash_api_person),
                    web.post("/api/dm.json", dash_api_dm),
                    web.post("/api/bank.json", dash_api_bank),
                    web.get(r"/img/ava/{uid:[0-9]{1,20}}.png", dash_avatar_img),
                    web.get(r"/api/slip/{pid:\d+}.json", dash_api_slip),
                    web.get(r"/img/shot/{pid:\d+}.jpg", dash_shot_img),
                    *dash30_routes(web), web.get("/api/{kind}.csv", dash_csv_out), web.get("/img/{kind}.png", dash_image),
                    web.get("/img/{kind}/{arg}.png", dash_image),                     web.get("/favicon.ico", dash_favicon),
                    web.get("/favicon.svg", dash_favicon),
                    web.get("/manifest.webmanifest", dash_manifest),
                    web.get("/apple-touch-icon.png", dash_touch_icon),
                    web.get("/apple-touch-icon-precomposed.png", dash_touch_icon),
                    web.get("/icon-192.png", dash_touch_icon),
                    web.get("/icon-512.png", dash_touch_icon),
                    web.get("/pimp-mark-180.png", dash_touch_icon),
                    web.get("/pimp-mark-192.png", dash_touch_icon),
                    web.get("/pimp-mark-512.png", dash_touch_icon),
                    web.get("/sw.js", dash_sw),
                    web.post("/api/log.json", dash_api_log),
                    web.get("/logout", dash_logout),
                    web.get("/staff", dash_staff), web.get("/pimp-trading", dash_pimp),
                    web.get("/apex-city", dash_pimp_city),
                    web.get("/apex-city/", dash_pimp_city),
                    web.get(r"/apex-city/{tail:.*}", dash_pimp_city),
                    web.get("/signal-city", dash_pimp_city),
                    web.get("/signal-city/", dash_pimp_city),
                    web.get(r"/signal-city/{tail:.*}", dash_pimp_city),
                    web.get("/pimp-city", dash_pimp_city),
                    web.get("/pimp-city/", dash_pimp_city),
                    web.get(r"/pimp-city/{tail:.*}", dash_pimp_city),
                    web.get("/api/staff.json", dash_api_staff),
                    web.post("/api/staff.json", dash_api_staff_post),
                    web.get("/api/pimp-trading.json", dash_api_pimp),
                    web.post("/api/pimp-trading.json", dash_api_pimp_post),
                    web.get("/account", dash_account), web.post("/account", dash_account_post),
                    web.post("/login", dash_login_post),
                    web.get("/{tail:.*}", dash_not_found)])
    return app


