def staff_gid(gid: Optional[int] = None) -> int:
    return int(gid if gid is not None else (dashboard_guild() or 0))


CREW_RANKS = {"developer": 40, "owner": 30, "admin": 20, "mod": 10}


def crew_baked(kind: str) -> list:
    return list({"developer": DEVELOPER_IDS, "owner": OWNER_IDS, "admin": ADMIN_IDS, "mod": MOD_IDS}.get(kind, []))


def crew_ids(kind: str, gid: Optional[int] = None) -> list:
    """Env IDs first (locked), then extras saved with /staff add. Legacy owner_id still counts as owner."""
    out = []
    for n in crew_baked(kind) + parse_snowflakes(get_setting(staff_gid(gid), f"crew_{kind}s") or ""):
        if n not in out:
            out.append(n)
    if kind == "owner":
        for n in parse_snowflakes(get_setting(staff_gid(gid), "owner_id") or ""):
            if n not in out:
                out.append(n)
    return out


def owner_id(gid: Optional[int] = None) -> int:
    ids = crew_ids("owner", gid)
    return ids[0] if ids else 0


def crew_rank(uid: int, gid: Optional[int] = None) -> int:
    if not uid:
        return 0
    uid = int(uid)
    for kind, rank in CREW_RANKS.items():
        if uid in crew_ids(kind, gid):
            return rank
    if staff_rec(uid, gid).get("state") == "on":
        return CREW_RANKS["mod"]
    return 0


def crew_at_least(uid: int, kind: str, gid: Optional[int] = None) -> bool:
    return crew_rank(uid, gid) >= CREW_RANKS.get(kind, 99)


def crew_role_name(uid: int, gid: Optional[int] = None) -> str:
    r = crew_rank(uid, gid)
    return {40: "developer", 30: "owner", 20: "admin", 10: "mod"}.get(r, "")


def crew_locked(kind: str, uid: int) -> bool:
    return int(uid) in crew_baked(kind) or (kind != "developer" and int(uid) in crew_baked("developer"))


def crew_save_extras(kind: str, ids: list, gid: Optional[int] = None) -> None:
    baked = set(crew_baked(kind))
    extra = [i for i in ids if i not in baked]
    set_setting(staff_gid(gid), f"crew_{kind}s", ",".join(str(i) for i in extra) or None)


def crew_grant(kind: str, uid: int, name: Optional[str] = None, gid: Optional[int] = None) -> str:
    """Put this Discord user on owner / admin / mod. Developers stay env-only."""
    uid = int(uid)
    if kind not in ("owner", "admin", "mod"):
        return "role"
    if uid in crew_ids("developer", gid):
        return "dev"
    if kind != "owner" and uid not in OWNER_IDS and owner_id(gid) == uid:
        set_setting(staff_gid(gid), "owner_id", None)
    for other in ("owner", "admin", "mod"):
        leftover = [i for i in parse_snowflakes(get_setting(staff_gid(gid), f"crew_{other}s") or "") if i != uid]
        if other == kind and uid not in crew_baked(kind):
            leftover.append(uid)
        crew_save_extras(other, leftover, gid)
    staff_put(uid, "on", name, gid)
    return "ok"


def crew_revoke(uid: int, gid: Optional[int] = None) -> str:
    uid = int(uid)
    if uid in crew_ids("developer", gid):
        return "dev"
    if uid in OWNER_IDS:
        return "env"
    for kind in ("owner", "admin", "mod"):
        leftover = [i for i in parse_snowflakes(get_setting(staff_gid(gid), f"crew_{kind}s") or "") if i != uid]
        crew_save_extras(kind, leftover, gid)
    if owner_id(gid) == uid and uid not in OWNER_IDS:
        set_setting(staff_gid(gid), "owner_id", None)
    staff_put(uid, None, gid=gid)
    return "ok"


HEAD_ROLE_NAME = "Head Admin"
_DEPARTED_AT: dict[int, float] = {}


def depart_alerts(gid: Optional[int] = None) -> list:
    try:
        raw = json.loads(get_setting(staff_gid(gid), "depart_alerts") or "[]")
    except Exception:
        raw = []
    return [x for x in raw if isinstance(x, dict)][:16]


def depart_save(rows: list, gid: Optional[int] = None) -> None:
    set_setting(staff_gid(gid), "depart_alerts", json.dumps(rows[:16]))


def depart_open(gid: Optional[int] = None) -> list:
    return [x for x in depart_alerts(gid) if not x.get("cleared")]


def head_admin_id(gid: Optional[int] = None) -> int:
    raw = get_setting(staff_gid(gid), "head_admin") or ""
    if str(raw).isdigit() and int(raw) in crew_ids("admin", gid) + crew_ids("owner", gid):
        return int(raw)
    admins = crew_ids("admin", gid)
    return admins[0] if admins else 0


def _depart_first(uid: int) -> bool:
    now_t = time.time()
    prev = _DEPARTED_AT.get(int(uid), 0)
    _DEPARTED_AT[int(uid)] = now_t
    return now_t - prev > 45


def recovery_recent(key: str) -> bool:
    raw = get_setting(0, "recovery_sent") or ""
    if not raw.startswith(key + "|"):
        return False
    try:
        return time.time() - float(raw.split("|", 1)[1]) < 3600
    except Exception:
        return False


def recovery_mark(key: str) -> None:
    set_setting(0, "recovery_sent", f"{key}|{time.time()}")


async def send_owner_recovery(client, reason: str) -> int:
    """DM the developers and owners their own database copy. The token stays in Railway."""
    key = clip(reason, 80)
    if recovery_recent(key):
        return 0
    ids: list[int] = []
    for i in list(DEVELOPER_IDS) + list(OWNER_IDS):
        if i not in ids:
            ids.append(i)
    gid = staff_gid()
    note = (
        "Failsafe\n"
        f"{clip(reason, 400)}\n"
        f"Version {BOT_VERSION}. Developers stay on the ladder.\n"
        "The files are the picks database and the spreadsheet. The Discord token stays in Railway. "
        "If a second copy is using it, reset the token in the Discord developer portal and paste the new one into Railway. "
        "Run one copy."
    )
    sent = 0
    for i in ids:
        files = []
        try:
            files = backup_files(gid) if gid else []
            user = await client.fetch_user(int(i))
            await user.send(note, files=files or None)
            sent += 1
        except Exception:
            log.warning("Recovery note could not be delivered to %s", i, exc_info=True)
        finally:
            release_backup_folders()
    if sent:
        recovery_mark(key)
        try:
            staff_log_add(gid, "warn", f"Failsafe packet sent to {sent}", "robot")
        except Exception:
            pass
    return sent


def _guild_for(gid: Optional[int]):
    try:
        return bot.get_guild(int(gid or staff_gid() or 0))
    except Exception:
        return None


try:
    ROLE_TZ = ZoneInfo("America/Chicago")
except Exception:
    ROLE_TZ = TZ

_ROLE_ACTOR: dict[tuple, tuple] = {}


def role_mark(name: str) -> str:
    """Two letters so a role row can be scanned. Not a picture."""
    parts = [p for p in re.split(r"[\s_\-]+", name or "") if any(c.isalnum() for c in p)]
    chars = []
    for part in parts:
        for ch in part:
            if ch.isalnum():
                chars.append(ch.upper())
                break
        if len(chars) == 2:
            break
    if len(chars) >= 2:
        return "".join(chars[:2])
    letters = "".join(c for c in (parts[0] if parts else "") if c.isalnum()).upper()
    return letters[:2] or "•"


def role_hex(role) -> str:
    color = getattr(role, "color", None)
    if color is None:
        color = getattr(role, "colour", None)
    try:
        value = int(getattr(color, "value", 0) or 0)
    except (TypeError, ValueError):
        value = 0
    if value <= 0:
        return ""
    return f"#{value:06x}"


def role_labels_map(gid: Optional[int] = None) -> dict:
    try:
        raw = json.loads(get_setting(staff_gid(gid), "role_labels") or "{}")
    except Exception:
        raw = {}
    if not isinstance(raw, dict):
        return {}
    out = {}
    for key, val in raw.items():
        if str(key).isdigit() and isinstance(val, str) and val.strip():
            out[str(int(key))] = clip(val.strip(), 40)
    return out


def role_labels_save(labels: dict, gid: Optional[int] = None) -> None:
    clean = {}
    for key, val in labels.items():
        if str(key).isdigit() and isinstance(val, str) and val.strip():
            clean[str(int(key))] = clip(val.strip(), 40)
    set_setting(staff_gid(gid), "role_labels", json.dumps(clean) if clean else None)


def role_desk_label(gid: Optional[int], role) -> str:
    name = clip((getattr(role, "name", None) or "").strip(), 40)
    custom = role_labels_map(gid).get(str(int(getattr(role, "id", 0) or 0))) or ""
    return custom or name


def role_label_set(gid: int, role_id, label) -> tuple[bool, str]:
    """Rename the label this desk shows. Discord's role name stays."""
    if not str(role_id).isdigit():
        return False, "Pick a Discord role."
    guild = _guild_for(gid)
    role = guild.get_role(int(role_id)) if guild is not None else None
    if role is None or not (getattr(role, "name", None) or "").strip():
        return False, "That Discord role is gone."
    text = re.sub(r"\s+", " ", str(label or "")).strip()
    if len(text) > 40:
        return False, "Keep the label to 40 characters."
    labels = role_labels_map(gid)
    key = str(int(role_id))
    discord_name = (role.name or "").strip()
    if not text or text.casefold() == discord_name.casefold():
        labels.pop(key, None)
        role_labels_save(labels, gid)
        return True, "The desk uses the Discord name again."
    labels[key] = text
    role_labels_save(labels, gid)
    return True, f"This desk calls it {text}."


def bot_manage_note(guild) -> str:
    """A standing reason when no role on this server can be changed."""
    if guild is None:
        return "The bot cannot see this server, so a role change here will not reach Discord."
    me = getattr(guild, "me", None)
    if me is None:
        return "The bot is not in this server, so a role change here will not reach Discord."
    perms = getattr(me, "guild_permissions", None)
    if perms is None or not getattr(perms, "manage_roles", False):
        return "The bot does not have Manage Roles, so a role change here will not reach Discord."
    return ""


def role_block_reason(guild, role) -> str:
    """Empty when Discord will accept a change to this role."""
    if guild is None:
        return "The bot cannot see this server."
    me = getattr(guild, "me", None)
    if me is None:
        return "The bot is not in this server."
    name = (getattr(role, "name", None) or "").strip()
    if name == "@everyone" or getattr(role, "is_default", lambda: False)():
        return "Discord manages that role, so the bot cannot change it."
    perms = getattr(me, "guild_permissions", None)
    if perms is None or not getattr(perms, "manage_roles", False):
        return "The bot does not have Manage Roles."
    if getattr(role, "managed", False):
        return "Discord manages that role, so the bot cannot change it."
    top = getattr(me, "top_role", None)
    if top is None or getattr(role, "position", 0) >= getattr(top, "position", 0):
        return "The bot's role is not above this one."
    return ""


def readable_name(text, uid: int = 0) -> str:
    """A name a person can read. A Discord id is not a label."""
    raw = str(text or "").strip()
    if not raw:
        return ""
    if raw.isdigit() and ((uid and int(raw) == int(uid)) or len(raw) >= 16):
        return ""
    return raw


def member_display_name(guild, uid: int) -> str:
    if guild is None or not uid:
        return ""
    member = None
    getter = getattr(guild, "get_member", None)
    if callable(getter):
        try:
            member = getter(int(uid))
        except Exception:
            member = None
    if member is None:
        for item in getattr(guild, "members", []) or []:
            if int(getattr(item, "id", 0) or 0) == int(uid):
                member = item
                break
    if member is None:
        return ""
    for attr in ("display_name", "global_name", "name"):
        shown = readable_name(getattr(member, attr, None), uid)
        if shown:
            return shown
    return ""


def discord_head_role_name(guild) -> str:
    if guild is not None:
        for role in getattr(guild, "roles", []) or []:
            name = (getattr(role, "name", None) or "").strip()
            if name.lower() == HEAD_ROLE_NAME.lower():
                return name
    return HEAD_ROLE_NAME


def head_admin_row(gid: Optional[int], hid: int, head_open: bool, left: Optional[dict]) -> dict:
    """Head admin: the member's display name and the Discord role name. Never the numeric id."""
    guild = _guild_for(gid)
    shown = ""
    if hid:
        shown = member_display_name(guild, hid) or readable_name(crew_display_name(hid, gid), hid)
    if not shown and left:
        shown = readable_name(left.get("name"), hid)
    return {
        "id": int(hid or 0),
        "name": shown,
        "role": discord_head_role_name(guild),
        "open": bool(head_open),
    }


def role_people(role) -> Optional[list]:
    if not MEMBERS_INTENT:
        return None
    rows = []
    for member in getattr(role, "members", []) or []:
        if getattr(member, "bot", False):
            continue
        uid = int(member.id)
        shown = ""
        for attr in ("display_name", "global_name", "name"):
            shown = readable_name(getattr(member, attr, None), uid)
            if shown:
                break
        rows.append({"id": uid, "name": shown})
    rows.sort(key=lambda r: r["name"].lower())
    return rows


def role_clock(when: Optional[datetime] = None) -> str:
    """ISO timestamp in America/Chicago, including the offset."""
    when = when or datetime.now(ROLE_TZ)
    if when.tzinfo is None:
        when = when.replace(tzinfo=ROLE_TZ)
    else:
        when = when.astimezone(ROLE_TZ)
    return when.isoformat(timespec="seconds")


def role_change_when(raw: str) -> str:
    try:
        when = datetime.fromisoformat(raw or "")
    except Exception:
        return raw or ""
    if when.tzinfo is None:
        when = when.replace(tzinfo=ROLE_TZ)
    return when.astimezone(ROLE_TZ).strftime("%b %-d, %-I:%M %p") + " Central"


def role_log_load(gid: Optional[int] = None) -> list:
    try:
        raw = json.loads(get_setting(staff_gid(gid), "role_log") or "[]")
    except Exception:
        raw = []
    return [x for x in raw if isinstance(x, dict)] if isinstance(raw, list) else []


def role_log_save(rows: list, gid: Optional[int] = None) -> None:
    set_setting(staff_gid(gid), "role_log", json.dumps(rows[:80]) if rows else None)


def role_log_add(gid: int, role_id: int, role_name: str, uid: int, who: str, act: str,
                 by: str = "", by_id: int = 0) -> None:
    """One add or remove. A second report of the same change in a few seconds updates the name."""
    act = "remove" if act == "remove" else "add"
    rows = role_log_load(gid)
    now = datetime.now(ROLE_TZ)
    for row in rows[:12]:
        if int(row.get("role") or 0) != int(role_id) or int(row.get("uid") or 0) != int(uid):
            continue
        if row.get("act") != act:
            continue
        try:
            prev = datetime.fromisoformat(row.get("at") or "")
            if prev.tzinfo is None:
                prev = prev.replace(tzinfo=ROLE_TZ)
            if abs((now - prev.astimezone(ROLE_TZ)).total_seconds()) <= 25:
                if by and not row.get("by"):
                    row["by"] = clip(by, 40)
                    if by_id:
                        row["by_id"] = int(by_id)
                    role_log_save(rows, gid)
                return
        except Exception:
            continue
    rows.insert(0, {
        "role": int(role_id),
        "role_name": clip(role_name or "", 40),
        "uid": int(uid),
        "who": clip(who or str(uid), 40),
        "act": act,
        "by": clip(by, 40) if by else "",
        "by_id": int(by_id or 0),
        "at": role_clock(now),
    })
    role_log_save(rows, gid)


def role_changes_public(gid: Optional[int] = None) -> list:
    out = []
    for row in role_log_load(gid)[:40]:
        out.append({
            "role": int(row.get("role") or 0),
            "name": row.get("role_name") or "",
            "act": "remove" if row.get("act") == "remove" else "add",
            "who": row.get("who") or "",
            "by": row.get("by") or "",
            "when": role_change_when(str(row.get("at") or "")),
        })
    return out


def role_note_warn(note: str) -> bool:
    text = note or ""
    return any(part in text for part in ("not changed", "was not", "did not", "Could not", "cannot"))


def role_actor_stash(gid: int, uid: int, role_id: int, act: str, by: str, by_id: int) -> None:
    _ROLE_ACTOR[(int(gid), int(uid), int(role_id), act)] = (clip(by, 40) if by else "", int(by_id or 0), time.monotonic())


def role_actor_clear(gid: int, uid: int, role_id: int, act: str) -> None:
    _ROLE_ACTOR.pop((int(gid), int(uid), int(role_id), act), None)


def role_actor_stash_get(gid: int, uid: int, role_id: int, act: str) -> tuple[str, int]:
    row = _ROLE_ACTOR.get((int(gid), int(uid), int(role_id), act))
    if not row or time.monotonic() - row[2] > 60:
        return "", 0
    return row[0], int(row[1] or 0)


def discord_role_rows(gid: Optional[int] = None) -> list:
    """This server's Discord roles, highest first, under the names Discord uses."""
    guild = _guild_for(gid)
    if guild is None:
        return []
    roles = []
    for role in getattr(guild, "roles", []) or []:
        name = (getattr(role, "name", None) or "").strip()
        if name:
            roles.append(role)
    roles.sort(key=lambda role: int(getattr(role, "position", 0) or 0), reverse=True)
    out = []
    for role in roles:
        name = (getattr(role, "name", None) or "").strip()
        people = role_people(role)
        shown = people[:40] if people is not None else None
        out.append({
            "id": int(role.id),
            "name": name,
            "label": name,
            "mark": role_mark(name),
            "color": role_hex(role),
            "n": None if people is None else len(people),
            "more": 0 if people is None else max(0, len(people) - 40),
            "people": shown,
            "head": name.lower() == HEAD_ROLE_NAME.lower(),
            "block": role_block_reason(guild, role),
        })
    return out


def desk_members(gid: Optional[int] = None) -> list:
    guild = _guild_for(gid)
    rows = []
    seen = set()
    if guild is not None and MEMBERS_INTENT:
        for m in getattr(guild, "members", []) or []:
            if getattr(m, "bot", False):
                continue
            shown = readable_name(getattr(m, "display_name", None) or getattr(m, "name", None), int(m.id))
            rows.append({"id": int(m.id), "name": shown})
            seen.add(int(m.id))
    for kind in ("owner", "admin", "mod"):
        for i in crew_ids(kind, gid):
            if i in seen:
                continue
            rows.append({"id": int(i), "name": readable_name(crew_display_name(i, gid), i)})
            seen.add(int(i))
    rows.sort(key=lambda r: r["name"].lower())
    return rows[:200]


def staff_desk(uid: int, gid: Optional[int] = None) -> Optional[dict]:
    if not crew_at_least(uid, "owner", gid):
        return None
    hid = head_admin_id(gid)
    open_alerts = depart_open(gid)
    left = next((a for a in open_alerts if a.get("seat") == "Head admin"), None)
    head_open = bool(left) or not hid
    return {
        "open": True,
        "developer": crew_at_least(uid, "developer", gid),
        "members_intent": MEMBERS_INTENT,
        "head": head_admin_row(gid, hid, head_open, left),
        "roles": discord_role_rows(gid),
        "members": desk_members(gid),
        "alerts": open_alerts,
        "changes": role_changes_public(gid),
        "manage": bot_manage_note(_guild_for(gid)),
    }


def resolve_desk_person(gid: int, raw: str) -> tuple[Optional[int], str]:
    text = (raw or "").strip()
    if not text:
        return None, ""
    ids = parse_snowflakes(text)
    if ids and (text.isdigit() or text.startswith("<@")):
        uid = ids[0]
        return uid, crew_display_name(uid, gid)
    guild = _guild_for(gid)
    want = text.casefold()
    if guild is not None:
        for m in getattr(guild, "members", []) or []:
            names = [getattr(m, "display_name", "") or "", getattr(m, "name", "") or ""]
            if any(n.casefold() == want for n in names if n):
                return int(m.id), clip(getattr(m, "display_name", None) or str(m.id), 40)
    for row in desk_members(gid):
        if row["name"].casefold() == want:
            return int(row["id"]), row["name"]
    return None, ""


async def audit_role_actor(guild, uid: int, role_id: int, act: str) -> tuple[str, int]:
    """Who Discord says made this role change, when the audit log is readable."""
    me = getattr(guild, "me", None)
    perms = getattr(me, "guild_permissions", None) if me is not None else None
    if perms is None or not getattr(perms, "view_audit_log", False):
        return "", 0
    try:
        async for entry in guild.audit_logs(limit=8, action=discord.AuditLogAction.member_role_update):
            target = getattr(entry, "target", None)
            if target is None or int(getattr(target, "id", 0) or 0) != int(uid):
                continue
            created = getattr(entry, "created_at", None)
            if created is not None:
                if created.tzinfo is None:
                    created = created.replace(tzinfo=timezone.utc)
                if (datetime.now(timezone.utc) - created).total_seconds() > 30:
                    continue
            diff = entry.before if act == "remove" else entry.after
            roles = getattr(diff, "roles", None) or []
            if not any(int(getattr(item, "id", 0) or 0) == int(role_id) for item in roles):
                continue
            user = getattr(entry, "user", None)
            if user is None:
                return "", 0
            name = getattr(user, "display_name", None) or getattr(user, "name", None) or ""
            return clip(str(name), 40), int(user.id)
    except Exception:
        log.warning("Role audit log was not readable", exc_info=True)
    return "", 0


async def observe_role_change(guild, member, role, act: str) -> None:
    gid = int(getattr(guild, "id", 0) or 0)
    uid = int(getattr(member, "id", 0) or 0)
    role_id = int(getattr(role, "id", 0) or 0)
    if not gid or not uid or not role_id:
        return
    name = (getattr(role, "name", None) or "").strip()
    if not name or name == "@everyone":
        return
    by, by_id = role_actor_stash_get(gid, uid, role_id, act)
    if not by:
        by, by_id = await audit_role_actor(guild, uid, role_id, act)
    who = clip(getattr(member, "display_name", None) or getattr(member, "name", None) or str(uid), 40)
    role_log_add(gid, role_id, name, uid, who, act, by, by_id)


async def note_member_role_edits(before, after) -> None:
    """Role adds and removes the gateway actually delivered."""
    if getattr(after, "bot", False):
        return
    guild = getattr(after, "guild", None)
    if guild is None:
        return
    old = {}
    for role in getattr(before, "roles", None) or []:
        rid = getattr(role, "id", None)
        if rid:
            old[int(rid)] = role
    new = {}
    for role in getattr(after, "roles", None) or []:
        rid = getattr(role, "id", None)
        if rid:
            new[int(rid)] = role
    for rid, role in new.items():
        if rid not in old:
            await observe_role_change(guild, after, role, "add")
    for rid, role in old.items():
        if rid not in new:
            await observe_role_change(guild, after, role, "remove")


async def switch_discord_role(gid: int, role_id: int, uid: int, add: bool, actor: int = 0) -> tuple[bool, str]:
    """Give or take one Discord role. Ok is true only when Discord already matches, or the call succeeded."""
    guild = _guild_for(gid)
    if guild is None:
        return False, "The bot cannot see this server, so the role was not changed."
    role = guild.get_role(int(role_id)) if role_id else None
    if role is None or not (getattr(role, "name", None) or "").strip() or getattr(role, "name", "") == "@everyone":
        return False, "That Discord role is gone, so nothing was changed."
    block = role_block_reason(guild, role)
    if block:
        return False, block + " The role was not changed."
    label = (getattr(role, "name", None) or "").strip()
    try:
        member = guild.get_member(int(uid))
        if member is None:
            member = await guild.fetch_member(int(uid))
    except discord.NotFound:
        return False, "That person is not in the server, so the role was not changed."
    except discord.Forbidden:
        return False, "The bot cannot see that person, so the role was not changed."
    except Exception:
        log.warning("Could not load member %s", uid, exc_info=True)
        return False, "Discord did not answer, so the role was not changed."
    if getattr(member, "bot", False):
        return False, "That account is a bot, so the role was not changed."
    has = any(int(getattr(item, "id", 0) or 0) == int(role.id) for item in (getattr(member, "roles", None) or []))
    who = clip(getattr(member, "display_name", None) or str(uid), 40)
    if add and has:
        return True, f"{who} already has {label}."
    if (not add) and (not has):
        return True, f"{who} does not have {label}."
    act = "add" if add else "remove"
    by = crew_display_name(actor, gid) if actor else ""
    role_actor_stash(gid, uid, int(role.id), act, by, actor)
    try:
        if add:
            await member.add_roles(role, reason="Staff HQ")
        else:
            await member.remove_roles(role, reason="Staff HQ")
    except discord.Forbidden:
        role_actor_clear(gid, uid, int(role.id), act)
        fresh = role_block_reason(guild, role)
        return False, (fresh + " The role was not changed.") if fresh else "Discord refused the change. The role was not changed."
    except discord.NotFound:
        role_actor_clear(gid, uid, int(role.id), act)
        return False, "That person is not in the server, so the role was not changed."
    except Exception:
        role_actor_clear(gid, uid, int(role.id), act)
        log.warning("Role change failed", exc_info=True)
        return False, "Discord did not take the change. The role was not changed."
    try:
        await observe_role_change(guild, member, role, act)
    except Exception:
        log.warning("Role change was not recorded", exc_info=True)
    if add:
        return True, f"{label} is on {who}."
    return True, f"{label} is off {who}."


async def assign_discord_role(gid: int, role_id: int, uid: int, replace: bool, actor: int = 0) -> str:
    if not replace:
        _ok, note = await switch_discord_role(gid, role_id, uid, True, actor)
        return note
    guild = _guild_for(gid)
    if guild is None:
        return "The bot cannot see this server, so the role was not changed."
    role = guild.get_role(int(role_id)) if role_id else None
    if role is None or not (getattr(role, "name", None) or "").strip():
        return "That Discord role is gone, so nothing was changed."
    block = role_block_reason(guild, role)
    if block:
        return block + " The role was not changed."
    if not MEMBERS_INTENT:
        _ok, note = await switch_discord_role(gid, role_id, uid, True, actor)
        if not _ok:
            return note
        return note + " The bot cannot see every member, so other people were left as they are."
    missed = 0
    for member in list(getattr(role, "members", []) or []):
        if int(member.id) == int(uid) or getattr(member, "bot", False):
            continue
        ok, _note = await switch_discord_role(gid, int(role.id), int(member.id), False, actor)
        if not ok:
            missed += 1
    _ok, note = await switch_discord_role(gid, int(role.id), int(uid), True, actor)
    if not _ok:
        return note
    if missed:
        word = "person" if missed == 1 else "people"
        return note + f" Could not take it off {missed} other {word}."
    return note


async def ensure_head_role(gid: int, uid: int, actor: int = 0) -> str:
    guild = _guild_for(gid)
    if guild is None:
        return "The bot cannot see this server, so the role was not changed."
    role = None
    for item in getattr(guild, "roles", []) or []:
        if (getattr(item, "name", None) or "").strip().lower() == HEAD_ROLE_NAME.lower():
            role = item
            break
    if role is None:
        try:
            role = await guild.create_role(name=HEAD_ROLE_NAME, colour=discord.Colour(0xF0B429),
                                           reason="Head admin seat")
        except discord.Forbidden:
            return "The bot does not have Manage Roles, so Head Admin was not created and the role was not changed."
        except Exception:
            log.warning("Head Admin role was not created", exc_info=True)
            return "Discord did not create Head Admin, so the role was not changed."
    return await assign_discord_role(gid, int(role.id), uid, True, actor)


async def member_departed(guild, uid: int, name: str, how: str) -> None:
    """A leave or a ban. Bans also drop dashboard cookies and today's access key."""
    uid = int(uid)
    gid = int(getattr(guild, "id", None) or staff_gid() or 0)
    name = clip(name or crew_display_name(uid, gid), 40)
    role = crew_role_name(uid, gid)
    hid = head_admin_id(gid)
    seat = "Head admin" if uid == hid else {"owner": "Owner", "admin": "Admin", "mod": "Mod",
                                            "developer": "Developer"}.get(role, "")
    first = _depart_first(uid)
    try:
        dash_note_kick(uid, True)
    except Exception:
        log.warning("Couldn't close the dashboard for a removed member")
    if how == "banned":
        try:
            dash_kick_sessions()
            dash_gate_rotate()
        except Exception:
            log.warning("Couldn't sign the dashboard out after a ban")
    if not first:
        return
    if seat:
        rows = depart_alerts(gid)
        rows.insert(0, {"id": uid, "name": name, "seat": seat, "how": how, "at": now_iso(), "cleared": False})
        depart_save(rows, gid)
        staff_log_add(gid, "warn", f"{seat} {how}: {name}", "robot")
    if role and role != "developer" and uid not in OWNER_IDS:
        crew_revoke(uid, gid)
    if uid == hid:
        set_setting(staff_gid(gid), "head_admin", None)
    if seat in ("Head admin", "Owner"):
        try:
            await send_owner_recovery(
                bot, f"{name} {how}. {seat} is open. The failsafe developers are still on the ladder.")
        except Exception:
            log.warning("Recovery packet failed", exc_info=True)


async def staff_seat(actor: int, gid: int, body: dict) -> tuple[bool, str]:
    mode = "replace" if str(body.get("mode") or "") == "replace" else "add"
    kind = str(body.get("role") or "head")
    uid, name = resolve_desk_person(gid, str(body.get("who") or ""))
    if uid is None:
        return False, "Pick a person who is still in the server, or paste their Discord ID."
    if mode == "replace" or kind == "head":
        if not crew_at_least(actor, "owner", gid):
            return False, "Developer and owner only."
        old = head_admin_id(gid)
        if old and old != uid and old not in OWNER_IDS and old not in crew_ids("developer", gid):
            crew_revoke(old, gid)
        st = crew_grant("admin", uid, name, gid)
        if st == "dev":
            return False, "That person is a developer. They already have the failsafe."
        set_setting(staff_gid(gid), "head_admin", str(uid))
        rows = depart_alerts(gid)
        for row in rows:
            if row.get("seat") == "Head admin":
                row["cleared"] = True
        depart_save(rows, gid)
        note = await ensure_head_role(gid, uid, actor)
        full = f"{name} is Head admin on the desk. {note}"
        staff_log_add(gid, "warn" if role_note_warn(full) else "ok", full, crew_display_name(actor, gid))
        return True, full
    if kind == "owner" and not crew_at_least(actor, "developer", gid):
        return False, "Only a developer can add an owner."
    if kind not in ("owner", "admin", "mod"):
        return False, "Pick Head admin, owner, admin, or mod."
    st = crew_grant(kind, uid, name, gid)
    if st == "dev":
        return False, "That person is a developer. They already have the failsafe."
    note = f"{name} is {kind}."
    role_id = str(body.get("discord_role") or "")
    if role_id.isdigit():
        extra = await assign_discord_role(gid, int(role_id), uid, False, actor)
        note = note + " " + extra
    staff_log_add(gid, "warn" if role_note_warn(note) else "ok", note, crew_display_name(actor, gid))
    return True, note


def owner_claim(uid: int, gid: Optional[int] = None) -> bool:
    """True when this person is (or just became) an owner. Developers may always claim a vacant owner slot."""
    if uid in crew_ids("owner", gid):
        return True
    if crew_ids("owner", gid) and not crew_at_least(uid, "developer", gid):
        return False
    crew_grant("owner", uid, gid=gid)
    return True


def crew_display_name(uid: int, gid: Optional[int] = None) -> str:
    rec = staff_rec(uid, gid)
    nm = rec.get("name") or ""
    if nm and not str(nm).isdigit():
        return clip(nm, 40)
    try:
        g = bot.get_guild(int(gid or staff_gid() or 0))
        m = g.get_member(int(uid)) if g else None
        n = (getattr(m, "display_name", None) or getattr(m, "name", None)) if m is not None else None
        if not n:
            u = bot.get_user(int(uid)) if hasattr(bot, "get_user") else None
            n = getattr(u, "display_name", None) or getattr(u, "name", None) if u is not None else None
        if n and not str(n).isdigit():
            if rec.get("state"):
                staff_put(uid, rec.get("state"), n, gid)
            return clip(n, 40)
    except Exception:
        pass
    try:
        row = db().execute(
            "SELECT bettor_name FROM picks WHERE bettor_id = ? AND bettor_name IS NOT NULL AND bettor_name != '' "
            "LIMIT 1", (int(uid),)).fetchone()
        if row and row["bettor_name"] and not str(row["bettor_name"]).isdigit():
            return clip(row["bettor_name"], 40)
    except Exception:
        pass
    return str(uid)


def note_slip_read(how: str, pick_id=None, who: str = "", title: str = "", url: str = "") -> None:
    try:
        items = json.loads(get_setting(0, "slipread_log") or "[]")
    except Exception:
        items = []
    if not isinstance(items, list):
        items = []
    items.insert(0, {"how": clip(how, 16), "id": pick_id, "who": clip(who, 40),
                     "title": clip(title, 80), "url": clip(url, 160), "at": now_iso()})
    set_setting(0, "slipread_log", json.dumps(items[:50]))


def crash_note(kind: str, title: str, why: str, gid: Optional[int] = None) -> None:
    g = staff_gid(gid)
    text = clip(f"{title}: {why}", 180)
    staff_log_add(g, kind, text, "robot")
    try:
        items = json.loads(get_setting(g, "crash_log") or "[]")
    except Exception:
        items = []
    if not isinstance(items, list):
        items = []
    items.insert(0, {"kind": clip(kind, 12), "title": clip(title, 60), "why": clip(why, 140), "at": now_iso()})
    set_setting(g, "crash_log", json.dumps(items[:24]))


async def crash_notify(client, kind: str, title: str, why: str) -> None:
    crash_note(kind, title, why)
    if kind in ("ok", "info"):
        return
    card = None
    try:
        card = status_card({
            "title": "HEADS UP",
            "tone": "crash",
            "happened": title,
            "news": [clip(why, 180)],
            "news_label": "DETAILS",
        })
    except Exception:
        log.warning("Crash card failed", exc_info=True)
    await post_alert(client, f"🚨 **{title}**\n{clip(why, 300)}", ping=True, file=card)


def alert_channel_ids(guild_id: int) -> list[int]:
    """Recap first (the group chat), then audit, then tickets."""
    ids = []
    for key in ("recap_channel", "audit_channel", "ticket_channel"):
        v = get_setting(guild_id, key)
        if v and str(v).isdigit():
            n = int(v)
            if n not in ids:
                ids.append(n)
    return ids


def hidden_record_name(name: str) -> bool:
    """A channel whose name is the hidden record, such as hidden-record or hidden_records."""
    words = re.sub(r"[^a-z0-9]+", " ", (name or "").lower()).split()
    return "hidden" in words and any(w.startswith("record") for w in words)


def hidden_record_ids(guild) -> list[int]:
    """Text channels in this server that are named as the hidden record."""
    ids = []
    for ch in list(getattr(guild, "text_channels", None) or []):
        if not hidden_record_name(getattr(ch, "name", "") or ""):
            continue
        cid = getattr(ch, "id", None)
        if cid and int(cid) not in ids:
            ids.append(int(cid))
    return ids


def boot_channel_ids(guild_id: int, guild=None) -> list[int]:
    """Where a new upload is posted: recap, the mods-only record, staff tickets, and a hidden-record channel."""
    ids = list(alert_channel_ids(guild_id))
    for n in hidden_record_ids(guild):
        if n not in ids:
            ids.append(n)
    return ids


def _boot_sent_ids() -> set[int]:
    """Channel ids that already received this version's upload note. An older upload only reached the recap channel."""
    raw = get_setting(0, "bot_announced_where") or ""
    if not raw:
        if (get_setting(0, "bot_announced") or "") != BOT_VERSION:
            return set()
        ids = set()
        for r in db().execute("SELECT value FROM settings WHERE key = 'recap_channel'"):
            if r["value"] and str(r["value"]).isdigit():
                ids.add(int(r["value"]))
        return ids
    try:
        d = json.loads(raw)
    except Exception:
        return set()
    if not isinstance(d, dict) or d.get("version") != BOT_VERSION:
        return set()
    ids = set()
    for x in d.get("ids") or []:
        try:
            ids.add(int(x))
        except (TypeError, ValueError):
            pass
    return ids


def _boot_mark_sent(ids) -> None:
    have = _boot_sent_ids()
    for n in ids or []:
        try:
            have.add(int(n))
        except (TypeError, ValueError):
            pass
    set_setting(0, "bot_announced_where", json.dumps({"version": BOT_VERSION, "ids": sorted(have)}))


def bot_gap_seconds(since: Optional[str]) -> Optional[int]:
    if not since:
        return None
    try:
        t = datetime.fromisoformat(str(since).replace("Z", "+00:00"))
        if t.tzinfo is None:
            t = t.replace(tzinfo=timezone.utc)
        return max(0, int((datetime.now(timezone.utc) - t.astimezone(timezone.utc)).total_seconds()))
    except Exception:
        return None


def bot_gap_words(sec: int) -> str:
    if sec < 90:
        return f"{sec}s"
    if sec < 3600:
        return f"{sec // 60} min"
    h, m = divmod(sec // 60, 60)
    return f"{h}h {m}m" if m else f"{h}h"


def _ver_token(text: str) -> str:
    """The version marker in a string. '2026-10-16 1.39' → '1.39', not a piece of '1.3'."""
    hits = re.findall(r"(r\d+|\d+\.\d+)", str(text or ""), flags=re.I)
    return hits[-1].lower() if hits else ""


def bot_update_lines(prev: str) -> list[str]:
    """Notes for versions after `prev`. Unknown/empty prev → the full current list (first announce)."""
    if not prev:
        return [line for _, line in BOT_UPDATES]
    token = _ver_token(prev)
    started = False
    out = []
    for ver, line in BOT_UPDATES:
        if started:
            out.append(line)
        if token and ver.lower() == token:
            started = True
    if out:
        return out
    cur = _ver_token(BOT_VERSION)
    return [line for ver, line in BOT_UPDATES if ver.lower() == cur]


def fit_alert(text: str, limit: int = 1900) -> str:
    """Keep a channel post under Discord's message cap. The recap stays at the top."""
    body = text or ""
    if len(body) <= limit:
        return body
    tail = "\n• More of this update is on More."
    return body[: max(0, limit - len(tail))].rstrip() + tail


def _recap_lines(prev: str, limit: int = 8) -> list[str]:
    """This upload's line first, then the other new lines, newest first."""
    notes = bot_update_lines(prev)
    cur = _ver_token(BOT_VERSION)
    current = [line for ver, line in BOT_UPDATES if ver.lower() == cur]
    rest = [n for n in reversed(notes) if n not in current]
    out = []
    for line in current + rest:
        if line and line not in out:
            out.append(line)
        if len(out) >= limit:
            break
    return out


def boot_notice(prev_ver: str, gap_sec: Optional[int], planned: bool) -> Optional[str]:
    """The recap-channel note for a new upload and/or a real outage. None when nothing to say."""
    new = (prev_ver or "") != BOT_VERSION
    down = gap_sec is not None and gap_sec >= 180
    if not new and not down:
        return None
    bits = [f"🛠️ **PIMP-BOT is live · {BOT_VERSION}**"]
    if down:
        bits.append("**What happened**")
        bits.append("Back from an update." if planned else f"Was down about {bot_gap_words(gap_sec)}.")
    elif new:
        bits.append("New upload. It was not down long enough to call it an outage.")
    full = bot_update_lines(prev_ver) if new else []
    show = _recap_lines(prev_ver) if new else (bot_update_lines(prev_ver)[:1] if down else [])
    if new:
        bits.append("**Update recap**")
        bits.append(f"This upload is {BOT_VERSION}.")
    if show:
        bits.append("**What's new**")
        bits.extend(f"• {n}" for n in show)
        extra = max(0, len(full) - len(show)) if new else 0
        if extra:
            bits.append(f"• {extra} earlier notes from this update are on More.")
    return "\n".join(bits)


async def _alert_channel(client, cid: int):
    ch = client.get_channel(cid) if cid else None
    if ch is not None:
        return ch
    fetch = getattr(client, "fetch_channel", None)
    if fetch is None:
        return None
    try:
        return await fetch(cid)
    except Exception:
        return None


async def post_alert(client, text: str, *, ping: bool = False, file=None, refresh: bool = False,
                     fanout: bool = False, only: Optional[set] = None, landed: Optional[list] = None) -> int:
    """One message per server, recap channel first. A boot note with fanout also reaches the mods-only record
    and a hidden-record channel. Returns how many channels took it."""
    sent = 0
    guilds = list(getattr(client, "guilds", None) or [])
    gids = [g.id for g in guilds if getattr(g, "id", None)]
    if not gids:
        gids = [r["guild_id"] for r in db().execute(
            "SELECT DISTINCT guild_id FROM settings WHERE key IN ('recap_channel','audit_channel','ticket_channel')")]
    by_gid = {getattr(g, "id", None): g for g in guilds}
    body = fit_alert(text, 1700 if ping else 1900)
    mentions = discord.AllowedMentions.none()
    if ping and OWNER_IDS:
        body = fit_alert(text + "\n" + " ".join(f"<@{i}>" for i in OWNER_IDS[:4]), 1900)
        mentions = discord.AllowedMentions(everyone=False, roles=False, users=True)
    seen = set()

    def _as_file(blob):
        if blob is None:
            return None
        try:
            blob.seek(0)
            return discord.File(blob, filename="status.png")
        except Exception:
            return None

    async def _send(ch, gid):
        blob = file(gid) if callable(file) else file
        attachment = _as_file(blob)
        if attachment is not None:
            try:
                extra = {"view": boot_view()} if refresh else {}
                await ch.send(body, allowed_mentions=mentions, file=attachment, **extra)
                return
            except TypeError:
                pass
            except Exception:
                log.warning("Alert picture failed in channel %s guild %s", getattr(ch, "id", None), gid)
        await ch.send(body, allowed_mentions=mentions)

    for gid in gids:
        if gid in seen:
            continue
        seen.add(gid)
        posted = False
        targets = boot_channel_ids(gid, by_gid.get(gid)) if fanout else alert_channel_ids(gid)
        for cid in targets:
            if only is not None and int(cid) not in only:
                continue
            ch = await _alert_channel(client, cid)
            if ch is None:
                continue
            try:
                await _send(ch, gid)
                posted, sent = True, sent + 1
                if landed is not None:
                    landed.append(int(cid))
                if not fanout:
                    break
            except Exception:
                log.warning("Alert failed in channel %s guild %s", cid, gid)
        if posted:
            continue
        if only is not None:
            continue
        g = by_gid.get(gid)
        sysch = getattr(g, "system_channel", None) if g is not None else None
        if sysch is None:
            continue
        try:
            await _send(sysch, gid)
            sent += 1
            if landed is not None and getattr(sysch, "id", None):
                landed.append(int(sysch.id))
        except Exception:
            log.warning("Alert failed in system channel guild %s", gid)
    return sent


def boot_facts() -> list[tuple[str, str]]:
    """(label, value) pairs for the restart picture. Only facts the bot can measure."""
    free, total, db_n = disk_bytes()
    free_mb = free // (1024 * 1024)
    db_mb = db_n / (1024 * 1024)
    if not total:
        disk = "could not be measured"
    elif free < 50 * 1024 * 1024:
        disk = f"almost full, {free_mb} MB free"
    elif free < 200 * 1024 * 1024:
        disk = f"low, {free_mb} MB free"
    else:
        disk = f"fine, {free_mb} MB free"
    rows = [("Disk", f"{disk}. Picks file {db_mb:.1f} MB.")]
    try:
        rows.append(("Scanner", "on." if TESSERACT else "off on this host."))
    except Exception:
        pass
    try:
        names = []
        if xai_ready():
            names.append("Grok")
        if GROQ_API_KEY:
            names.append("Groq")
        if GEMINI_API_KEY:
            names.append("Gemini")
        if ai_enabled() and claude_alive():
            names.append("Claude")
        elif ai_enabled():
            names.append("Claude paused")
        rows.append(("Answers", (", ".join(names) if names else "none set") + "."))
    except Exception:
        pass
    try:
        err = SLIP_STATE.get("last_error")
    except Exception:
        err = None
    if err and len(err) > 1 and err[1]:
        rows.append(("Last scan problem", clip(str(err[1]), 120)))
    return rows


def boot_health_lines() -> list[str]:
    """A short status block for the recap note. Only facts the bot can measure."""
    return ["**Right now**"] + [f"• {k}: {v}" for k, v in boot_facts()]


def boot_slip_rows(guild_id: Optional[int] = None) -> list[dict]:
    """Open slips for the restart board. Hidden and test slips stay off it."""
    gid = staff_gid(guild_id)
    if not gid:
        return []
    try:
        rows = db().execute(
            "SELECT bettor_name, description, platform, cost, payout FROM picks "
            "WHERE guild_id = ? AND status = 'open' AND (hidden IS NULL OR hidden = 0) "
            "AND (test IS NULL OR test = 0) ORDER BY id DESC LIMIT 8",
            (gid,)).fetchall()
    except Exception:
        return []
    out = []
    for p in rows:
        out.append({"who": p["bettor_name"] or "Slip", "what": p["description"] or "Slip",
                    "book": p["platform"] or "", "cost": p["cost"] or 0, "payout": p["payout"] or 0})
    return out


def boot_view() -> discord.ui.View:
    v = discord.ui.View(timeout=None)
    v.add_item(BootRefreshButton())
    return v


class BootRefreshButton(discord.ui.DynamicItem[discord.ui.Button], template=r"boot:ref"):
    """Redraws the restart board in place."""

    def __init__(self):
        super().__init__(discord.ui.Button(label="🔄 Refresh", style=discord.ButtonStyle.secondary,
                                           custom_id="boot:ref"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls()

    async def callback(self, interaction: discord.Interaction):
        if await sec_button_slow(interaction, "boot_refresh"):
            return
        await interaction.response.defer()
        card = status_card({
            "title": "PIMP-BOT IS LIVE", "tone": "live", "happened": "Refreshed.",
            "news": [], "slips": boot_slip_rows(interaction.guild_id),
        })
        if card is None:
            await interaction.followup.send("I couldn't redraw the board.", ephemeral=True)
            return
        card.seek(0)
        await interaction.edit_original_response(
            attachments=[discord.File(card, filename="status.png")], view=boot_view())


def poster_staff_snapshot() -> dict:
    """Staff HQ numbers for the restart picture. No access key and no addresses."""
    out = {"reads": (0, 0, 0), "feeds": [], "pool": [], "tickets_open": 0, "tickets_closed": 0,
           "tickets": [], "devices": 0, "update": ROADMAP_NOW, "uptime": "", "last_job": "", "asks": 0}
    sure = confirm = failed = 0
    for i in range(7):
        day = (datetime.now(TZ).date() - timedelta(days=i)).isoformat()
        try:
            counts = json.loads(get_setting(0, f"slipreads:{day}") or "{}")
        except Exception:
            counts = {}
        if not isinstance(counts, dict):
            continue
        def num(key, src=counts):
            return int(src[key]) if str(src.get(key) or "").isdigit() else 0
        sure += num("scan")
        confirm += num("scan_confirm")
        failed += num("fail")
    out["reads"] = (sure, confirm, failed)
    try:
        out["asks"] = int(get_setting(0, f"asks:{datetime.now(TZ).date().isoformat()}") or 0)
    except Exception:
        pass
    try:
        health = dash30_health()
        out["uptime"] = str(health.get("uptime") or "")
        out["last_job"] = str(health.get("last_job") or "")
        for feed in (health.get("feeds") or [])[:6]:
            state = str(feed.get("state") or "idle")
            if state == "idle":
                detail = "waiting for a call"
            else:
                detail = f"{int(feed.get('ok') or 0)} ok · {int(feed.get('fail') or 0)} fail"
                if feed.get("last_ok"):
                    detail += " · " + str(feed["last_ok"])
            out["feeds"].append({"name": str(feed.get("name") or "feed"), "state": state, "detail": detail})
        cycle = health.get("cycle") or {}
        failing = len((health.get("jobs") or {}).get("failing") or [])
        out["feeds"].append({
            "name": "Robot loop",
            "state": "ok" if cycle.get("ok") else "idle",
            "detail": (("ran " + str(cycle.get("ago"))) if cycle.get("ago") else "just started")
                      + (f" · {failing} jobs failing" if failing else ""),
        })
    except Exception:
        log.warning("Poster feeds failed", exc_info=True)
    try:
        out["pool"] = [
            {"name": "Grok", "on": bool(xai_ready())},
            {"name": "Groq", "on": bool(GROQ_API_KEY)},
            {"name": "Gemini", "on": bool(GEMINI_API_KEY)},
            {"name": "Claude", "on": bool(ANTHROPIC_API_KEY) and claude_alive()},
        ]
    except Exception:
        pass
    try:
        out["devices"] = len(dash_devices())
    except Exception:
        pass
    try:
        gid = staff_gid()
        open_n = db().execute(
            "SELECT COUNT(*) AS n FROM staff_tickets WHERE guild_id = ? AND status = 'open'",
            (gid,)).fetchone()["n"]
        lines = []
        for row in db().execute(
                "SELECT author_name, text FROM staff_tickets WHERE guild_id = ? AND status = 'open' "
                "ORDER BY id DESC LIMIT 3", (gid,)):
            lines.append(f"{row['author_name']}: {clip(row['text'], 72)}")
        needs = dash_needs(gid)
        open_n += len(needs)
        for need in needs[:3]:
            if len(lines) >= 3:
                break
            lines.append(f"{need.get('who') or 'Slip'}: {need.get('why') or ''}")
        week = iso(datetime.now(timezone.utc) - timedelta(days=7))
        closed = db().execute(
            "SELECT COUNT(*) AS n FROM picks WHERE guild_id = ? AND status != 'open' AND settled_at >= ?",
            (gid, week)).fetchone()["n"]
        out["tickets_open"] = int(open_n or 0)
        out["tickets_closed"] = int(closed or 0)
        out["tickets"] = lines
    except Exception:
        log.warning("Poster tickets failed", exc_info=True)
    return out


def _boot_clock() -> str:
    now = datetime.now(TZ)
    try:
        return now.strftime("%a %b %-d · %-I:%M %p")
    except ValueError:
        return now.strftime("%a %b %d · %I:%M %p")


def status_card(data: dict) -> Optional[io.BytesIO]:
    """Tonight's Board style picture for a restart or a crash. A plain board if the full draw fails."""
    payload = dict(data)
    try:
        payload.setdefault("when", _boot_clock())
        payload.setdefault("rows", boot_facts())
        if "staff" not in payload:
            try:
                payload["staff"] = poster_staff_snapshot()
            except Exception:
                log.warning("Staff snapshot failed", exc_info=True)
                payload["staff"] = {}
        return render_status_card(payload)
    except Exception:
        log.warning("Status card failed", exc_info=True)
        try:
            return render_status_fallback(payload)
        except Exception:
            log.warning("Status fallback failed", exc_info=True)
            return None


async def storage_alert(client) -> None:
    """Once a night: tell mods and admins when the disk or the scanner needs a person."""
    free, total, db_n = disk_bytes()
    today = datetime.now(TZ).date().isoformat()
    try:
        counts = json.loads(get_setting(0, f"slipreads:{today}") or "{}")
    except ValueError:
        counts = {}
    fails = int(counts.get("fail") or 0)
    if free and free < 200 * 1024 * 1024:
        await crash_notify(client, "bot", "Storage is low",
                           f"{free // (1024 * 1024)} MB free of {total // (1024 * 1024)} MB. "
                           f"Database is {db_n // (1024 * 1024)} MB. Old backup copies were removed.")
    if fails >= 8:
        await crash_notify(client, "bot", "Scanner missed a lot today",
                           f"{fails} screenshots could not be read today. A clearer crop, or a Gemini key, covers the rest.")


async def announce_boot(client) -> Optional[str]:
    """On process start: tell the recap channel, the mods-only record, and a hidden-record channel."""
    try:
        sweep_storage()
    except Exception:
        log.warning("Storage sweep failed", exc_info=True)
    prev = get_setting(0, "bot_announced") or ""
    hb = get_setting(0, "bot_heartbeat")
    planned = bool(get_setting(0, "bot_stopping"))
    gap = bot_gap_seconds(get_setting(0, "bot_disconnect_at") or hb)
    note = boot_notice(prev, gap, planned)
    set_setting(0, "bot_heartbeat", now_iso())
    set_setting(0, "bot_stopping", None)
    set_setting(0, "bot_disconnect_at", None)
    guilds = list(getattr(client, "guilds", None) or [])
    by_gid = {getattr(g, "id", None): g for g in guilds}
    gids = [getattr(g, "id", None) for g in guilds if getattr(g, "id", None)]
    if not gids:
        gids = [r["guild_id"] for r in db().execute(
            "SELECT DISTINCT guild_id FROM settings WHERE key IN ('recap_channel','audit_channel','ticket_channel')")]
    sent_ids = set() if (prev or "") != BOT_VERSION else _boot_sent_ids()
    targets = []
    for gid in gids:
        for cid in boot_channel_ids(gid, by_gid.get(gid)):
            if cid not in targets:
                targets.append(cid)
    missing = [c for c in targets if c not in sent_ids]
    catchup = False
    if not note:
        free, _, _ = disk_bytes()
        low = bool(free) and free < 200 * 1024 * 1024
        if not low and not missing:
            set_setting(0, "bot_announced", BOT_VERSION)
            return None
        if missing and not low:
            catchup = True
            show = _recap_lines(prev) if (prev or "") != BOT_VERSION else (bot_update_lines(prev)[:1] or [])
            bits = [f"🛠️ **PIMP-BOT is live · {BOT_VERSION}**",
                    "**Update recap**",
                    f"This upload is {BOT_VERSION}.",
                    "New upload. The record channel is getting it now."]
            if show:
                bits.append("**What's new**")
                bits.extend(f"• {n}" for n in show)
            note = "\n".join(bits)
        else:
            note = (f"🛠️ **PIMP-BOT is live · {BOT_VERSION} · update {ROADMAP_NOW}**\n"
                    "Storage is low, so this restart is being reported.")
    health = boot_health_lines()
    if health:
        note = note + "\n" + "\n".join(health)
    note = fit_alert(note)
    if not note:
        return None
    crash_note("ok" if planned or prev == BOT_VERSION else "bot", "PIMP-BOT is live",
               clip(note.replace("\n", " · "), 180))
    happened = ""
    if gap and gap >= 180:
        happened = "Back from an update." if planned else f"Was down about {bot_gap_words(gap)}."
    elif (prev or "") != BOT_VERSION:
        happened = "New upload. It was not down long enough to call it an outage."
    elif "Storage is low" in (note or ""):
        happened = "Storage is low, so this restart is being reported."
    fresh = bot_update_lines(prev)
    news = _recap_lines(prev) if (prev or "") != BOT_VERSION else fresh[:1]
    tone = "down" if gap and gap >= 180 and not planned else "live"
    sent = 0
    try:
        def _card(gid, tone=tone, happened=happened, news=news):
            return status_card({
                "title": "PIMP-BOT IS LIVE", "tone": tone, "happened": happened, "news": list(news),
            })

        landed = []
        miss = set(missing)
        sent = await post_alert(client, note, ping=bool(gap and gap >= 180 and not planned and not catchup),
                                file=_card, refresh=True, fanout=True,
                                only=miss if catchup else None, landed=landed)
        for gid in gids:
            raw_recap = get_setting(gid, "recap_channel")
            if not raw_recap or not str(raw_recap).isdigit():
                continue
            recap_id = int(raw_recap)
            if recap_id in landed:
                continue
            if catchup and recap_id not in miss:
                continue
            ch = await _alert_channel(client, recap_id)
            if ch is None:
                continue
            try:
                await ch.send(note, allowed_mentions=discord.AllowedMentions.none())
                landed.append(recap_id)
                sent += 1
            except Exception:
                log.warning("Update recap failed in channel %s", recap_id)
        if landed:
            _boot_mark_sent(landed)
    except Exception:
        log.warning("Boot announce failed")
    if sent:
        set_setting(0, "bot_announced", BOT_VERSION)
        return note
    return ""


def staff_rec(uid: int, gid: Optional[int] = None) -> dict:
    raw = get_setting(staff_gid(gid), f"staff:{uid}") or ""
    if raw.startswith("{"):
        try:
            d = json.loads(raw)
            if isinstance(d, dict):
                return d
        except Exception:
            pass
    return {"state": raw} if raw else {}


def staff_put(uid: int, state: Optional[str], name: Optional[str] = None, gid: Optional[int] = None) -> None:
    prev = staff_rec(uid, gid)
    g = staff_gid(gid)
    if state is None:
        set_setting(g, f"staff:{uid}", None)
        return
    set_setting(g, f"staff:{uid}", json.dumps({
        "state": state, "name": clip(name or prev.get("name") or str(uid), 40)}))


def staff_rows(state: Optional[str] = None, gid: Optional[int] = None) -> list:
    out = []
    for r in db().execute("SELECT key, value FROM settings WHERE guild_id = ? AND key LIKE 'staff:%'",
                          (staff_gid(gid),)):
        uid_s = str(r["key"]).split(":", 1)[-1]
        if not uid_s.isdigit():
            continue
        try:
            d = json.loads(r["value"]) if (r["value"] or "").startswith("{") else {"state": r["value"]}
        except Exception:
            d = {"state": r["value"]}
        if state and d.get("state") != state:
            continue
        out.append({"id": int(uid_s), "name": clip(d.get("name") or uid_s, 40), "state": d.get("state") or ""})
    return out


def staff_web_ok(uid: int, gid: Optional[int] = None) -> bool:
    return crew_at_least(uid, "mod", gid)


def staff_pass(uid: int) -> str:
    sig = hmac.new(dashboard_key().encode(), f"staff:{uid}".encode(), hashlib.sha256).hexdigest()[:24]
    return f"{uid}.{sig}"


def staff_pass_ok(token: Optional[str]) -> Optional[int]:
    if not token or token.count(".") != 1:
        return None
    uid_s, sig = token.split(".", 1)
    if not uid_s.isdigit() or len(sig) != 24:
        return None
    uid = int(uid_s)
    want = staff_pass(uid)
    if len(want) != len(token) or not hmac.compare_digest(want.encode(), token.encode()):
        return None
    if uid in dash_kicked_ids() and uid not in DEVELOPER_IDS and uid not in OWNER_IDS:
        return None
    return uid if staff_web_ok(uid) else None


def staff_site_url(uid: int) -> Optional[str]:
    if not PUBLIC_DOMAIN or not staff_web_ok(uid):
        return None
    return f"https://{PUBLIC_DOMAIN}/staff?pass={staff_pass(uid)}"


def staff_uid_from_request(request) -> Optional[int]:
    tok = (getattr(request, "cookies", None) or {}).get(DASH_STAFF_COOKIE) or ""
    return staff_pass_ok(tok)


def site_look(gid: Optional[int] = None) -> tuple:
    try:
        raw = json.loads(get_setting(staff_gid(gid), "sitelook") or "{}")
    except Exception:
        raw = {}
    if not isinstance(raw, dict):
        raw = {}
    bg = raw.get("bg") if raw.get("bg") in SITE_BGS else "court"
    accent = raw.get("accent") if raw.get("accent") in BRAND_PRESETS else "purple"
    return bg, accent, BRAND_PRESETS[accent]


def site_look_save(bg: Optional[str] = None, accent: Optional[str] = None, gid: Optional[int] = None) -> tuple:
    cur_bg, cur_ac, _ = site_look(gid)
    if bg in SITE_BGS:
        cur_bg = bg
    if accent in BRAND_PRESETS:
        cur_ac = accent
    set_setting(staff_gid(gid), "sitelook", json.dumps({"bg": cur_bg, "accent": cur_ac}))
    return site_look(gid)


def dash_paint_look(html: str) -> str:
    """Default look stays byte-identical to the shipped HTML (tests compare the full page)."""
    bg, accent, rgb = site_look()
    if bg == "court" and accent == "purple":
        return html
    hx = _brand_hex(rgb)
    css = (f"<style id=look>:root{{--brand:{hx};--brand2:{hx}cc;--gold:#f0b429}}"
           f"body{{background:{SITE_BGS[bg][1]}!important}}</style>")
    html = html.replace("</head>", css + "</head>", 1)
    if 'class="v4"' in html:
        html = html.replace('<body class="v4">', f'<body class="v4" data-bg="{bg}" data-accent="{accent}">', 1)
        html = html.replace('<body class="v4 has-staff">',
                            f'<body class="v4 has-staff" data-bg="{bg}" data-accent="{accent}">', 1)
    else:
        html = html.replace("<body>", f'<body data-bg="{bg}" data-accent="{accent}">', 1)
    return html


def dash_staff_inject(html: str, request) -> str:
    if "body.v4" not in html and 'class="v4"' not in html:
        return html
    if not staff_uid_from_request(request):
        return html
    if 'class="staffbtn"' in html:
        return html
    html = html.replace('<body class="v4">', '<body class="v4 has-staff">', 1)
    html = html.replace('<button class="iconbtn" id="theme"',
                        '<a class="staffbtn" href="/staff">Staff HQ</a><button class="iconbtn" id="theme"', 1)
    return html


def staff_log_add(gid: Optional[int], kind: str, text: str, name: str = "") -> None:
    g = staff_gid(gid)
    try:
        items = json.loads(get_setting(g, "staff_log") or "[]")
    except Exception:
        items = []
    if not isinstance(items, list):
        items = []
    items.insert(0, {"kind": clip(kind, 12), "text": clip(text, 140), "name": clip(name, 40), "at": now_iso()})
    set_setting(g, "staff_log", json.dumps(items[:40]))


ASK_QUOTA_DEFAULT = [
    {"id": "new", "name": "New activity 0+", "n": 5},
    {"id": "regular", "name": "Regular activity 5+", "n": 10},
    {"id": "active", "name": "Active activity 15+", "n": 20},
    {"id": "core", "name": "Core activity 40+", "n": 35},
    {"id": "staff", "name": "Mods and owners", "n": 0},
]


def staff_quota_rows(gid: Optional[int] = None) -> list:
    try:
        raw = json.loads(get_setting(staff_gid(gid), "ask_quota") or "[]")
    except Exception:
        raw = []
    by_id = {x.get("id"): x for x in raw if isinstance(x, dict) and x.get("id")}
    out = []
    for row in ASK_QUOTA_DEFAULT:
        cur = by_id.get(row["id"], row)
        n = cur.get("n", row["n"])
        try:
            n = int(n)
        except (TypeError, ValueError):
            n = row["n"]
        out.append({"id": row["id"], "name": row["name"], "n": n,
                    "label": "unlimited" if int(n) == 0 else f"{int(n)} a day"})
    return out


def staff_channel_name(gid: int, cid) -> str:
    try:
        g = bot.get_guild(int(gid))
        ch = g.get_channel(int(cid)) if g else None
        if ch is not None:
            return getattr(ch, "name", None) or str(cid)
    except Exception:
        pass
    return str(cid or "")


def staff_channels(gid: int) -> list:
    out = []
    try:
        g = bot.get_guild(int(gid))
        for ch in list(getattr(g, "text_channels", None) or [])[:40]:
            out.append({"id": ch.id, "name": getattr(ch, "name", str(ch.id))})
    except Exception:
        pass
    if not out:
        for key, label in (("ticket_channel", "staff-tickets"), ("audit_channel", "audit"),
                           ("recap_channel", "recap")):
            cid = get_setting(gid, key)
            if cid:
                out.append({"id": int("".join(c for c in str(cid) if c.isdigit()) or 0), "name": label})
    return [c for c in out if c["id"]]


def acct_clean_name(name: str) -> Optional[str]:
    s = re.sub(r"[^A-Za-z0-9_]+", "_", (name or "").strip())[:24].strip("_")
    return s if len(s) >= 3 else None


def acct_fresh_name(name: str) -> str:
    base = acct_clean_name(name) or "user"
    cand, n = base, 2
    while db().execute("SELECT 1 FROM accounts WHERE name = ?", (cand,)).fetchone():
        cand = clip(f"{base}{n}", 24)
        n += 1
    return cand


def acct_hash(password: str) -> str:
    return hashlib.pbkdf2_hmac("sha256", password.encode(), dashboard_key().encode(), 120000).hex()


def acct_cookie(aid: int) -> str:
    sig = hmac.new(dashboard_key().encode(), f"acct:{aid}".encode(), hashlib.sha256).hexdigest()[:24]
    return f"{aid}.{sig}"


def acct_cookie_ok(token: Optional[str]) -> Optional[int]:
    if not token or token.count(".") != 1:
        return None
    aid_s, sig = token.split(".", 1)
    if not aid_s.isdigit() or len(sig) != 24:
        return None
    want = acct_cookie(int(aid_s))
    if len(want) != len(token) or not hmac.compare_digest(want.encode(), token.encode()):
        return None
    return int(aid_s)


def acct_from_request(request) -> Optional[dict]:
    aid = acct_cookie_ok((getattr(request, "cookies", None) or {}).get(DASH_ACCT_COOKIE) or "")
    if not aid:
        return None
    row = db().execute("SELECT * FROM accounts WHERE id = ?", (aid,)).fetchone()
    return dict(row) if row else None


def acct_touch(aid: int, how: str) -> None:
    db().execute("UPDATE accounts SET last_seen = ? WHERE id = ?", (now_iso(), aid))
    db().execute("INSERT INTO account_access (account_id, at, how) VALUES (?,?,?)", (aid, now_iso(), clip(how, 40)))
    db().commit()


def acct_login_token(aid: int) -> str:
    exp = str(int(time.time()) + 600)
    sig = hmac.new(dashboard_key().encode(), f"dlogin:{aid}:{exp}".encode(), hashlib.sha256).hexdigest()[:20]
    return f"{aid}.{exp}.{sig}"


def acct_login_ok(token: Optional[str]) -> Optional[int]:
    if not token or token.count(".") != 2:
        return None
    aid_s, exp, sig = token.split(".")
    if not aid_s.isdigit() or not exp.isdigit() or int(exp) < time.time():
        return None
    want = hmac.new(dashboard_key().encode(), f"dlogin:{aid_s}:{exp}".encode(), hashlib.sha256).hexdigest()[:20]
    if len(want) != len(sig) or not hmac.compare_digest(want.encode(), sig.encode()):
        return None
    return int(aid_s)


def staff_ticket_add(guild_id: int, message) -> None:
    text = clip(getattr(message, "content", "") or "(attachment)", 200)
    if not text.strip():
        return
    db().execute(
        "INSERT INTO staff_tickets (guild_id, channel_id, message_id, author_id, author_name, text, status, created_at) "
        "VALUES (?,?,?,?,?,?,?,?)",
        (guild_id, getattr(message.channel, "id", None), getattr(message, "id", None),
         getattr(message.author, "id", None), clip(getattr(message.author, "display_name", None) or "Member", 40),
         text, "open", now_iso()))
    db().commit()


def staff_house_bits(gid: int) -> dict:
    """Week note, test slips, filed-under pairs, today's settles, and one week with legs."""
    now = datetime.now(TZ)
    start = (now - timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    today = now.date()
    names: dict[int, str] = {}
    try:
        for row in db().execute(
                "SELECT bettor_id, bettor_name FROM picks WHERE guild_id = ? AND bettor_id IS NOT NULL", (gid,)):
            names[row["bettor_id"]] = row["bettor_name"]
    except Exception:
        names = {}
    tests, pairs, day = [], [], []
    week: dict[str, list] = {}
    try:
        rows = db().execute(
            "SELECT * FROM picks WHERE guild_id = ? ORDER BY id DESC LIMIT 400", (gid,)).fetchall()
    except Exception:
        rows = []
    for p in rows:
        if unrevealed_hidden(p):
            continue
        test = pick_is_test(p)
        if test and len(tests) < 8:
            tests.append({"id": int(p["id"]), "who": clip(p["bettor_name"], 40),
                          "what": clip(shown_desc(p), 60)})
        logger = int(p["logged_by"] or 0)
        bettor = int(p["bettor_id"] or 0)
        if logger and bettor and logger != bettor and len(pairs) < 12:
            pairs.append({"id": int(p["id"]),
                          "logger": clip(names.get(logger) or "Staff", 40),
                          "bettor": clip(p["bettor_name"], 40)})
        if test:
            continue
        if p["status"] != "open" and len(day) < 40:
            try:
                when = datetime.fromisoformat(p["settled_at"] or "")
            except Exception:
                when = None
            if when is not None:
                if when.tzinfo is None:
                    when = when.replace(tzinfo=timezone.utc)
                if when.astimezone(TZ).date() == today:
                    day.append({"id": int(p["id"]), "who": clip(p["bettor_name"], 40),
                                "what": clip(shown_desc(p), 80), "net": round(pick_net(p), 2)})
        try:
            created = datetime.fromisoformat(p["created_at"] or "")
        except Exception:
            continue
        if created.tzinfo is None:
            created = created.replace(tzinfo=timezone.utc)
        if created.astimezone(TZ) < start:
            continue
        who = clip(p["bettor_name"], 40) or "Member"
        if who not in week and len(week) >= 16:
            continue
        bucket = week.setdefault(who, [])
        if len(bucket) >= 15:
            continue
        try:
            legs = " | ".join(clip(leg["text"], 80) for leg in get_legs(p["id"]))
        except Exception:
            legs = ""
        bucket.append({"id": int(p["id"]), "what": clip(shown_desc(p), 80),
                       "status": p["status"] or "open", "legs": legs})
    return {
        "weekboard": clip(get_setting(gid, "week_board") or "", 280),
        "tests": tests,
        "pairs": pairs,
        "daysettles": day,
        "weekexport": [{"who": name, "rows": items} for name, items in week.items()],
    }


def staff_ops(uid: int) -> dict:
    """Numbers and lists for Staff HQ. Names only; nothing a person typed is marked HTML."""
    gid = staff_gid()
    clean = unsure = failed = 0
    asks = {"ask_groq": 0, "ask_gemini": 0, "ask_claude": 0}
    for i in range(7):
        day = (datetime.now(TZ).date() - timedelta(days=i)).isoformat()
        try:
            c = json.loads(get_setting(0, f"slipreads:{day}") or "{}")
        except Exception:
            c = {}
        if not isinstance(c, dict):
            c = {}
        num = lambda k, d=c: int(d[k]) if str(d.get(k) or "").isdigit() else 0
        clean += num("scan")
        unsure += num("scan_confirm")
        failed += num("fail")
        if i == 0:
            for k in asks:
                asks[k] = num(k)
    tickets = []
    try:
        for t in db().execute(
                "SELECT id, author_name, text, status FROM staff_tickets WHERE guild_id = ? AND status = 'open' "
                "ORDER BY id DESC LIMIT 20", (gid,)):
            tickets.append({"id": "d" + str(t["id"]), "who": clip(t["author_name"], 40),
                            "title": clip(t["text"], 90), "state": "open", "kind": "discord"})
    except Exception:
        pass
    for need in dash_needs(gid)[:12]:
        tickets.append({"id": need.get("id"), "who": need["who"], "title": need["why"], "state": "open",
                        "kind": "grade" if "grade" in (need.get("why") or "").lower() else "pay"})
    try:
        cutoff = iso(datetime.now(timezone.utc) - timedelta(days=4))
        for p in db().execute(
                "SELECT id, bettor_name FROM picks WHERE guild_id = ? AND status = 'open' AND created_at <= ? "
                "AND (hidden IS NULL OR hidden = 0) ORDER BY id LIMIT 8", (gid, cutoff)):
            if not any(t.get("id") == p["id"] for t in tickets):
                tickets.append({"id": p["id"], "who": clip(p["bettor_name"], 40),
                                "title": f"Slip #{p['id']} has been open 4+ days", "state": "open", "kind": "stale"})
    except Exception:
        pass
    closed = 0
    try:
        week = iso(datetime.now(timezone.utc) - timedelta(days=7))
        closed = db().execute(
            "SELECT COUNT(*) AS n FROM picks WHERE guild_id = ? AND status != 'open' AND settled_at >= ?",
            (gid, week)).fetchone()["n"]
        closed += db().execute(
            "SELECT COUNT(*) AS n FROM staff_tickets WHERE guild_id = ? AND status != 'open' "
            "AND COALESCE(closed_at, created_at) >= ?", (gid, week)).fetchone()["n"]
    except Exception:
        pass
    raw_ch = get_setting(gid, "ticket_channel") or ""
    ch_digits = "".join(c for c in str(raw_ch) if c.isdigit())
    ch_label = staff_channel_name(gid, ch_digits) if ch_digits else "staff-tickets"
    if str(ch_label).isdigit():
        ch_label = "staff-tickets"
    try:
        blacklist = json.loads(get_setting(gid, "staff_blacklist") or "[]")
    except Exception:
        blacklist = []
    if not isinstance(blacklist, list):
        blacklist = []
    hits = []
    try:
        for p in db().execute(
                f"SELECT bettor_name, description, settled_at FROM picks WHERE guild_id = ? AND status != 'open' "
                f"AND {_DASH_VISIBLE} ORDER BY settled_at DESC LIMIT 5", (gid,)):
            hits.append({"who": clip(p["bettor_name"], 40), "what": clip(shown_desc(p), 80),
                         "when": local_day(p["settled_at"]) if p["settled_at"] else ""})
    except Exception:
        pass
    try:
        log_rows = json.loads(get_setting(gid, "staff_log") or "[]")
    except Exception:
        log_rows = []
    if not isinstance(log_rows, list):
        log_rows = []
    anns = []
    try:
        for a in db().execute(
                "SELECT text, due_at, sent_at, channel_id FROM announcements WHERE guild_id = ? "
                "ORDER BY COALESCE(sent_at, due_at) DESC LIMIT 6", (gid,)):
            anns.append({"text": clip(a["text"], 120), "due": a["due_at"] or "",
                         "sent": bool(a["sent_at"]),
                         "channel": staff_channel_name(gid, a["channel_id"]) if a["channel_id"] else ""})
    except Exception:
        pass
    crew = []
    for kind in ("developer", "owner", "admin", "mod"):
        for i in crew_ids(kind, gid):
            rec = staff_rec(i, gid)
            crew.append({"id": i, "name": crew_display_name(i, gid), "role": kind})
    pending = staff_rows("pending", gid) if crew_at_least(uid, "owner", gid) else []
    pool = [
        {"name": "Grok (xAI)", "on": xai_ready()},
        {"name": "Groq (free)", "on": bool(env("GROQ_API_KEY", ""))},
        {"name": "Cerebras (free)", "on": bool(env("CEREBRAS_API_KEY", ""))},
        {"name": "OpenRouter (free)", "on": bool(env("OPENROUTER_API_KEY", ""))},
        {"name": "Gemini (free)", "on": bool(env("GEMINI_API_KEY", ""))},
        {"name": "Claude (paid)", "on": bool(ANTHROPIC_API_KEY)},
    ]
    quota = staff_quota_rows(gid)
    servers = []
    try:
        health = dash30_health()
        for f in (health.get("feeds") or [])[:48]:
            st = f.get("state") or "idle"
            detail = []
            if f.get("last_ok"):
                detail.append("last ok " + str(f["last_ok"]))
            elif f.get("ago"):
                detail.append("last ok " + str(f["ago"]))
            if f.get("ok") or f.get("fail"):
                detail.append(f"{int(f.get('ok') or 0)} ok · {int(f.get('fail') or 0)} fail")
            if f.get("code"):
                detail.append("http " + str(f["code"]))
            if st == "idle":
                detail.append("added · waiting for a call")
            elif st == "down":
                detail.append("offline")
            elif st in ("shaky", "warn"):
                detail.append("caution")
            servers.append({"name": f.get("name") or "feed", "state": st, "kind": "feed",
                            "detail": " · ".join(detail), "ago": f.get("last_ok") or f.get("ago") or ""})
        cyc = health.get("cycle") or {}
        jobs = health.get("jobs") or {}
        servers.append({"name": "Robot loop", "state": "ok" if cyc.get("ok") else "down", "kind": "bot",
                        "detail": ("ran " + str(cyc.get("ago") or "never")) + (
                            f" · {len(jobs.get('failing') or [])} job(s) failing" if jobs.get("failing") else "")})
    except Exception:
        pass
    try:
        guilds = list(getattr(bot, "guilds", None) or [])
        guilds.sort(key=lambda g: (0 if str(getattr(g, "id", "")) == str(GUILD_ID) else 1,
                                   (getattr(g, "name", None) or "").lower()))
        for g in guilds[:48]:
            n = getattr(g, "member_count", None) or len(getattr(g, "members", []) or [])
            chans = len(getattr(g, "text_channels", []) or [])
            home = str(getattr(g, "id", "")) == str(GUILD_ID) and bool(GUILD_ID)
            extra = " · home server, commands sync here" if home else ""
            servers.append({"name": clip(getattr(g, "name", None) or str(getattr(g, "id", "")), 40),
                            "state": "ok", "kind": "discord",
                            "detail": f"{n} members · {chans} text channels · id {g.id}{extra}", "ago": ""})
    except Exception:
        pass
    try:
        slog = json.loads(get_setting(0, "slipread_log") or "[]")
    except Exception:
        slog = []
    if not isinstance(slog, list):
        slog = []
    try:
        crashes = json.loads(get_setting(gid, "crash_log") or "[]")
    except Exception:
        crashes = []
    if not isinstance(crashes, list):
        crashes = []
    return {
        "me": {"id": uid, "role": crew_role_name(uid, gid) or "staff", "boss": crew_at_least(uid, "owner", gid)},
        "alerts": depart_open(gid),
        "desk": staff_desk(uid, gid),
        "reads": {"clean": clean, "unsure": unsure, "failed": failed, "slips": [x for x in slog if isinstance(x, dict)][:18]},
        "pool": pool, "quota": quota, "asks": asks, "servers": servers, "channels": staff_channels(gid),
        "tickets": {"channel": ch_label, "closed": int(closed or 0), "open": tickets[:12]},
        "blacklist": [x for x in blacklist if isinstance(x, dict)][:20],
        "hits": hits, "log": log_rows[:12], "announce": anns, "crew": crew, "pending": pending,
        "crashes": [x for x in crashes if isinstance(x, dict)][:12], "version": BOT_VERSION,
        "update": ROADMAP_NOW,
        "netmode": "group" if get_setting(gid, "kpi_net") == "group" else "week",
        "groupnet": round(sum(s["net"] for s in compute_stats(gid)), 2),
        "access": {"key": dash_gate_code(), "day": dash_gate_state().get("day") or "",
                   "used": int(dash_gate_state().get("used") or 0)},
        "devices": [{"id": r.get("id") or "", "who": r.get("who") or "Browser", "ip": r.get("ip") or "",
                     "when": r.get("when") or ""} for r in dash_devices()],
        "photos_today": photos_read_today(),
        **staff_house_bits(gid),
    }


