STAFF_HTML = STAFF_HTML.replace("</style>", SITE_LOOK_CSS + "</style>", 1)
STAFF_HTML = dash_pwa_html(STAFF_HTML)
if "innerHTML" in STAFF_HTML:
    raise RuntimeError("staff page used innerHTML")


def staff_page_html(uid: int, panel: str = "hq") -> str:
    html = STAFF_HTML
    if panel == "pimp":
        html = html.replace('<div class="wrap" id="hq">', '<div class="wrap" id="hq" hidden>', 1)
        html = html.replace('<div class="wrap" id="pimp" hidden>', '<div class="wrap" id="pimp">', 1)
        html = html.replace('id="pimpbtn" type="button" aria-pressed="false"',
                            'id="pimpbtn" type="button" aria-pressed="true"', 1)
        html = html.replace(">PIMP<b>-</b>BOT · STAFF</a>",
                            ">PIMP<b>-</b>BOT · STAFF · TRADING</a>", 1)
    return html


async def dash_staff(request):
    from aiohttp import web
    q = request.query
    token = q.get("pass")
    if token is not None:
        uid = staff_pass_ok(token)
        if uid is None:
            return dash_error(web, request, 403)
        resp = web.Response(status=303, headers={"Location": "/staff"})
        resp.set_cookie(DASH_STAFF_COOKIE, staff_pass(uid), max_age=DASH_STAFF_COOKIE_AGE, path="/",
                        httponly=True, secure=True, samesite="Lax")
        return resp
    uid = staff_uid_from_request(request)
    if uid is None:
        return dash_page(web, 403, "Staff only", "This page is for staff. Everyone else stays on the dashboard.")
    if q.get("bg") or q.get("accent"):
        site_look_save(q.get("bg"), q.get("accent"))
        return web.Response(status=303, headers={"Location": "/staff"})
    target = q.get("approve") or q.get("deny") or q.get("revoke")
    if target is not None:
        if not crew_at_least(uid, "owner") or not str(target).isdigit():
            return dash_error(web, request, 403)
        tid = int(target)
        if q.get("approve"):
            crew_grant("mod", tid, staff_rec(tid).get("name"))
        else:
            crew_revoke(tid)
        return web.Response(status=303, headers={"Location": "/staff"})
    return dash_html(web, dash_paint_look(staff_page_html(uid)))


async def freshen_head_name(gid: int, head: dict) -> dict:
    """Fill the Head admin display name from Discord when the cache only had the id."""
    head = dict(head or {})
    hid = int(head.get("id") or 0)
    head["name"] = readable_name(head.get("name"), hid)
    guild = _guild_for(gid)
    head["role"] = discord_head_role_name(guild)
    if head["name"] or not hid or guild is None:
        return head
    fetch = getattr(guild, "fetch_member", None)
    if not callable(fetch):
        return head
    try:
        member = fetch(int(hid))
        if asyncio.iscoroutine(member):
            member = await member
    except Exception:
        return head
    if member is None:
        return head
    shown = ""
    for attr in ("display_name", "global_name", "name"):
        shown = readable_name(getattr(member, attr, None), hid)
        if shown:
            break
    if shown:
        head["name"] = shown
    return head


async def staff_payload(uid: int) -> dict:
    data = staff_ops(uid)
    desk = data.get("desk") if isinstance(data, dict) else None
    if isinstance(desk, dict) and isinstance(desk.get("head"), dict):
        desk["head"] = await freshen_head_name(staff_gid(), desk["head"])
    return data


async def dash_api_staff(request):
    from aiohttp import web
    uid = staff_uid_from_request(request)
    if uid is None:
        return dash_error(web, request, 403)
    return web.json_response(await staff_payload(uid))


async def _req_json(request) -> dict:
    fn = getattr(request, "json", None)
    if not callable(fn):
        return {}
    try:
        data = fn()
        if asyncio.iscoroutine(data):
            data = await data
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


async def _req_form(request) -> dict:
    fn = getattr(request, "post", None)
    if callable(fn):
        try:
            data = fn()
            if asyncio.iscoroutine(data):
                data = await data
            if hasattr(data, "items"):
                return {str(k): (v if isinstance(v, str) else str(v)) for k, v in dict(data).items()}
        except Exception:
            pass
    q = getattr(request, "query", None) or {}
    return {str(k): str(v) for k, v in dict(q).items()}


def staff_blacklist_save(gid: int, items: list) -> None:
    set_setting(gid, "staff_blacklist", json.dumps(items[:40]))


def staff_quota_save(gid: int, tier: str, n) -> None:
    rows = staff_quota_rows(gid)
    try:
        n = max(0, min(200, int(n)))
    except (TypeError, ValueError):
        return
    out = []
    for row in rows:
        out.append({"id": row["id"], "n": n if row["id"] == tier else row["n"]})
    set_setting(gid, "ask_quota", json.dumps(out))


async def dash_api_staff_post(request):
    from aiohttp import web
    uid = staff_uid_from_request(request)
    if uid is None:
        return dash_error(web, request, 403)
    gid = staff_gid()
    body = await _req_json(request)
    op = str(body.get("op") or "")
    if op == "close":
        tid = str(body.get("id") or "")
        if tid.startswith("d") and tid[1:].isdigit():
            db().execute("UPDATE staff_tickets SET status = 'closed', closed_at = ? WHERE id = ? AND guild_id = ?",
                         (now_iso(), int(tid[1:]), gid))
            db().commit()
            staff_log_add(gid, "ok", f"Closed ticket {tid}", staff_rec(uid, gid).get("name") or str(uid))
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "ban":
        name = clip(str(body.get("name") or ""), 40)
        if name:
            try:
                items = [x for x in json.loads(get_setting(gid, "staff_blacklist") or "[]") if isinstance(x, dict)]
            except Exception:
                items = []
            items.insert(0, {"name": name, "kind": clip(str(body.get("kind") or "player"), 16),
                             "action": clip(str(body.get("action") or "staff alert"), 40)})
            staff_blacklist_save(gid, items)
            staff_log_add(gid, "ban", f"Blacklisted {name}", staff_rec(uid, gid).get("name") or str(uid))
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "unban":
        name = clip(str(body.get("name") or ""), 40)
        try:
            items = [x for x in json.loads(get_setting(gid, "staff_blacklist") or "[]") if isinstance(x, dict)
                     and x.get("name") != name]
        except Exception:
            items = []
        staff_blacklist_save(gid, items)
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "quota" and crew_at_least(uid, "owner", gid):
        staff_quota_save(gid, str(body.get("id") or ""), body.get("n"))
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "announce":
        due = parse_due(str(body.get("when") or ""))
        text = clip(str(body.get("text") or ""), 1800)
        ch = str(body.get("channel") or "")
        cid = int(ch) if ch.isdigit() else 0
        if due is None or not text:
            return web.json_response({"ok": False, "error": "Need a message and a time I can read."}, status=400)
        if not cid:
            chans = staff_channels(gid)
            cid = chans[0]["id"] if chans else 0
        if not cid:
            return web.json_response({"ok": False, "error": "Pick a channel."}, status=400)
        db().execute(
            "INSERT INTO announcements (guild_id, channel_id, text, due_at, created_by, created_at) VALUES (?,?,?,?,?,?)",
            (gid, cid, text, iso(due), uid, now_iso()))
        db().commit()
        staff_log_add(gid, "ok", "Scheduled an announcement", staff_rec(uid, gid).get("name") or str(uid))
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "netmode" and crew_at_least(uid, "admin", gid):
        mode = "group" if str(body.get("mode") or "") == "group" else None
        set_setting(gid, "kpi_net", mode)
        staff_log_add(gid, "ok", "Switched the board tile to group net" if mode else "Switched the board tile to week net",
                      staff_rec(uid, gid).get("name") or str(uid))
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "weekboard" and crew_at_least(uid, "admin", gid):
        text = clip(str(body.get("text") or ""), 280)
        set_setting(gid, "week_board", text or None)
        staff_log_add(gid, "ok", "Pinned the week board" if text else "Cleared the week board",
                      staff_rec(uid, gid).get("name") or str(uid))
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "kick":
        dash_kick_sessions()
        staff_log_add(gid, "ok", "Signed everyone out of the dashboard",
                      staff_rec(uid, gid).get("name") or str(uid))
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "revoke":
        who = staff_rec(uid, gid).get("name") or str(uid)
        if dash_revoke_device(str(body.get("id") or "")):
            staff_log_add(gid, "ok", "Signed one browser out of the dashboard", who)
        return web.json_response({"ok": True, **await staff_payload(uid)})
    if op == "role":
        if not crew_at_least(uid, "owner", gid):
            return web.json_response({"ok": False, "error": "Developer and owner only."}, status=403)
        mode = str(body.get("mode") or "")
        if mode == "label":
            ok, note = role_label_set(gid, body.get("role"), body.get("label"))
            if not ok:
                return web.json_response({"ok": False, "error": note}, status=400)
            staff_log_add(gid, "ok", note, crew_display_name(uid, gid))
            return web.json_response({"ok": True, "note": note, **await staff_payload(uid)})
        if mode not in ("add", "remove"):
            return web.json_response({"ok": False, "error": "Pick give or take."}, status=400)
        person, _name = resolve_desk_person(gid, str(body.get("who") or ""))
        if person is None:
            return web.json_response(
                {"ok": False, "error": "Pick a person who is still in the server, or paste their Discord ID."},
                status=400)
        role_raw = str(body.get("role") or "")
        if not role_raw.isdigit():
            return web.json_response({"ok": False, "error": "Pick a Discord role."}, status=400)
        ok, note = await switch_discord_role(gid, int(role_raw), person, mode == "add", uid)
        if not ok:
            return web.json_response({"ok": False, "error": note, "warn": True}, status=400)
        if " is on " in note or " is off " in note:
            staff_log_add(gid, "ok", note, crew_display_name(uid, gid))
        return web.json_response({"ok": True, "note": note, **await staff_payload(uid)})
    if op == "seat":
        if not crew_at_least(uid, "owner", gid):
            return web.json_response({"ok": False, "error": "Developer and owner only."}, status=403)
        ok, note = await staff_seat(uid, gid, body)
        if not ok:
            return web.json_response({"ok": False, "error": note}, status=400)
        return web.json_response({"ok": True, "note": note, "warn": role_note_warn(note), **await staff_payload(uid)})
    return web.json_response({"ok": False}, status=400)


_PIMP = None


def pimp_mod():
    """Load the paper desk without importing it at startup. Paper scripts stay out of the Discord process."""
    global _PIMP
    if _PIMP is not None:
        return _PIMP
    import importlib.util
    import sys
    folder = os.path.join(os.path.dirname(os.path.abspath(__file__)), "paper-bots")
    if folder not in sys.path:
        sys.path.insert(0, folder)
    path = os.path.join(folder, "pimp_desk.py")
    spec = importlib.util.spec_from_file_location("pimp_desk", path)
    if spec is None or spec.loader is None:
        raise RuntimeError("paper desk missing")
    mod = importlib.util.module_from_spec(spec)
    sys.modules["pimp_desk"] = mod
    spec.loader.exec_module(mod)
    try:
        mod.keep_closed_settlements()
    except Exception:
        log.exception("paper settlements")
    # DESK_SERVICE_URL set: the trading service holds the books and runs the
    # timer. Desk calls go there; the staff login and pages stay here.
    import desk_remote
    _PIMP = desk_remote.wrap(mod)
    return _PIMP


def _pimp_access(uid: int, gid: int, desk) -> dict:
    role = crew_role_name(uid, gid)
    return {
        "role": role or "",
        "view": desk.role_can(role, "view"),
        "run": desk.role_can(role, "run"),
        "save": desk.role_can(role, "save"),
        "reset": desk.role_can(role, "reset"),
    }


def _pimp_public(snap: dict, uid: int, gid: int, desk) -> dict:
    body = dict(snap)
    body["access"] = _pimp_access(uid, gid, desk)
    if body.get("error"):
        body["error"] = desk.public_error(body.get("error"))
    return body


async def dash_pimp(request):
    """Staff session only. The public dashboard never links here."""
    from aiohttp import web
    if staff_uid_from_request(request) is None:
        return dash_page(web, 403, "Staff only", "This page is for staff. Everyone else stays on the dashboard.")
    return dash_html(web, dash_paint_look(staff_page_html(0, "pimp")))


def pimp_city_root() -> str:
    """Built Vite bundle for APEX-CITY (trading-city/dist)."""
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "trading-city", "dist")


async def dash_pimp_city(request):
    """Neon city shell. Live trades stay staff-only on /api/pimp-trading.json.

    The HTML is not staff-gated: a Home Assistant iframe does not send the
    Lax staff cookie, and a 403 here is what left the APEX-CITY view blank.
    Logged-out viewers get the offline fixture. A staff session still gets
    the live snapshot.
    """
    from aiohttp import web
    import mimetypes

    root = os.path.realpath(pimp_city_root())
    index = os.path.join(root, "index.html")
    if not os.path.isfile(index):
        return dash_page(
            web, 503, "APEX-CITY not built",
            "Build the city UI with: cd trading-city && npm ci && npm run build",
        )
    tail = (request.match_info.get("tail") or "").lstrip("/")
    if ".." in tail.split("/"):
        return dash_error(web, request, 400)
    target = os.path.realpath(os.path.join(root, tail)) if tail else index
    if not target.startswith(root + os.sep) and target != root:
        return dash_error(web, request, 400)
    if os.path.isdir(target):
        target = os.path.join(target, "index.html")
    if not os.path.isfile(target):
        # SPA fallback — client routes stay on index.html
        target = index
    ctype = mimetypes.guess_type(target)[0] or "application/octet-stream"
    if target.endswith(".html"):
        ctype = "text/html; charset=utf-8"
    resp = web.FileResponse(target)
    resp.content_type = ctype
    resp.headers["Cache-Control"] = "no-store" if target.endswith(".html") else "public, max-age=3600"
    resp.headers["X-Content-Type-Options"] = "nosniff"
    return resp


async def dash_api_pimp(request):
    from aiohttp import web
    uid = staff_uid_from_request(request)
    if uid is None:
        return dash_error(web, request, 403)
    gid = staff_gid()
    try:
        desk = pimp_mod()
    except Exception:
        log.exception("pimp desk")
        return web.json_response({"ok": False, "error": "The paper desk is not on this checkout."}, status=500)
    if str(request.query.get("export") or "") == "xlsx":
        try:
            data = await asyncio.get_running_loop().run_in_executor(None, desk.export_xlsx)
        except Exception:
            log.exception("pimp export")
            return web.json_response({"ok": False, "error": "Could not build the paper workbook."}, status=500)
        resp = web.Response(body=data, content_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
        resp.headers["Content-Disposition"] = 'attachment; filename="pimp-paper-book.xlsx"'
        return resp
    try:
        page = int(request.query.get("page") or 1)
    except (TypeError, ValueError):
        page = 1
    try:
        q, filt = str(request.query.get("q") or ""), str(request.query.get("filter") or "all")
        body = await asyncio.get_running_loop().run_in_executor(None, lambda: desk.snapshot(q=q, filt=filt, page=page))
    except Exception:
        log.exception("pimp snapshot")
        return web.json_response({"ok": False, "error": "Could not read the paper desk."}, status=500)
    return web.json_response(_pimp_public(body, uid, gid, desk))


async def dash_api_pimp_post(request):
    from aiohttp import web
    uid = staff_uid_from_request(request)
    if uid is None:
        return dash_error(web, request, 403)
    gid = staff_gid()
    who = staff_rec(uid, gid).get("name") or str(uid)
    body = await _req_json(request)
    op = str(body.get("op") or "")
    try:
        desk = pimp_mod()
    except Exception:
        log.exception("pimp desk")
        return web.json_response({"ok": False, "error": "The paper desk is not on this checkout."}, status=500)
    role = crew_role_name(uid, gid)
    loop = asyncio.get_running_loop()

    async def denied(err: str, status: int = 403):
        snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
        return web.json_response({"ok": False, "error": desk.public_error(err) or "Staff only.", **snap}, status=status)

    try:
        if op == "save":
            err = desk.auth_error(role, "save")
            if err:
                return await denied(err)
            raw = body.get("settings") if isinstance(body.get("settings"), dict) else {}
            cfg, err = await loop.run_in_executor(None, lambda: desk.save_settings(raw, who=who))
            snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
            if err:
                return web.json_response({"ok": False, "error": desk.public_error(err), **snap}, status=400)
            staff_log_add(gid, "ok", "Saved paper desk limits", who)
            return web.json_response({"ok": True, **snap, "limits": cfg})
        if op == "run":
            err = desk.auth_error(role, "run")
            if err:
                return await denied(err)
            bot_id = str(body.get("bot") or "")
            action = str(body.get("action") or "run")
            result = await loop.run_in_executor(
                None, lambda: desk.run_bot(bot_id, action, manual=True, stake=body.get("stake"), prob=body.get("prob")))
            if result.get("ok"):
                staff_log_add(gid, "ok", f"Paper check {bot_id} {action}", who)
            snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
            status = 200 if result.get("ok") else (409 if result.get("blocked") else 400)
            return web.json_response({"ok": bool(result.get("ok")), "error": desk.public_error(result.get("error") or ""), **snap}, status=status)
        if op == "run-due":
            err = desk.auth_error(role, "run")
            if err:
                return await denied(err)
            result = await loop.run_in_executor(None, desk.run_due)
            if result.get("ok"):
                staff_log_add(gid, "ok", "Ran the paper checks that were due", who)
            snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
            status = 200 if result.get("ok") else 429
            return web.json_response({"ok": bool(result.get("ok")), "error": desk.public_error(result.get("error") or ""), **snap}, status=status)
        if op == "pause":
            err = desk.auth_error(role, "pause")
            if err:
                return await denied(err)
            result = await loop.run_in_executor(None, lambda: desk.set_pause(
                None, str(body.get("bot") or ""), bool(body.get("on")), who, bool(body.get("all"))))
            snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
            if result.get("ok"):
                staff_log_add(gid, "ok", result.get("summary") or "Paused a paper bot", who)
            status = 200 if result.get("ok") else 400
            return web.json_response({"ok": bool(result.get("ok")), "error": desk.public_error(result.get("error") or ""), **snap}, status=status)
        if op == "note":
            err = desk.auth_error(role, "note")
            if err:
                return await denied(err)
            result = await loop.run_in_executor(None, lambda: desk.annotate(
                None, str(body.get("bot") or ""), str(body.get("trade") or ""),
                str(body.get("note") or ""), body.get("skipped"), body.get("stake_idea"), who))
            snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
            status = 200 if result.get("ok") else 400
            return web.json_response({"ok": bool(result.get("ok")), "error": desk.public_error(result.get("error") or ""), **snap}, status=status)
        if op == "seen":
            await loop.run_in_executor(None, desk.mark_seen)
            snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
            return web.json_response({"ok": True, **snap})
        if op == "reset":
            err = desk.auth_error(role, "reset")
            if err:
                return await denied(err)
            confirm = desk.confirm_reset(str(body.get("confirm") or ""))
            if confirm:
                snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
                return web.json_response({"ok": False, "error": confirm, **snap}, status=400)
            bot_id = str(body.get("bot") or "")
            result = await loop.run_in_executor(None, lambda: desk.reset_bot(bot_id, who=who))
            if result.get("ok"):
                staff_log_add(gid, "ok", f"Reset paper state {bot_id}", who)
            snap = _pimp_public(await loop.run_in_executor(None, desk.snapshot), uid, gid, desk)
            status = 200 if result.get("ok") else 400
            return web.json_response(
                {"ok": bool(result.get("ok")), "error": desk.public_error(result.get("error") or ""), **snap},
                status=status)
    except Exception:
        log.exception("pimp desk")
        return web.json_response({"ok": False, "error": "The paper desk could not finish that."}, status=500)
    return web.json_response({"ok": False, "error": "Unknown action."}, status=400)


