def free_counts_line() -> str:
    try:
        counts = json.loads(get_setting(0, f"slipreads:{datetime.now(TZ).date().isoformat()}") or "{}")
    except ValueError:
        counts = {}
    names = {"scan": "free scan", "scan_confirm": "free scan (confirmed by hand)", "fail": "failed reads",
             "gemini": "Gemini (free)",
             "claude": "Claude", "ask_gemini": "questions on Gemini (free)", "ask_claude": "questions on Claude",
             "ask_groq": "questions on Groq (free)"}
    parts = [f"{counts[k]} {names.get(k, k)}" for k in ("scan", "scan_confirm", "fail", "gemini", "claude", "ask_groq",
                                                         "ask_gemini", "ask_claude") if counts.get(k)]
    on = [names[r] if r != "scan" else "free scan" for r in SLIP_READERS
          if (r == "scan" and TESSERACT) or (r == "gemini" and GEMINI_API_KEY) or (r == "claude" and ai_enabled())]
    return (" · ".join(parts) or "none yet") + "\nReaders on, in order: " + (" → ".join(on) or "none (the form only)")


# ---- the free text scan (pure: runs in a thread, never touches the database) -------------------------

def free_prepare(raw: bytes):
    """(colour image, OCR-ready greyscale image, scale) with dark mode flipped, upscaled so small print reads."""
    from PIL import Image, ImageOps, ImageFilter, ImageStat
    try:
        from pillow_heif import register_heif_opener
        register_heif_opener()
    except Exception:
        pass
    img = Image.open(io.BytesIO(raw))
    sec_check_image(img)
    img.seek(0)
    img = ImageOps.exif_transpose(img).convert("RGB")
    w, h = img.size
    scale = max(1.0, min(3.0, 1600 / max(1, w)))
    if scale > 1.05:
        img = img.resize((round(w * scale), round(h * scale)), Image.LANCZOS)
    grey = img.convert("L")
    if ImageStat.Stat(grey).mean[0] < 128:          # dark mode: Tesseract wants dark text on light
        grey = ImageOps.invert(grey)
    grey = ImageOps.autocontrast(grey, cutoff=1).filter(ImageFilter.UnsharpMask(radius=1.5, percent=80, threshold=2))
    return img, grey, scale


def _free_tess(img, psm: int, extra: Optional[list] = None, tsv: bool = True) -> str:
    buf = io.BytesIO()
    img.save(buf, "PNG")
    args = [TESSERACT, "stdin", "stdout", "--oem", "1", "--psm", str(psm), "-l", "eng"] + (extra or []) + (["tsv"] if tsv else [])
    try:
        r = subprocess.run(args, input=buf.getvalue(), capture_output=True, timeout=6)
    except subprocess.TimeoutExpired:
        return ""
    return r.stdout.decode("utf-8", "replace")


def _free_word_rows(grey, psm: int) -> list[dict]:
    out = []
    for row in _free_tess(grey, psm).splitlines()[1:]:
        f = row.split("\t")
        if len(f) < 12 or f[0] != "5" or not f[11].strip():
            continue
        try:
            out.append({"text": f[11].strip(), "conf": float(f[10]), "x": int(f[6]), "y": int(f[7]), "w": int(f[8]),
                        "h": int(f[9]), "line": (int(f[2]), int(f[3]), int(f[4]))})
        except ValueError:
            continue
    return out


def free_words(grey, psm: int = 4) -> list[dict]:
    """Every word Tesseract saw: {text, conf, x, y, w, h, line} with line = a key shared by words on one line.
    One layout only. A thin read is retried by the scan budget, not by stacking more passes here."""
    return _free_word_rows(grey, psm)


def free_lines(words: list[dict]) -> list[dict]:
    """Words grouped into lines, top to bottom: {words, text, y, h, x0, x1}."""
    groups: dict = {}
    for wd in words:
        groups.setdefault(wd["line"], []).append(wd)
    lines = []
    for ws in groups.values():
        ws.sort(key=lambda w: w["x"])
        lines.append({"words": ws, "text": " ".join(w["text"] for w in ws), "y": min(w["y"] for w in ws),
                      "h": max(w["h"] for w in ws), "x0": min(w["x"] for w in ws),
                      "x1": max(w["x"] + w["w"] for w in ws)})
    lines.sort(key=lambda ln: (ln["y"], ln["x0"]))
    return lines


def free_reocr_number(grey, wd: dict) -> Optional[str]:
    """Read one number box again, zoomed in, digits only (fixes '495' for '49.5')."""
    from PIL import Image
    pad = max(4, wd["h"] // 3)
    box = (max(0, wd["x"] - pad), max(0, wd["y"] - pad), wd["x"] + wd["w"] + pad, wd["y"] + wd["h"] + pad)
    crop = grey.crop(box)
    crop = crop.resize((crop.width * 3, crop.height * 3), Image.LANCZOS)
    txt = _free_tess(crop, 7, ["-c", "tessedit_char_whitelist=0123456789."], tsv=False).strip()
    return txt if re.fullmatch(r"\d{1,4}(?:\.\d)?", txt) else None


def free_arrow(img, box: tuple) -> Optional[str]:
    """'over' for an up arrow, 'under' for a down arrow, from where the arrow's head (its widest part) sits."""
    x0, y0, x1, y1 = (int(v) for v in box)
    x0, y0, x1, y1 = max(0, x0), max(0, y0), min(img.width, x1), min(img.height, y1)
    if x1 - x0 < 4 or y1 - y0 < 6:
        return None
    crop = img.crop((x0, y0, x1, y1)).convert("L")
    px = crop.load()
    w, h = crop.size
    vals = sorted(px[i, j] for i in range(w) for j in range(h))
    bg = vals[len(vals) // 2]
    rows = []
    for j in range(h):
        rows.append(sum(1 for i in range(w) if abs(px[i, j] - bg) > 60))
    ink = [j for j, n in enumerate(rows) if n]
    if len(ink) < 5:
        return None
    top, bottom = ink[0], ink[-1]
    span = bottom - top + 1
    third = max(1, span // 3)
    upper = sum(rows[top:top + third])
    lower = sum(rows[bottom - third + 1:bottom + 1])
    if upper > lower * 1.25:
        return "over"
    if lower > upper * 1.25:
        return "under"
    return None


def free_green(img, wd: dict) -> float:
    """How much of a word's button is filled green (the picked More/Less on PrizePicks' builder)."""
    pad = wd["h"]
    crop = img.crop((max(0, wd["x"] - pad), max(0, wd["y"] - pad // 2), wd["x"] + wd["w"] + pad,
                     wd["y"] + wd["h"] + pad // 2))
    px = list(crop.getdata())
    green = sum(1 for r, g, b in px if g > 150 and g > r + 50 and g > b + 50)
    return green / max(1, len(px))


def free_green_side(img, top: float, bottom: float) -> Optional[str]:
    """On the builder screen the picked button is filled green: Less sits left of More."""
    w = img.width
    crop = img.crop((int(w * 0.55), max(0, int(top)), w, min(img.height, int(bottom))))
    pts = [i % crop.width for i, (r, g, b) in enumerate(crop.getdata()) if g > 150 and g > r + 50 and g > b + 50]
    if len(pts) < 50:
        return None
    centre = (sum(pts) / len(pts) + w * 0.55) / w
    return "over" if centre > 0.78 else "under"


def _free_numtext(t: str) -> str:
    """'«12.5' -> '12.5', '49,5' -> '49.5' (icons and punctuation OCR glues onto a number)."""
    if re.search(r"[#:$%/x]|\d\s*['’]?\s*[a-wyz]", t, re.I):   # jersey numbers, times, money, '37.5x', '6pm', "180's"
        return ""
    core = re.sub(r"^[^\d]+|[^\d]+$", "", t).replace(",", ".")
    lead = re.match(r"^[^\d]*", t).group(0)
    if lead[-1:] in (".", ",") and lead[-2:-1] in ("", "O", "o", "D", "Q"):
        core = "0." + core                     # "O.5" / ".5" is 0.5
    return core


def _free_stat_in(text: str) -> Optional[tuple[str, int]]:
    """(stat name, where it starts) for the stat printed in this line, if any."""
    text = (text or "").replace("’", "'").replace("`", "'")
    for name, rx in _FREE_STAT_RX:
        m = rx.search(text)
        if m:
            return name, m.start()
    return None


def free_glyph_side(text: str) -> Optional[str]:
    """The over/under arrow when OCR kept the glyph, which is more reliable than guessing from pixels."""
    if re.search(r"[↑▲]", text or ""):
        return "over"
    if re.search(r"[↓▼]", text or ""):
        return "under"
    return None


_FREE_LABEL_JUNK = re.compile(
    r"\b(?:vs|am|pm|refund|payout|prizepicks|flex|power|play|pick|picks|entry|slide|early|self|available|"
    r"time|remaining|mlb|nba|nbap|nhl|wnba|nfl|cfb|cbb|ncaaf|ncaab|tennis|darts|cricket|soccer|today|"
    r"tomorrow|mon|tue|wed|thu|fri|sat|sun)\b", re.I)


def _free_label(text: str) -> Optional[str]:
    """A stat printed in the right-hand box that isn't in the known list, kept so the leg still logs."""
    raw = (text or "").replace("’", "'")
    if re.search(r"\d{1,2}:\d{2}|\$", raw):
        return None
    known = _free_stat_in(raw)
    if known:
        return known[0]
    t = " ".join(re.sub(r"[^A-Za-z0-9+.'’\- ]", " ", raw).split())
    if not t or len(t) < 2 or len(t) > 28 or not re.search(r"[A-Za-z]", t):
        return None
    words = t.split()
    if not 1 <= len(words) <= 4 or _FREE_LABEL_JUNK.search(t):
        return None
    return t


def _free_combo_name(line: dict) -> Optional[str]:
    """'Gabby Williams + Rhyne Howard' is one combo card, even when the stat sits on the same line."""
    text = re.sub(r"\s+", " ", line.get("text") or "").strip()
    m = re.search(
        r"([A-Z][\w'’.\-]+(?:\s+[A-Z][\w'’.\-]+){0,2})\s*\+\s*([A-Z][\w'’.\-]+(?:\s+[A-Z][\w'’.\-]+){0,2})",
        text)
    if not m:
        return None
    a, b = m.group(1), m.group(2)
    if len(a.split()) < 2 or len(b.split()) < 2 or _free_stat_in(a) or _free_stat_in(b):
        return None
    return f"{a} + {b}"


def _free_named(line: dict, max_x: Optional[float] = None) -> Optional[str]:
    return _free_combo_name(line) or _free_name(line, max_x)


def _free_name(line: dict, max_x: Optional[float] = None) -> Optional[str]:
    """A player's name at the start of a line (skipping OCR noise from photos and icons)."""
    text = " ".join(t for t in line["text"].split() if not ("@" in t and free_pill_num(t)))
    if re.search(r"vs\b|\d{1,2}:\d{2}|@|\$|#\s?\d", text, re.I) or re.search(
            r"\b(defender|midfielder|attacker|forward|goalkeeper|guard|center|qb|rb|wr|te|lw|rw|sp|rp)\b", line["text"], re.I):
        return None                            # a game header, an amount, or a team/position/jersey line
    toks = [w["text"].strip(",;:|()[]{}©@&*") for w in line["words"] if not ("@" in w["text"] and free_pill_num(w["text"]))
            and (max_x is None or w["x"] < max_x)]
    best: list[str] = []
    run: list[str] = []
    for t in toks + [""]:
        ok = bool(t) and _FREE_NAME_TOKEN.match(t) and t.lower() not in _FREE_JUNK and not any(c.isdigit() for c in t)
        if ok:
            run.append(t)
            continue
        while run and len(run[-1]) <= 2 and run[-1] not in ("Jr", "Sr", "II", "IV") and len(run) > 1:
            run.pop()                          # trailing icon noise like "Vv"
        while len(run) > 2 and len(run[0]) <= 2 and not run[0].isupper():
            run.pop(0)                         # leading noise like "Ps" (but "OG Anunoby", "AJ Brown" stay)
        while len(run) > 2 and len(run[0]) == 1:
            run.pop(0)                         # a lone letter from the photo: "A Shohei Ohtani"
        if len(run) >= 4 and len(run[0]) <= 3 and not run[0].isupper() and run[-1] in ("Jr", "Sr", "II", "III", "IV"):
            run.pop(0)                         # "Aan James Cook III": the scrap before a full name with a suffix
        joined = " ".join(run)
        if len(run) >= 2 and not _free_stat_in(joined) and sum(len(x) for x in run) > len(" ".join(best).replace(" ", "")):
            best = run[:]
        run = []
    if len(best) < 2 or len(best) > 4:
        return None
    if all(x.isupper() for x in best):        # "DAL QB", "TB RB": team and position, not a name
        return None
    if _free_stat_in(" ".join(best)):         # "Pass Yards" is a stat, not a person
        return None
    return " ".join(best)


_FREE_PILL = re.compile(r"^[^\w]*[vVtTrRlI1↑↓]?([0-9oOsS]{1,2}(?:[.,][0-9oOsS])?)$")


def free_pill_num(text: str) -> Optional[str]:
    """A number from the pick's box with the over/under arrow glued on: '@r15' -> '15', '@vos' -> '05'."""
    t = _free_numtext(text)
    if t:
        return t
    m = _FREE_PILL.match(text or "")
    if not m or not re.search(r"[sS5]", m.group(1)):
        return None
    return m.group(1).translate(str.maketrans("oOsS,", "0055."))


def free_slip_result(full: str) -> tuple[str, Optional[float], bool]:
    """(status, returned, hint). A finished win or loss has to say so. 'to win' on an open entry is not a win.
    hint is true when the words look like a result but are not clear enough to grade."""
    low = (full or "").lower()
    cleaned = re.sub(r"\b(faceoffs?|games?|sets?|maps?)\s+won\b", " ", low)
    cleaned = re.sub(r"\bto\s+win\b", " ", cleaned)
    win = bool(re.search(
        r"\b(you won|entry won|slip won|we won|cashed|winner|payout paid|paid out)\b", cleaned))
    loss = bool(re.search(
        r"\b(you lost|entry lost|slip lost|lost entry|did not hit|didn't hit|busted|better luck)\b", cleaned))
    if re.search(r"(?:^|\n)\s*won\b", cleaned):
        win = True
    if re.search(r"(?:^|\n)\s*lost\b", cleaned):
        loss = True
    # PrizePicks prints a Win or Loss chip on a settled card. "to win" was already removed.
    if re.search(r"\bwin\b", cleaned):
        win = True
    if re.search(r"\bloss\b", cleaned):
        loss = True
    paid = re.search(r"\$\s*([\d,]+(?:\.\d{1,2})?)\s*paid\s*\$\s*([\d,]+(?:\.\d{1,2})?)", full or "", re.I)
    paid_back = as_amount(paid.group(2)) if paid else None
    if paid and not loss:
        win = True
    if win and loss:
        return "open", None, True
    if re.search(r"\brefunded\b", cleaned) and not win and not loss:
        return "push", None, False
    if win:
        m = re.search(r"(?:you won|cashed|paid out|payout paid)\s*\$?\s*([\d,]+\.\d{2})", full, re.I)
        if not m:
            m = re.search(r"(?:^|\n)\s*won\s*\$?\s*([\d,]+\.\d{2})", full, re.I)
        if not m:
            m = re.search(r"(?:^|\n)\s*won\s*(?:\n\s*)\$([\d,]+\.\d{2})", full, re.I)
        returned = paid_back if paid_back is not None else (as_amount(m.group(1)) if m else None)
        return "win", returned, False
    if loss:
        return "loss", 0.0, False
    hint = bool(re.search(r"\b(won|lost|cashed|busted)\b", cleaned))
    return "open", None, hint


def free_parse(words: list[dict], img, grey) -> Optional[dict]:
    """A slip from the scan's words, in the same shape the AI readers return, plus '_unsure' with the reasons
    when anything didn't read cleanly. None when it doesn't look like a slip at all."""
    lines = free_lines(words)
    if not lines:
        return None
    full = "\n".join(ln["text"] for ln in lines)
    low = full.lower()
    unsure: list[str] = []
    # platform and entry type
    platform = None
    if "prizepicks" in low or re.search(r"\b(power|flex) play\b", low) or re.search(r"\bless\b.*\bmore\b", low):
        platform = "PrizePicks"
    elif "underdog" in low or re.search(r"\bhigher\b|\blower\b", low):
        platform = "Underdog"
    for book in ("FanDuel", "DraftKings", "BetMGM", "Caesars", "Fanatics", "bet365", "ESPN BET", "Hard Rock",
                 "BetRivers", "Kalshi", "Sleeper", "Dabble", "Betr", "ParlayPlay"):
        if book.lower() in low:
            platform = book
            break
    if platform is None and (re.search(r"\bkalshi\b", low)
                             or (re.search(r"\b(yes|no)\b", low)
                                 and re.search(r"\b\d{1,3}\s*(?:¢|cents)\b", low))):
        platform = "Kalshi"
    has_flex, has_power = bool(re.search(r"\bflex\b|\binsured\b", low)), bool(re.search(r"\bpower\b|\bstandard\b", low))
    entry_type = None if has_flex and has_power else ("flex" if has_flex else ("power" if has_power else None))
    m = re.search(r"(\d{1,2})\s*-?\s*pick", low)
    want = int(m.group(1)) if m and 2 <= int(m.group(1)) <= 12 else None
    # amounts: "$2 paid $3" on a settled card, or "$25 to win $450" on an open entry
    cost = payout = None
    paid_m = re.search(_FREE_MONEY + r"\s*paid\s*" + _FREE_MONEY, full, re.I)
    if paid_m:
        cost, payout = as_amount(paid_m.group(1)), as_amount(paid_m.group(2))
    m = re.search(_FREE_MONEY + r"\s*to\s*(?:win|pay)\s*" + _FREE_MONEY, full, re.I) if not paid_m else None
    if m:
        cost, payout = as_amount(m.group(1)), as_amount(m.group(2))
    elif not paid_m:
        for k, ln in enumerate(lines):
            if re.search(r"entry\s*fee|wager|stake", ln["text"], re.I):
                amounts = re.findall(_FREE_MONEY + r"|(?<![\d.])(\d+\.\d{2})(?!\d)",
                                     " ".join(x["text"] for x in lines[k:k + 3]))
                vals = [as_amount(a or b) for a, b in amounts]
                vals = [v for v in vals if v]
                if len(vals) >= 2:
                    cost, payout = vals[0], vals[1]
                elif vals:
                    cost = vals[0]
                break
    if cost is None:
        unsure.append("the amount risked")
    if payout is None:
        unsure.append("the payout")
    if len(re.findall(r"\b(?:entry fee|to win|power play|flex play)\b", low)) >= 4:
        unsure.append("more than one slip in this photo")
    # legs: anchor on each stat name, take the line number before it, the name above it, and the side
    legs: list[str] = []
    used_lines: set = set()       # a name line belongs to one leg; the same player can be on two lines
    num_hs = sorted(w["h"] for w in words if _FREE_NUM.match(_free_numtext(w["text"])))
    builder = bool(re.search(r"\bless\b", low) and re.search(r"\bmore\b", low))
    used_rows: set = set()
    for k, ln in enumerate(lines):
        blob, joined = ln["text"], False
        if not _free_stat_in(blob) and ln["x0"] > 0.40 * img.width:
            extra = []
            for j in range(k + 1, min(len(lines), k + 3)):
                nxt = " ".join(w["text"] for w in lines[j]["words"] if w["x"] > 0.42 * img.width)
                if not nxt:
                    break
                extra.append(nxt)
                if _free_stat_in(blob + " " + " ".join(extra)):
                    blob = blob + " " + " ".join(extra)
                    joined = True
                    break
        st = _free_stat_in(blob)
        if not st:
            continue
        stat, at = st
        # where the stat sits: on cards with the line in a box on the right, only numbers in that box count
        pos, stat_x = 0, None
        for w in ln["words"]:
            if pos >= at - 1 and stat_x is None:
                stat_x = w["x"]
            pos += len(w["text"]) + 1
        right = stat_x is not None and stat_x > 0.55 * img.width
        if joined and at >= len(ln["text"]):
            right = True
        # the number: on this line before the stat, else the line(s) just above
        cand_lines = [ln] + [lines[j] for j in range(k - 1, max(-1, k - 3), -1)]
        num_words, src = [], None
        whole = None                                          # a bare whole number, used only if no decimal is near
        hn = num_hs[len(num_hs) // 2] if num_hs else 25
        if right:
            for cl in cand_lines[1:]:
                box_ws = [w for w in cl["words"] if w["x"] > 0.55 * img.width]
                if not box_ws:
                    continue
                rw = max(box_ws, key=lambda w: w["x"] + w["w"])
                clean = _free_numtext(rw["text"])
                if "." in clean or len(re.sub(r"\D", "", clean)) > 2:
                    break                                     # a clean number: the usual path reads it
                rr, cy = rw["x"] + rw["w"], rw["y"] + rw["h"] / 2
                fake = {"x": int(rr - 1.8 * hn), "y": int(cy - 0.6 * hn), "w": int(1.8 * hn), "h": int(1.2 * hn),
                        "text": rw["text"], "conf": 100, "_glued": True}
                got = free_reocr_number(grey, fake)
                if got and "." in got:
                    fake["_num"] = got
                    num_words, src = [fake], cl
                break
        for idx, cl in enumerate([] if num_words else cand_lines):
            ws = [w for w in cl["words"] if _FREE_NUM.match(_free_numtext(w["text"]))]
            if right:
                ws = []
                for w in cl["words"]:
                    if w["x"] < 0.55 * img.width:
                        continue                              # avatar and jersey scraps on the left
                    pn = free_pill_num(w["text"])
                    if pn and _FREE_NUM.match(pn):
                        w["_num"] = pn
                        w["_glued"] = not _free_numtext(w["text"])
                        ws.append(w)
            if cl is ln:
                cut = len(ln["text"][:at])
                pos, kept = 0, []
                for w in cl["words"]:
                    if pos < cut and w in ws:
                        kept.append(w)
                    pos += len(w["text"]) + 1
                ws = kept
            ws = [w for w in ws if not re.search(r"#\s*$", cl["text"][:cl["text"].find(w["text"])])]
            dec = [w for w in ws if re.search(r"[.,]\d$", w.get("_num") or _free_numtext(w["text"]))]
            if dec:
                num_words, src = dec, cl
                break
            if ws and whole is None:
                whole = (ws, cl)
            # "13 Rebs+Asts" is a real line. Don't walk past it to the previous leg's 2.5.
            if ws and idx <= 1:
                num_words, src = ws, cl
                break
        if not num_words and whole:
            num_words, src = whole
        if not num_words:
            continue
        wd = max(num_words, key=lambda w: w["x"])            # the new line, never a crossed-out old one
        txt = wd.get("_num") or _free_numtext(wd["text"])
        again = free_reocr_number(grey, wd)
        if again and (("." in again) or "." not in txt):
            txt = again
        try:
            value = float(txt)
        except ValueError:
            continue
        if platform == "PrizePicks" and right and re.fullmatch(r"\d5", txt):
            value = value / 10                                # the dot lost next to the arrow: '25' is 2.5
        if "." not in txt and value >= 100 and txt.endswith("5") and stat not in ("Pass Yards", "Pass+Rush Yds",
                                                                                   "Rush+Rec Yds", "Pitches Thrown"):
            value = value / 10                                # '495' Rec Yards is 49.5
        # the player: the nearest name at or above the number's line
        name, name_at = None, None
        start = lines.index(src)
        order = [start] + ([start + 1] if start + 1 < len(lines) and lines[start + 1]["y"] - src["y"] < 1.2 * src["h"]
                           else []) + list(range(start - 1, max(-1, start - 4), -1))
        for j in order:
            name = _free_named(lines[j], 0.55 * img.width if right else None)
            if name and j not in used_lines:
                name_at = j
                break
            name = None
        if not name:
            # The line above this one already logged this same number and stat. Don't flag it twice.
            if not any(f" {value:g} " in f" {lg} " and stat.lower() in lg.lower() for lg in legs):
                unsure.append(f"a player's name near {value:g} {stat}")
            continue
        used_lines.add(name_at)
        # the side: an arrow glyph OCR kept, else More/Less words (the green one when both show), else the pixels
        side = None
        lo = min(start, name_at if name_at is not None else start)
        near = [w for j in range(lo, min(len(lines), k + 2)) for w in lines[j]["words"]]
        for w in near:
            side = free_glyph_side(w["text"])
            if side:
                break
        words_low = {w["text"].lower().strip("+-↑↓"): w for w in near}
        if side is None and "more" in words_low and "less" in words_low:
            gm, gl = free_green(img, words_low["more"]), free_green(img, words_low["less"])
            side = "over" if gm > gl * 1.5 and gm > 0.08 else ("under" if gl > gm * 1.5 and gl > 0.08 else None)
        elif side is None and (("more" in words_low) ^ ("less" in words_low) or not builder):
            for word, s in (("more", "over"), ("over", "over"), ("higher", "over"), ("less", "under"),
                            ("under", "under"), ("lower", "under")):
                if word in words_low:
                    side = s
                    break
        if side is None and builder:
            top = lines[lo]["y"] - src["h"]
            bottom = ln["y"] + 2 * ln["h"]
            side = free_green_side(img, top, bottom)
        if side is None:
            left = [w for w in src["words"] if w["x"] + w["w"] <= wd["x"] and w["x"] > wd["x"] - 6 * wd["h"]]
            nums_left = [w for w in left if _FREE_NUM.match(_free_numtext(w["text"]))
                         and len(_free_numtext(w["text"])) > 1]      # a lone "4"/"1" is the arrow, misread
            anchor = min(nums_left, key=lambda w: w["x"]) if nums_left else wd
            glyph = [w for w in left if w not in nums_left and w["x"] + w["w"] <= anchor["x"] + 2
                     and w["x"] > anchor["x"] - 3 * wd["h"]]
            if glyph:
                g = max(glyph, key=lambda w: w["x"])
                box = (g["x"] - 4, wd["y"] - wd["h"] * 0.4, g["x"] + g["w"] + 4, wd["y"] + wd["h"] * 1.4)
            else:
                box = (anchor["x"] - 2.2 * wd["h"], wd["y"] - wd["h"] * 0.4, anchor["x"] - 0.15 * wd["h"],
                       wd["y"] + wd["h"] * 1.4)
            side = free_arrow(img, box)
        if side is None and right and wd.get("_glued"):
            # the arrow glued into the number's word: find it just left of the digits, from the box's right edge
            digits = len(f"{value:g}") + (0 if "." in f"{value:g}" else 1)
            rr, cy = wd["x"] + wd["w"], wd["y"] + wd["h"] / 2
            nw = digits * 0.6 * hn
            side = free_arrow(img, (rr - nw - 1.9 * hn, cy - 0.9 * hn, rr - nw - 0.15 * hn, cy + 0.9 * hn))
        if side is None:
            unsure.append(f"over or under for {name}")
            side = "over"
        if num_hs and wd["h"] > 1.35 * num_hs[len(num_hs) // 2] and wd.get("conf", 100) < 60:
            unsure.append(f"the line for {name}")           # an arrow glued onto the number
        if stat.lower().startswith("anytime") and value > 1.5:
            unsure.append(f"the line for {name}")
            value = 0.5
        leg = f"{name} {side} {value:g} {'Anytime TD' if stat.lower().startswith('anytime') else stat}"
        if leg not in legs:
            legs.append(leg)
            used_rows.add(k)
            if joined:
                used_rows.add(min(k + 1, len(lines) - 1))
                used_rows.add(min(k + 2, len(lines) - 1))
    # A stat the list has never seen (a new PrizePicks market) still becomes a leg when it sits in the right box.
    for k, ln in enumerate(lines):
        if k in used_rows or ln["x0"] < 0.48 * img.width:
            continue
        stat = _free_label(ln["text"])
        if not stat:
            continue
        num_w = []
        src = None
        for j in range(k, max(-1, k - 3), -1):
            ws = [w for w in lines[j]["words"] if w["x"] > 0.50 * img.width and _FREE_NUM.match(_free_numtext(w["text"]))]
            if ws:
                num_w, src = ws, lines[j]
                break
        if not num_w:
            continue
        wd = max(num_w, key=lambda w: w["x"])
        try:
            value = float(_free_numtext(wd["text"]))
        except ValueError:
            continue
        name, name_at = None, None
        for j in range(k - 1, max(-1, k - 5), -1):
            name = _free_named(lines[j], 0.55 * img.width)
            if name and j not in used_lines:
                name_at = j
                break
            name = None
        if not name:
            continue
        side = free_glyph_side(ln["text"]) or free_glyph_side(wd["text"])
        if side is None:
            side = free_arrow(img, (wd["x"] - 2.2 * wd["h"], wd["y"] - wd["h"] * 0.4, wd["x"] - 2, wd["y"] + wd["h"] * 1.4))
        if side is None:
            unsure.append(f"over or under for {name}")
            side = "over"
        leg = f"{name} {side} {value:g} {stat}"
        if leg not in legs:
            legs.append(leg)
            used_lines.add(name_at)
            used_rows.add(k)
    status, returned, result_hint = free_slip_result(full)
    if status == "win" and returned is not None and payout is None:
        payout = returned
        unsure = [u for u in unsure if u != "the payout"]
    if not legs:
        if platform and (cost or payout or status != "open"):
            return {"is_slip": True, "platform": platform, "sport": None, "description": "Slip", "legs": [],
                    "cost": cost, "payout": payout, "status": status, "returned": returned, "game_date": None,
                    "entry_type": entry_type, "placed": True, "_unsure": ["the picks"], "_how": "scan",
                    "_result_hint": result_hint}
        return None
    if want and len(legs) != want:
        unsure.append(f"all {want} picks (I found {len(legs)})")
    if not platform:
        platform = "PrizePicks" if entry_type else "Other"
        unsure.append("which app it's from")
    placed = not re.search(r"\bsubmit\b|place entry|add picks|entry fee", low)
    n = want or len(legs)
    desc = (f"{n}-Pick {'Flex' if entry_type == 'flex' else 'Power'} Play" if platform in ("PrizePicks", "Underdog")
            else f"{n}-leg slip" if n > 1 else legs[0])
    sports = []
    for label, rx in (("NFL", r"\bNFL(?:SZN)?\b"), ("NBA", r"\bNBA(?:SZN|P)?\b|\bNBAP\b"), ("NHL", r"\bNHL\b"), ("MLB", r"\bMLB\b"),
                      ("WNBA", r"\bWNBA\b"), ("SOCCER", r"\bSOCCER\b"), ("CFB", r"\bCFB\b|\bNCAAF\b"),
                      ("CBB", r"\bCBB\b|\bNCAAB\b"), ("Tennis", r"\bTENNIS\b"), ("Darts", r"\bDARTS\b"),
                      ("Cricket", r"\bCRICKET\b"), ("Table Tennis", r"(?<![A-Za-z])TT(?![A-Za-z])")):
        if re.search(rx, full):
            sports.append(label)
    slip = {"is_slip": True, "platform": platform, "sport": ", ".join(s.title() if s == "SOCCER" else s for s in sports)
            or None, "description": desc, "legs": legs, "cost": cost, "payout": payout, "status": status,
            "returned": returned, "game_date": None, "entry_type": entry_type, "placed": placed,
            "_unsure": unsure, "_how": "scan", "_result_hint": result_hint}
    apply_scan_bijan_fix(slip)
    return slip


_FREE_MINOR_UNSURE = ("which app it's from",)


def _free_scan_ready(slip) -> bool:
    """Scanner 3.0: first pass is enough when legs + cost are in and leftover notes are only minor
    (unknown app). Extra OCR still runs when a leg, the amount, or a real hole is missing."""
    if not slip or not slip.get("legs") or slip.get("cost") is None:
        return False
    holes = [u for u in (slip.get("_unsure") or [])
             if u not in _FREE_MINOR_UNSURE and not str(u).startswith("more than one slip")]
    return not holes


def _free_slip_parts(words: list[dict]) -> list:
    """Split one photo into separate slips when two pick-count headers sit far apart."""
    lines = free_lines(words)
    heads = [ln for ln in lines if re.search(r"\b\d{1,2}\s*-?\s*pick\b", ln["text"], re.I)]
    if len(heads) < 2:
        return [words]
    heads.sort(key=lambda ln: ln["y"])
    cuts = []
    for a, b in zip(heads, heads[1:]):
        if b["y"] - a["y"] >= 90:
            cuts.append((a["y"] + b["y"]) // 2)
    if not cuts:
        return [words]
    bounds = [0] + cuts + [10 ** 9]
    parts = []
    for lo, hi in zip(bounds, bounds[1:]):
        part = [w for w in words if lo <= w["y"] < hi]
        if part:
            parts.append(part)
    return parts or [words]


def free_scan(raw: bytes) -> Optional[dict]:
    """The whole free scan on one image (sync, for a worker thread). Scanner 2.0: a clean first pass
    is kept as-is; extra treatments (other contrast, a tighter crop, a second Tesseract layout) only
    run when that pass missed the slip or left holes, and they may fill those holes — they never
    replace a sure read with a different one. Scanner 3.0 skips those retries when the first pass
    already has legs and the amount. The whole scan stops after a few seconds so a chat reply isn't stuck typing."""
    started = time.monotonic()
    img, grey, _ = free_prepare(raw)
    words = free_words(grey)
    parts = _free_slip_parts(words)
    if len(parts) > 1:
        slips = []
        for part in parts[:4]:
            one = free_parse(part, img, grey)
            if one and one.get("legs"):
                slips.append(one)
        if len(slips) >= 2:
            head = slips[0]
            head["_extra"] = slips[1:]
            return head
    first = free_parse(words, img, grey)
    if _free_scan_ready(first):
        return first
    best = first
    # A first pass that already has legs only re-reads the bands that can fill the holes.
    # A blank first pass still looks at the whole photo.
    deadline = started + 6
    if time.monotonic() > deadline:
        return best
    retries = (_free_hole_bands(img, grey, first, deadline) if first and first.get("legs")
               else _free_scan_retries(img, grey, deadline))
    for extra in retries:
        if time.monotonic() - started > 6:
            break
        best = _free_fill(best, extra)
        best = _free_tidy(best)
        if _free_scan_ready(best):
            return best
    return best


def _free_hole_bands(img, grey, slip, deadline: float = 0) -> list:
    """Crops for a second pass. Each box is a hole (money, the player list, or the app name), never the whole photo."""
    from PIL import ImageEnhance, ImageOps
    unsure = [str(u) for u in (slip.get("_unsure") or [])]
    w, h = img.size
    boxes = []
    if any(u in ("the amount risked", "the payout") for u in unsure):
        boxes.append((0, int(h * 0.72), w, h))
    if any("name" in u or "over or under" in u or "picks (I found" in u for u in unsure):
        boxes.append((0, int(h * 0.12), w, int(h * 0.78)))
    if any(u == "which app it's from" for u in unsure):
        boxes.append((0, 0, w, max(40, int(h * 0.22))))
    out = []
    for box in boxes:
        if deadline and time.monotonic() > deadline:
            break
        bw, bh = box[2] - box[0], box[3] - box[1]
        if bw < 40 or bh < 40 or bw * bh >= w * h * 0.92:
            continue
        try:
            crop, cgrey = img.crop(box), grey.crop(box)
            punch = ImageOps.autocontrast(ImageEnhance.Contrast(cgrey).enhance(1.6), cutoff=1)
            out.append(free_parse(free_words(punch), crop, punch))
        except Exception:
            log.debug("Hole re-read failed", exc_info=True)
    return [s for s in out if s]


def _free_scan_retries(img, grey, deadline: float = 0) -> list:
    """Other looks at the same picture when the first pass wasn't enough. Each is a free_parse result or None."""
    from PIL import ImageEnhance, ImageOps, ImageFilter
    out = []
    if deadline and time.monotonic() > deadline:
        return out
    try:
        words6 = free_words(grey, 6)
        if words6:
            out.append(free_parse(words6, img, grey))
    except Exception:
        log.debug("Scan retry psm6 failed", exc_info=True)
    if deadline and time.monotonic() > deadline:
        return [s for s in out if s]
    crop = _free_focus(img)
    if crop is not None and crop.size != img.size:
        try:
            cgrey = ImageOps.autocontrast(crop.convert("L"), cutoff=1).filter(
                ImageFilter.UnsharpMask(radius=1.5, percent=80, threshold=2))
            from PIL import ImageStat
            if ImageStat.Stat(cgrey).mean[0] < 128:
                cgrey = ImageOps.invert(cgrey)
            out.append(free_parse(free_words(cgrey), crop, cgrey))
        except Exception:
            log.debug("Scan retry crop failed", exc_info=True)
    if deadline and time.monotonic() > deadline:
        return [s for s in out if s]
    try:
        punch = ImageEnhance.Contrast(grey).enhance(1.85)
        punch = ImageOps.autocontrast(punch, cutoff=2)
        out.append(free_parse(free_words(punch), img, punch))
    except Exception:
        log.debug("Scan retry contrast failed", exc_info=True)
    return [s for s in out if s]


def _free_focus(img):
    """Crop chrome off a tall phone screenshot (status bar / home indicator / side wallpaper)."""
    w, h = img.size
    if h < 1.7 * w:
        return None
    return img.crop((int(w * 0.02), int(h * 0.05), int(w * 0.98), int(h * 0.94)))


def _free_leg_key(leg: str) -> str:
    return re.sub(r" (over|under) [\d.]+ ", " ", (leg or "").lower())


def _free_fill(base: Optional[dict], extra: Optional[dict]) -> Optional[dict]:
    """Copy amounts and missing legs from extra into base. Never drops what base already read."""
    if extra is None:
        return base
    if base is None:
        return extra
    out = dict(base)
    out["legs"] = list(base.get("legs") or [])
    out["_unsure"] = list(base.get("_unsure") or [])
    if out.get("cost") is None and extra.get("cost") is not None:
        out["cost"] = extra["cost"]
        out["_unsure"] = [u for u in out["_unsure"] if u != "the amount risked"]
    if out.get("payout") is None and extra.get("payout") is not None:
        out["payout"] = extra["payout"]
        out["_unsure"] = [u for u in out["_unsure"] if u != "the payout"]
    if not out.get("platform") and extra.get("platform"):
        out["platform"] = extra["platform"]
        out["_unsure"] = [u for u in out["_unsure"] if u != "which app it's from"]
    have = {_free_leg_key(lg) for lg in out["legs"]}
    for lg in extra.get("legs") or []:
        k = _free_leg_key(lg)
        if k and k not in have:
            out["legs"].append(lg)
            have.add(k)
    if extra.get("entry_type") and not out.get("entry_type"):
        out["entry_type"] = extra["entry_type"]
    if extra.get("sport") and not out.get("sport"):
        out["sport"] = extra["sport"]
    if extra.get("status") in ("win", "loss", "push") and out.get("status") not in ("win", "loss", "push"):
        out["status"] = extra["status"]
        if extra.get("returned") is not None:
            out["returned"] = extra["returned"]
        out["_result_hint"] = False
    elif extra.get("_result_hint") and out.get("status") not in ("win", "loss", "push"):
        out["_result_hint"] = True
    return out


def _free_tidy(slip: Optional[dict]) -> Optional[dict]:
    """Drop unsure flags that the fill-in pass resolved, and rebuild the header description."""
    if not slip:
        return slip
    unsure = list(slip.get("_unsure") or [])
    if slip.get("cost") is not None:
        unsure = [u for u in unsure if u != "the amount risked"]
    if slip.get("payout") is not None:
        unsure = [u for u in unsure if u != "the payout"]
    if slip.get("platform"):
        unsure = [u for u in unsure if u != "which app it's from"]
    legs = slip.get("legs") or []
    for u in list(unsure):
        m = re.search(r"all (\d+) picks \(I found (\d+)\)", u)
        if m and int(m.group(1)) == len(legs):
            unsure = [x for x in unsure if "picks (I found" not in x]
            break
    slip["_unsure"] = unsure
    n = len(legs)
    entry = slip.get("entry_type")
    platform = slip.get("platform") or "Other"
    if n and platform in ("PrizePicks", "Underdog"):
        slip["description"] = f"{n}-Pick {'Flex' if entry == 'flex' else 'Power'} Play"
    elif n > 1:
        slip["description"] = f"{n}-leg slip"
    elif n == 1:
        slip["description"] = legs[0]
    return slip


# ---- names: the scan's spelling checked against ESPN's players ---------------------------------------

def _scan_edit_key(leg: str) -> str:
    return re.sub(r"\s+", " ", (leg or "").lower()).strip()


def remember_scan_edits(before: list, after: list) -> None:
    """An Edit correction is kept, so the next screenshot with that same line uses the fixed wording."""
    if len(before) != len(after):
        return
    try:
        edits = json.loads(get_setting(0, "scan_edit") or "{}")
    except Exception:
        edits = {}
    if not isinstance(edits, dict):
        edits = {}
    for old, new in zip(before, after):
        old, new = (old or "").strip(), (new or "").strip()
        if old and new and old != new:
            edits[_scan_edit_key(old)] = new[:180]
    if not edits:
        return
    try:
        keep = dict(list(edits.items())[-40:])
        set_setting(0, "scan_edit", json.dumps(keep)[:4000])
    except Exception:
        pass


def free_apply_edits(slip: dict) -> None:
    try:
        edits = json.loads(get_setting(0, "scan_edit") or "{}")
    except Exception:
        return
    if not isinstance(edits, dict) or not edits:
        return
    legs, changed = [], False
    for leg in slip.get("legs") or []:
        hit = edits.get(_scan_edit_key(leg))
        if isinstance(hit, str) and hit.strip():
            legs.append(hit.strip())
            changed = True
        else:
            legs.append(leg)
    if changed:
        slip["legs"] = legs


# Tesseract reads "Bijan" as "Brian". Only an NFL slip, and only Brian Robinson or a bare
# Brian next to ATL / the Falcons or on a rush-yards line. Brian Burns, Brian Thomas, and
# every other Brian stay as read.
_SCAN_NFL = re.compile(r"\bnfl(?:szn)?\b", re.I)
_SCAN_FALCONS = re.compile(r"\b(?:atl|atlanta|falcons)\b", re.I)
_SCAN_BRIAN_ROBINSON = re.compile(r"\bBrian\s+Robinson(?:\s+(?:Jr\.?|Junior))?(?!\w)", re.I)
_SCAN_OTHER_BRIAN = re.compile(
    r"\bBrian\s+(?!(?:Robinson\b|over\b|under\b|more\b|less\b|[ou]\s*\d))[A-Za-z]", re.I)
_SCAN_BARE_BRIAN = re.compile(
    r"\bBrian\b(?=\s+(?:[ou]\s*\d|over\b|under\b|more\b|less\b)|$)", re.I)
_SCAN_RUSH = re.compile(r"\brush(?:ing)?\s*(?:yds|yards)\b", re.I)


def correct_scanned_brian(line: str, sport: str = "", context: str = "") -> str:
    """One scanned slip line. 'Brian Robinson' or 'Brian o72.5 rush yds' on an NFL slip
    (or next to ATL / Falcons) becomes Bijan Robinson. A different last name is not Bijan."""
    text = "" if line is None else str(line)
    sport = "" if sport is None else str(sport)
    context = "" if context is None else str(context)
    if not text:
        return text
    blob = " ".join((text, sport, context))
    if not (_SCAN_NFL.search(blob) or _SCAN_FALCONS.search(blob)):
        return text
    if _SCAN_OTHER_BRIAN.search(text):
        return text
    if _SCAN_BRIAN_ROBINSON.search(text):
        return _SCAN_BRIAN_ROBINSON.sub("Bijan Robinson", text, count=1)
    around = f"{text} {context}"
    bare_hit = bool(_SCAN_BARE_BRIAN.search(text)) and (
        _SCAN_RUSH.search(text) or _SCAN_FALCONS.search(around) or re.search(r"\brobinson\b", context, re.I))
    if bare_hit:
        return _SCAN_BARE_BRIAN.sub("Bijan Robinson", text, count=1)
    return text


def apply_scan_bijan_fix(slip: dict) -> None:
    """Rewrite Bijan-as-Brian on this scanned slip. Other players on the same slip stay."""
    if not isinstance(slip, dict):
        return
    sport = str(slip.get("sport") or "")
    desc = str(slip.get("description") or "")
    legs = [str(x) for x in (slip.get("legs") or [])]
    context = " ".join([sport, desc, *legs])
    fixed = [correct_scanned_brian(leg, sport=sport, context=context) for leg in legs]
    if fixed == legs:
        return
    slip["legs"] = fixed
    if desc and desc in legs:
        slip["description"] = fixed[legs.index(desc)]


async def free_fix_names(slip: dict) -> None:
    """'Julian Quifiones' -> 'Julián Quiñones' when ESPN has one clear match (best effort, a few seconds).
    Scanner 4.0 also remembers a match in scan_alias so the next screenshot of the same OCR typo is instant.
    An earlier Edit correction is applied first.
    A scanned Brian on an NFL slip, in context of Robinson or ATL or the Falcons, is Bijan Robinson.
    That correction is applied again after the ESPN match so a 0.93 'Brian Robinson' hit cannot put Bijan back."""
    free_apply_edits(slip)
    apply_scan_bijan_fix(slip)
    try:
        aliases = json.loads(get_setting(0, "scan_alias") or "{}")
    except Exception:
        aliases = {}
    if not isinstance(aliases, dict):
        aliases = {}
    async def found(name: str) -> list:
        try:
            raw = await asyncio.wait_for(_get_json(ESPN_SEARCH, {"query": name, "limit": 5, "type": "player"}), 6)
            return [it.get("displayName") or "" for it in (raw.get("items") or []) if isinstance(it, dict)]
        except Exception:
            return []
    legs = slip.get("legs") or []
    sport = str(slip.get("sport") or "")
    scan_context = " ".join([sport, str(slip.get("description") or ""), *[str(x) for x in legs]])
    shapes = [re.match(r"^(.+?) (over|under) ([\d.]+) (.+)$", leg) for leg in legs]
    names, dirty = [], {}
    for m in shapes:
        if not m:
            continue
        raw_name = m.group(1)
        alias = aliases.get(norm_name(raw_name))
        use = alias if isinstance(alias, str) and alias.strip() else raw_name
        dirty[raw_name] = use
        names.append(use)
    names = list(dict.fromkeys(names))
    looked = dict(zip(names, await asyncio.gather(*(found(n) for n in names)))) if names else {}
    fixed, changed = [], False
    name_alts: dict = {}
    for leg, m in zip(legs, shapes):
        if not m:
            fixed.append(leg)
            continue
        raw_name = m.group(1)
        name = dirty.get(raw_name) or raw_name
        items = looked.get(name) or []
        ranked = []
        for it in items:
            if not it:
                continue
            r = difflib.SequenceMatcher(None, norm_name(name), norm_name(it)).ratio()
            ranked.append((r, it))
        ranked.sort(key=lambda pair: pair[0], reverse=True)
        best, score = (ranked[0][1], ranked[0][0]) if ranked else (None, 0.0)
        if best and score >= 0.8 and norm_name(best) != norm_name(raw_name):
            aliases[norm_name(raw_name)] = best
            name, changed = best, True
        elif isinstance(aliases.get(norm_name(raw_name)), str) and aliases[norm_name(raw_name)] != raw_name:
            name = aliases[norm_name(raw_name)]
        # ESPN scores "Brian Robinson" against "Bijan Robinson" at 0.93, so a hit on the real
        # Brian would undo the scan correction. Put Bijan back and remember that spelling.
        fixed_name = correct_scanned_brian(name, sport=sport, context=f"{scan_context} {leg}")
        if fixed_name != name:
            aliases[norm_name(raw_name)] = fixed_name
            name, changed = fixed_name, True
        others = [it for r, it in ranked if r >= 0.55 and norm_name(it) != norm_name(name)][:4]
        if others:
            name_alts[name] = others
        fixed.append(f"{name} {m.group(2)} {m.group(3)} {m.group(4)}")
    if name_alts:
        slip["_name_alts"] = name_alts
    slip["legs"] = fixed
    apply_scan_bijan_fix(slip)
    if changed:
        try:
            keep = {k: aliases[k] for k in list(aliases)[-80:] if isinstance(aliases.get(k), str)}
            set_setting(0, "scan_alias", json.dumps(keep)[:4000])
        except Exception:
            pass


# ---- Gemini (Google's free tier) ------------------------------------------------------------------

async def read_slip_gemini(attachment) -> Optional[dict]:
    """Same job as read_slip, through Gemini. The key goes in a header, never the URL."""
    import aiohttp
    raw = await attachment.read()
    if len(raw) > MAX_IMAGE_BYTES:
        raise SecImageTooBig(f"{len(raw) // 1024} KB")
    try:
        pngs = await asyncio.to_thread(enlarge_slip, raw)
    except Exception:
        pngs = [raw]
    parts = [{"inline_data": {"mime_type": "image/png", "data": base64.standard_b64encode(b).decode()}} for b in pngs[:5]]
    prompt = SLIP_PROMPT
    if len(pngs) > 1:
        prompt = (f"These {len(pngs)} images are ONE screenshot: the first is the whole thing, the rest are enlarged "
                  "slices of it from top to bottom that overlap a little. Count each leg only once.\n\n" + prompt)
    prompt += f"\n\nToday is {datetime.now(TZ):%A, %B %d, %Y}."
    parts.append({"text": prompt})
    body = {"contents": [{"parts": parts}], "generationConfig": {"temperature": 0, "responseMimeType": "application/json"}}
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=8)) as session:
        async with session.post(url, json=body, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
            if resp.status != 200:
                text = (await resp.text())[:300]
                raise RuntimeError(f"Gemini HTTP {resp.status}: {text}")
            data = await resp.json(content_type=None)
    text = "".join(p.get("text", "") for c in (data.get("candidates") or [])[:1]
                   for p in ((c.get("content") or {}).get("parts") or []))
    slip = extract_json(text)
    if not slip.get("is_slip"):
        return None
    slip["cost"] = as_amount(slip.get("cost"))
    slip["payout"] = as_amount(slip.get("payout"))
    slip["returned"] = as_amount(slip.get("returned"))
    if slip.get("status") not in ("open", "win", "loss", "push"):
        slip["status"] = "open"
    slip["placed"] = slip.get("placed") is not False
    return slip


async def gemini_see(attachment, prompt: str, temperature: float = 0.5, tokens: int = 420,
                     timeout: float = 8) -> str:
    """One short look at a screenshot. No enlarged slices, so it comes back in a few seconds."""
    if not GEMINI_API_KEY:
        return ""
    import aiohttp
    raw = await attachment.read()
    if len(raw) > MAX_IMAGE_BYTES:
        return ""
    mt = sniff_image_type(raw) or "image/jpeg"
    body = {"contents": [{"parts": [
        {"inline_data": {"mime_type": mt, "data": base64.standard_b64encode(raw).decode()}},
        {"text": prompt},
    ]}], "generationConfig": {"temperature": temperature, "maxOutputTokens": tokens}}
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=timeout)) as session:
        async with session.post(url, json=body, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
            if resp.status != 200:
                return ""
            data = await resp.json(content_type=None)
    return "".join(p.get("text", "") for c in (data.get("candidates") or [])[:1]
                   for p in ((c.get("content") or {}).get("parts") or [])).strip()


RESULT_CARD_PROMPT = """This is one bet screenshot. Read the card. Reply with ONLY a JSON object, no other text:
{
  "is_slip": true,
  "platform": "PrizePicks" or the app name,
  "description": short header such as "5-Pick Flex Play",
  "legs": ["Player Name over|under LINE stat"],
  "cost": number risked or null,
  "payout": possible pay if it is still open, or null,
  "returned": amount actually paid if the card is already settled, else null,
  "status": "win" or "loss" or "push" or "open"
}
A PrizePicks result card often says "$3 paid $4.50" (cost 3, returned 4.50) with a Win or Loss chip.
Up arrow means over. Down arrow means under. The line is the number at the right of the row. The number sitting on the colored bar is the result, not the line.
Each player row is one leg. Include a row even when it says DNP.
Use "win" when the chip says Win or the header says paid. Use "loss" when the chip says Loss. Use "open" only when the card has no final result.
Do not invent a player who is not on the screen. "to win" on an entry that is still open is not a win.
"""


async def read_result_card(attachment) -> Optional[dict]:
    """A second look for a settled result card when the first read found no legs."""
    if not GEMINI_API_KEY or attachment is None:
        return None
    text = await gemini_see(attachment, RESULT_CARD_PROMPT, temperature=0, tokens=900, timeout=16)
    if not text:
        return None
    try:
        slip = extract_json(text)
    except Exception:
        return None
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()]
    if len(legs) < 1:
        return None
    slip["is_slip"] = True
    slip["legs"] = legs[:12]
    slip["cost"] = as_amount(slip.get("cost"))
    slip["payout"] = as_amount(slip.get("payout"))
    slip["returned"] = as_amount(slip.get("returned"))
    if slip.get("status") not in ("open", "win", "loss", "push"):
        slip["status"] = "open"
    if slip["status"] == "win" and slip.get("returned") is not None and slip.get("payout") is None:
        slip["payout"] = slip["returned"]
    slip["placed"] = True
    slip["_how"] = "card"
    slip.setdefault("platform", "PrizePicks")
    slip.setdefault("description", "Slip")
    return slip


async def slip_with_card(attachment, slip, reason):
    """Keep a read that already has legs. Otherwise try the result-card look once."""
    if slip and slip.get("legs"):
        return slip, reason
    try:
        rescued = await asyncio.wait_for(read_result_card(attachment), timeout=16)
    except Exception:
        log.warning("Result card read failed", exc_info=True)
        rescued = None
    if rescued and rescued.get("legs"):
        return rescued, None
    return slip, reason


async def read_slip_raced(attachment, budget: float = 18):
    """The short result-card look and the full reader run together.
    An open read waits for the card look, so a Win chip is not thrown out for a stats pass."""
    best_task = asyncio.create_task(read_slip_best(attachment))
    card_task = asyncio.create_task(read_result_card(attachment))
    slip, reason, timed_out, held = None, None, False, None
    pending = {best_task, card_task}
    loop = asyncio.get_running_loop()
    deadline = loop.time() + budget
    try:
        while pending and loop.time() < deadline:
            done, pending = await asyncio.wait(
                pending, timeout=max(0.05, deadline - loop.time()), return_when=asyncio.FIRST_COMPLETED)
            if not done:
                timed_out = True
                break
            ready = []
            for task in done:
                if task.cancelled():
                    continue
                exc = task.exception()
                if exc:
                    log.warning("Slip read failed: %s", type(exc).__name__)
                    continue
                if task is best_task:
                    got, why = task.result()
                    if why:
                        reason = why
                    if got and got.get("legs"):
                        ready.append((got, why))
                    elif got is not None and slip is None:
                        slip = got
                else:
                    got = task.result()
                    if got and got.get("legs"):
                        ready.append((got, None))
            if ready:
                ready.sort(key=lambda item: 0 if item[0].get("status") in ("win", "loss", "push") else 1)
                top, why = ready[0]
                if top.get("status") in ("win", "loss", "push") or not pending:
                    slip, reason = top, why
                    break
                held = (top, why)
    finally:
        for task in (best_task, card_task):
            if not task.done():
                task.cancel()
        await asyncio.gather(best_task, card_task, return_exceptions=True)
    if not (slip and slip.get("legs")) and held:
        slip, reason = held
    if not (slip and slip.get("legs")) and timed_out:
        reason = reason or "that read took too long"
    return slip, reason


# ---- the chain ------------------------------------------------------------------------------------

def _merge_vision(scan: Optional[dict], vision: dict) -> dict:
    """Keep the scan's legs when the picture reader saw fewer, and keep a win or loss either one found."""
    if not isinstance(scan, dict):
        return vision
    out = dict(vision)
    slegs, vlegs = list(scan.get("legs") or []), list(out.get("legs") or [])
    if slegs and len(slegs) > len(vlegs):
        out["legs"] = slegs
    if out.get("cost") is None and scan.get("cost") is not None:
        out["cost"] = scan["cost"]
    if out.get("payout") is None and scan.get("payout") is not None:
        out["payout"] = scan["payout"]
    if out.get("returned") is None and scan.get("returned") is not None:
        out["returned"] = scan["returned"]
    if out.get("status") not in ("win", "loss", "push") and scan.get("status") in ("win", "loss", "push"):
        out["status"] = scan["status"]
    if not out.get("platform") and scan.get("platform"):
        out["platform"] = scan["platform"]
    if not out.get("description") and scan.get("description"):
        out["description"] = scan["description"]
    if out.get("status") in ("win", "loss", "push"):
        out.pop("_unsure", None)
    out.pop("_result_hint", None)
    return out


async def read_slip_best(attachment) -> tuple[Optional[dict], Optional[str]]:
    """Free scan first, then Gemini, then Claude. Returns (slip or None, why it failed or None). A slip the scan
    wasn't sure about comes back with '_unsure' (reasons) when no AI reader could do better: confirm it by hand."""
    reason, unsure_slip = None, None
    for reader in SLIP_READERS:
        if reader == "scan" and TESSERACT:
            try:
                raw = await attachment.read()
                if len(raw) > MAX_IMAGE_BYTES:
                    raise SecImageTooBig(f"{len(raw) // 1024} KB")
                slip = await asyncio.to_thread(free_scan, raw)
            except SecImageTooBig:
                raise
            except Exception as exc:
                log.warning("Free slip scan failed", exc_info=True)
                SLIP_STATE["last_error"] = (now_iso(), f"Free scan: {type(exc).__name__}: {exc}"[:300])
                continue
            if slip is None:
                reason = reason or "it didn't look like a bet slip to me"
                continue
            try:
                await free_fix_names(slip)
                for extra in slip.get("_extra") or []:
                    if isinstance(extra, dict):
                        await free_fix_names(extra)
            except Exception:
                log.debug("Name check skipped", exc_info=True)
            if slip.get("_extra"):
                return slip, None
            if slip.get("_extra"):
                if not slip["_unsure"] and slip["legs"]:
                    free_count("scan")
                    slip.pop("_unsure", None)
                return slip, None
            if slip.get("legs"):
                if not slip.get("_unsure") or slip_result_ready(slip):
                    free_count("scan")
                    if not slip.get("_unsure"):
                        slip.pop("_unsure", None)
                    slip.pop("_result_hint", None)
                    return slip, None
                if slip.get("_result_hint") or any(
                        u in ("the amount risked", "the payout") for u in (slip.get("_unsure") or [])):
                    unsure_slip = slip
                    continue
                slip.pop("_result_hint", None)
                return slip, None
            unsure_slip = slip
            continue
        if reader == "gemini" and GEMINI_API_KEY:
            try:
                slip = await read_slip_gemini(attachment)
            except SecImageTooBig:
                raise
            except Exception as exc:
                log.warning("Gemini slip read failed: %s", str(exc)[:200])
                SLIP_STATE["last_error"] = (now_iso(), f"Reading with Gemini: {type(exc).__name__}: {str(exc)[:200]}")
                continue
            if slip and (slip.get("cost") is not None or slip.get("status") in ("win", "loss", "push")):
                slip = _merge_vision(unsure_slip, slip)
                free_count("gemini")
                slip["_how"] = "gemini"
                return slip, None
            reason = "I couldn't make out the amount risked" if slip else reason
            continue
        if reader == "claude" and ai_enabled() and claude_budget_ok(essential=True) and claude_alive():
            slip, why = await read_slip_claude(attachment)
            if slip is not None and (slip.get("cost") is not None or slip.get("status") in ("win", "loss", "push")):
                slip = _merge_vision(unsure_slip, slip)
                free_count("claude")
                slip["_how"] = "claude"
                return slip, None
            reason = why or reason
    if unsure_slip is not None:
        return unsure_slip, None
    free_count("fail")
    return None, reason


def free_unsure_note(slip: dict) -> str:
    bits = slip.get("_unsure") or []
    return ("🔎 I read this with the free scan but couldn't be sure about " + ", ".join(bits[:3])
            + (" and more" if len(bits) > 3 else "") + ". Check it, then tap 🧾 **Log this slip** (or ✏️ **Edit** to fix it).")


HELP_EXTRA.append(("🔎 Reading slips for free", (
    "Screenshots are read by **scanner 2.0** (free text scan) first: every picture on the message, any common "
    "photo type (PNG, JPEG, WebP, GIF, BMP, HEIC when the phone sends it), dark or light, a tight crop of a full "
    "phone screenshot. Scanner **3.0** skips extra OCR when that first pass already has the legs and the amount, "
    "and tags Kalshi cents tickets and stacked photos. Scanner **4.0** remembers ESPN name fixes and counts "
    "failed reads on Staff HQ. Scanner **5.0** keeps every card: SOG, Hitter FS, Singles, tennis, darts, cricket, "
    "and table tennis, and the review pulls the game log from the right league. Scanner **5.1** also reads combos, "
    "NBASZN and NFLSZN, and PPG, RPG, APG, BPG, 3PTM, 3PTA, FTM, and 50+ Point Games. The player page groups those "
    "stats and lets you switch last 5, 10, or 20, and home or away. Scanner **5.2** fills a thin log from the box score "
    "and the league's own feed, and when more than one player fits you pick the name and can go back. If it's sure, the slip logs like before; if not, you get a card to check and tap 🧾 "
    "**Log this slip** (or ✏️ Edit). A free `GEMINI_API_KEY` on Railway adds a second free reader, and Claude is "
    "only the last resort. `/admin status` shows which reader handled today's slips.")))


# ---- questions: Gemini's free tier first (with Google Search), Claude as the backup ---------------------------

ASK_ENGINES = [x.strip().lower() for x in env("ASK_ENGINES", "groq,gemini,claude").split(",") if x.strip()]


GEMINI_FALLBACK_MODELS = ("gemini-flash-latest", "gemini-2.5-flash", "gemini-2.0-flash")


def gemini_models() -> list[str]:
    """The configured model first, then stable names, so a renamed model doesn't break answers."""
    return list(dict.fromkeys([GEMINI_MODEL, *GEMINI_FALLBACK_MODELS]))


ASK_LAST_ERROR: dict = {"text": None}


def ask_error_hint(exc: Optional[BaseException]) -> str:
    """A short, safe reason for a failed answer (never the key)."""
    t = str(exc or "")
    if "429" in t or "quota" in t.lower() or "exhausted" in t.lower():
        return "Gemini's free limit is used up for now"
    if "401" in t or "403" in t or "API key" in t:
        return "the Gemini key on Railway was refused"
    if "none of the model names" in t:
        return "Gemini doesn't recognise the model name (GEMINI_MODEL)"
    if "no question engine" in t:
        return "no AI key is set on Railway"
    if "timed out" in t.lower():
        return "Gemini took too long to answer"
    if re.search(r"HTTP 5\d\d", t):
        return "Gemini is overloaded on Google's side; try again in a minute"
    if "came back empty" in t:
        return "Gemini came back with no text"
    code = re.search(r"HTTP (\d{3})", t)
    return f"error {code.group(1)}: {ask_error_snip(t)}" if code else f"didn't answer: {ask_error_snip(t)}"


def ask_error_snip(t: str) -> str:
    """A short piece of an error to show in Discord, with anything key-like blanked out."""
    t = re.sub(r"(AIza[\w-]{10,}|sk-[\w-]{10,}|key=[^&\s]+)", "[key]", str(t or ""))
    t = re.sub(r"^(?:Gemini|Groq) HTTP \d{3}:\s*", "", t)
    m = re.search(r"['\"]message['\"]\s*:\s*['\"]([^'\"]{4,})", t)
    return clip(" ".join((m.group(1) if m else t).split()), 90) or type(t).__name__


def claude_error_hint(exc: Optional[BaseException]) -> str:
    t = str(exc or "")
    low = t.lower()
    if "credit balance" in low or "billing" in low:
        return "the Claude account is out of credits"
    if "authentication" in low or "401" in t or "invalid x-api-key" in low:
        return "the Claude key on Railway was refused"
    if "overloaded" in low or "529" in t or "rate_limit" in low or "429" in t:
        return "Claude is busy; try again in a minute"
    return f"didn't answer: {ask_error_snip(t)}"


XAI_API_KEY = env("XAI_API_KEY", "")
XAI_MODEL = env("XAI_MODEL", "grok-3")


def xai_key() -> str:
    """The xAI key with line breaks and spaces removed, so a wrapped paste still sends as one token."""
    return "".join((XAI_API_KEY or "").split())


def xai_ready() -> bool:
    """A real xAI key starts with xai-. A model name such as grok-3 in that variable is not a key."""
    key = xai_key()
    return key.startswith("xai-") and len(key) > 20


def ask_enabled() -> bool:
    """Can the bot answer questions at all (a Gemini or a Claude key)?"""
    if xai_ready() or env("OPENROUTER_API_KEY", ""):
        return True
    return any((e == "groq" and GROQ_API_KEY) or (e == "gemini" and GEMINI_API_KEY) or (e == "claude" and ai_enabled())
               for e in ASK_ENGINES)


def groq_models(search: bool) -> list[tuple[str, bool]]:
    """[(model, search the web?)]: the main model first, then the fallbacks."""
    return [(m, search and m in GROQ_SEARCH_OK) for m in dict.fromkeys([GROQ_MODEL, *GROQ_FALLBACK_MODELS])]


async def ask_groq(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """(answer, source links) from Groq's free tier. A model that's busy or out of free uses hands off to the next."""
    import aiohttp
    errors = []
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=18 if search else 8)) as session:
        for model, web in groq_models(search):
            body = {"model": model, "temperature": 0.4, "max_completion_tokens": 4096,
                    "messages": [{"role": "system", "content": system}, {"role": "user", "content": user_text}]}
            if model.startswith("openai/gpt-oss"):
                body["reasoning_effort"] = "low"
            if web:
                body.update(tools=[{"type": "browser_search"}], tool_choice="auto")
            data, tried_plain = None, False
            while True:
                try:
                    async with session.post("https://api.groq.com/openai/v1/chat/completions", json=body,
                                            headers={"Authorization": f"Bearer {GROQ_API_KEY}"}) as resp:
                        if resp.status == 400 and "tools" in body and not tried_plain:
                            body = {k: v for k, v in body.items() if k not in ("tools", "tool_choice")}
                            tried_plain = True                          # search not allowed here: answer without it
                            continue
                        if resp.status != 200:
                            err = f"Groq HTTP {resp.status}: {(await resp.text())[:200]}"
                            if resp.status in (401, 403):
                                raise RuntimeError(err)                 # a bad key fails on every model
                            errors.append(err)
                            break
                        data = await resp.json(content_type=None)
                        break
                except RuntimeError:
                    raise
                except Exception as exc:
                    errors.append(f"Groq timed out or dropped ({type(exc).__name__})")
                    break
            if data is None:
                continue
            msg = ((data.get("choices") or [{}])[0].get("message") or {})
            text = re.sub(r"<think>.*?</think>", "", msg.get("content") or "", flags=re.S)
            text = re.sub(r"【[^】]{0,40}】", "", text).strip()               # browser_search citation marks
            if text:
                sources = []
                for tool in msg.get("executed_tools") or []:
                    for r in ((tool.get("search_results") or {}).get("results") or []):
                        u = str(r.get("url") or "").strip()
                        if u.startswith("https://") and u not in sources:
                            sources.append(u)
                return text, sources[:3]
            errors.append(f"Groq came back empty on {model}")
    log.warning("Groq tried %s: %s", ", ".join(m for m, _ in groq_models(search)), " | ".join(errors)[:600])
    raise RuntimeError(" | ".join(errors) or "Groq came back empty")


def groq_error_hint(exc: Optional[BaseException]) -> str:
    t = str(exc or "")
    if "429" in t:
        return "Groq's free limit is used up for now"
    if "401" in t or "403" in t:
        return "the Groq key on Railway was refused"
    if "timed out" in t:
        return "Groq took too long"
    if re.search(r"HTTP 5\d\d", t):
        return "Groq is busy; try again in a minute"
    return "Groq didn't answer: " + ask_error_snip(t)


async def ask_gemini(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """(answer, source links) from Gemini, searching Google for anything current. The key goes in a header."""
    import aiohttp
    system = (system + "\n\nYou don't have a group_stats tool here: for the group's own records use only the group "
              "data included in the message, and say so if it isn't there.")
    body = {"system_instruction": {"parts": [{"text": system}]},
            "contents": [{"role": "user", "parts": [{"text": user_text}]}],
            "tools": [{"google_search": {}}],
            "generationConfig": {"temperature": 0.4, "maxOutputTokens": 8192}}
    if not search:
        body.pop("tools")                                      # the numbers are in the message: save the search quota
    data, text, errors = None, "", []
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=18 if search else 8)) as session:
        for model in gemini_models():
            url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"
            mbody, tried_plain, data = body, False, None
            while True:
                try:
                    async with session.post(url, json=mbody, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
                        if resp.status == 400 and not tried_plain and "tools" in mbody:
                            mbody = {k: v for k, v in mbody.items() if k != "tools"}   # no search on this model
                            tried_plain = True
                            continue
                        if resp.status == 404:
                            errors.append(f"{model} not found")
                            break                                               # unknown model: try the next
                        if resp.status != 200:
                            err = f"Gemini HTTP {resp.status}: {(await resp.text())[:200]}"
                            if resp.status in (401, 403) or "API key" in err:
                                raise RuntimeError(err)                         # a bad key fails on every model
                            errors.append(err)
                            break                                               # busy / limit hit: next model
                        data = await resp.json(content_type=None)
                        break
                except RuntimeError:
                    raise
                except Exception as exc:                                        # timeout, connection dropped
                    errors.append(f"Gemini timed out or dropped ({type(exc).__name__})")
                    break
            if data is None:
                continue
            if not data.get("candidates") and (data.get("promptFeedback") or {}).get("blockReason"):
                return "", []                                                   # blocked: the fallback decides
            cand = (data.get("candidates") or [{}])[0]
            text = "".join(p.get("text", "") for p in ((cand.get("content") or {}).get("parts") or [])
                           if not p.get("thought")).strip()
            if text:
                break
            errors.append(f"Gemini came back empty on {model} ({cand.get('finishReason') or 'no reason given'})")
    if not text:
        if errors and all(e.endswith("not found") for e in errors):
            raise RuntimeError("Gemini: none of the model names worked (check GEMINI_MODEL)")
        log.warning("Gemini tried %s: %s", ", ".join(gemini_models()), " | ".join(errors)[:600])
        raise RuntimeError(" | ".join(e for e in errors if not e.endswith("not found")) or "Gemini came back empty")
    sources = []
    for ch in ((cand.get("groundingMetadata") or {}).get("groundingChunks") or []):
        uri = ((ch.get("web") or {}).get("uri") or "").strip()
        if uri.startswith("https://") and uri not in sources:
            sources.append(uri)
    return text, sources[:3]


_NO_ANSWER = re.compile(r"\b(i (?:couldn'?t|could not|can'?t|cannot|wasn'?t able to|was unable to|don'?t have|do not have)"
                        r" (?:find|access|confirm|verify|browse|search|look up|get|provide|give)|unable to (?:find|access|"
                        r"confirm|verify)|no (?:recent |current |reliable )?(?:information|info|results|data) (?:on|about|for|"
                        r"available)|my knowledge cutoff|as of my last (?:update|training)"
                        r"|i(?:'m| am) (?:not able|unable) to (?:find|access|confirm|verify|browse|search|look up|get)"
                        r"|(?:don'?t|do not) have (?:real[- ]time|live|current|up[- ]to[- ]date|recent) (?:access|data|info|"
                        r"information|stats|results)|couldn'?t locate|there (?:is|was|are) no (?:recent |current |reliable )?"
                        r"(?:information|info|data|news|reports?)\b)", re.I)


def ask_unanswered(answer: str) -> bool:
    """Did the answer duck the question (empty, a few words, or 'I couldn't find...')?"""
    a = (answer or "").strip()
    m = _NO_ANSWER.search(a[:400])
    return len(a) < 20 or bool(m and (m.start() < 120 or len(a) < 200))   # a late hedge in a real answer is fine


async def ask_chat(url: str, key: str, model: str, system: str, user_text: str, label: str,
                   extra: Optional[dict] = None) -> tuple[str, list[str]]:
    """One OpenAI-style chat call. extra is dropped and retried once if the host rejects it."""
    import aiohttp
    body = {"model": model, "temperature": 0.4, "max_tokens": 900,
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": user_text}]}
    if extra:
        body.update(extra)
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=60)) as session:
        async with session.post(url, json=body, headers={"Authorization": f"Bearer {key}"}) as resp:
            if resp.status == 400 and extra:
                await resp.read()
                plain = {k: v for k, v in body.items() if k not in extra}
                async with session.post(url, json=plain, headers={"Authorization": f"Bearer {key}"}) as again:
                    if again.status != 200:
                        raise RuntimeError(f"{label} HTTP {again.status}: {(await again.text())[:200]}")
                    data = await again.json(content_type=None)
            elif resp.status != 200:
                raise RuntimeError(f"{label} HTTP {resp.status}: {(await resp.text())[:200]}")
            else:
                data = await resp.json(content_type=None)
    text = (((data.get("choices") or [{}])[0].get("message") or {}).get("content") or "").strip()
    if not text:
        raise RuntimeError(f"{label} came back empty")
    sources = []
    for cite in data.get("citations") or []:
        u = str(cite or "").strip()
        if u.startswith("https://") and u not in sources:
            sources.append(u)
    return text, sources[:3]


async def ask_xai(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """Grok, from xAI, when XAI_API_KEY is set on the host. A factual question can use live search."""
    extra = {"search_parameters": {"mode": "auto", "return_citations": True}} if search else None
    return await ask_chat("https://api.x.ai/v1/chat/completions", xai_key(), XAI_MODEL, system, user_text, "Grok", extra)


async def ask_openrouter(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """Grok through OpenRouter when OPENROUTER_API_KEY is set. OPENROUTER_MODEL can pick another model."""
    key = env("OPENROUTER_API_KEY", "")
    model = env("OPENROUTER_MODEL", "x-ai/grok-4-fast")
    return await ask_chat("https://openrouter.ai/api/v1/chat/completions", key, model, system, user_text, "OpenRouter")


async def ask_any(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """Answer with Gemini (free) first. Claude is the fail-safe: it only runs when Gemini errors out or comes back
    without a real answer (and a Claude key is set). ASK_ENGINES can change the order.
    A Grok key (XAI_API_KEY, or OpenRouter) answers first when it is set."""
    last: Optional[Exception] = None
    fallback: Optional[tuple[str, list[str]]] = None
    why: list[str] = []
    ASK_LAST_ERROR["text"] = None
    engines = list(ASK_ENGINES)
    if xai_ready() and "xai" not in engines:
        engines.insert(0, "xai")
    elif env("OPENROUTER_API_KEY", "") and "openrouter" not in engines:
        engines.insert(0, "openrouter")
    for engine in engines:
        if engine == "xai" and xai_ready():
            try:
                answer, sources = await ask_xai(system, user_text, search)
                if answer and not ask_unanswered(answer):
                    free_count("ask_xai")
                    return answer, sources
                if answer and fallback is None:
                    fallback = (answer, sources)
            except Exception as exc:
                last = exc
                why.append("Grok: " + ask_error_snip(str(exc)))
                log.warning("Grok answer failed: %s", str(exc)[:300])
        elif engine == "openrouter" and env("OPENROUTER_API_KEY", ""):
            try:
                answer, sources = await ask_openrouter(system, user_text, search)
                if answer and not ask_unanswered(answer):
                    free_count("ask_openrouter")
                    return answer, sources
                if answer and fallback is None:
                    fallback = (answer, sources)
            except Exception as exc:
                last = exc
                why.append("OpenRouter: " + ask_error_snip(str(exc)))
                log.warning("OpenRouter answer failed: %s", str(exc)[:300])
        elif engine == "groq" and GROQ_API_KEY:
            try:
                answer, sources = await ask_groq(system, user_text, search)
                if answer and not ask_unanswered(answer):
                    free_count("ask_groq")
                    return answer, sources
                if answer and fallback is None:
                    fallback = (answer, sources)
            except Exception as exc:
                last = exc
                why.append(groq_error_hint(exc))
                log.warning("Groq answer failed: %s", str(exc)[:300])
        elif engine == "gemini" and GEMINI_API_KEY:
            try:
                answer, sources = await ask_gemini(system, user_text, search=search)
                if answer and not ask_unanswered(answer):
                    free_count("ask_gemini")
                    return answer, sources
                if answer:
                    fallback = (answer, sources)       # keep it in case nothing better comes
                else:
                    why.append("Gemini: it blocked or skipped the request")
            except Exception as exc:
                last = exc
                h = ask_error_hint(exc)
                why.append(h if "Gemini" in h else "Gemini: " + h)
                log.warning("Gemini answer failed: %s", str(exc)[:300])
        elif engine == "claude" and ai_enabled() and claude_budget_ok(essential=True) and claude_alive():
            try:
                answer, sources = await ask_claude(system, user_text)
            except Exception as exc:
                last = exc
                why.append("Claude backup: " + claude_error_hint(exc))
                log.warning("Claude answer failed: %s", str(exc)[:300])
                continue
            if answer:
                free_count("ask_claude")
                return answer, sources
    if fallback is not None:
        free_count("ask_gemini")
        return fallback
    ASK_LAST_ERROR["text"] = "; ".join(why) if why else ask_error_hint(last or RuntimeError("no question engine is set up"))
    raise last or RuntimeError("no question engine is set up")


# ==========================================================================
# r24: /live as a big, easy-to-read picture with a pace graph per leg, and /gamecard on demand.
# ==========================================================================

LV2_GAMES = 4                 # games drawn on one /live picture
LV2_ROWS = 7                  # legs drawn per game
# (periods, minutes per period) for working out how much of a game is gone
LV2_CLOCK = {"basketball/nba": (4, 12), "basketball/wnba": (4, 10), "basketball/mens-college-basketball": (2, 20),
             "football/nfl": (4, 15), "football/college-football": (4, 15), "hockey/nhl": (3, 20)}


def lv2_elapsed(ev: dict, path: Optional[str]) -> Optional[float]:
    """How much of the game has been played (0-1), from the period and clock; None when it can't tell."""
    if not ev or ev.get("state") != "in":
        return 1.0 if ev and (ev.get("final") or ev.get("state") == "post") else None
    detail = (ev.get("detail") or "").lower()
    fam = (path or "").split("/")[0]
    if fam == "soccer":
        m = re.search(r"(\d{1,3})(?:\+\d+)?'", detail)
        if m:
            return min(1.0, int(m.group(1)) / 90)
        if re.search(r"\b(ft|aet|full[- ]?time|pens?)\b", detail):
            return 1.0
        return 0.5 if re.search(r"\bht\b|half", detail) else None
    if fam == "baseball":
        m = re.search(r"(top|bot|bottom|mid|middle|end)\w*\s+(?:of\s+)?(\d{1,2})", detail)
        if not m:
            return None
        inning = int(m.group(2))
        half = {"top": 0.0, "mid": 0.5, "middle": 0.5, "bot": 0.5, "bottom": 0.5, "end": 1.0}[m.group(1)]
        return max(0.0, min(1.0, (inning - 1 + half) / 9))
    spec = LV2_CLOCK.get(path or "")
    if not spec:
        return None
    periods, mins = spec
    if "halftime" in detail or detail.strip() in ("half", "ht"):
        return 0.5
    if re.search(r"\b\d?ot\b", detail) and not ev.get("period"):
        return 1.0                             # "OT", "2OT" without a period number
    period = int(ev.get("period") or 0)
    if not period:
        m = re.search(r"\b[qp](\d)\b|(\d)(?:st|nd|rd|th)\b", detail)
        period = int(m.group(1) or m.group(2)) if m else 0
    if not period:
        return None
    if period > periods or "ot" in detail.split():
        return 1.0
    m = re.search(r"(\d{1,2}):(\d{2})", detail)
    left = (int(m.group(1)) + int(m.group(2)) / 60) if m else (
        0.0 if ("end" in detail or "intermission" in detail) else mins / 2)
    return max(0.0, min(1.0, ((period - 1) * mins + (mins - min(left, mins))) / (periods * mins)))


def lv2_pace(value: float, line: float, elapsed: Optional[float], text: str) -> Optional[float]:
    """Where this stat is headed if it keeps this rate (None early in a game, or for 'longest' stats)."""
    if elapsed is None or elapsed < 0.12 or elapsed >= 0.999 or re.search(r"longest|first|anytime", text, re.I):
        return None
    return round(value / elapsed, 1)


def lv2_game_rows(g: dict, show_open_only: bool = True) -> list[dict]:
    rows = [lv_row(r["s"], r["e"]) for r in g["rows"]
            if r["s"]["p"]["status"] == "open" or r["e"].get("status") != "open" or not show_open_only]
    return sorted(rows, key=lambda r: (LV_ORDER.get(r["state"], 9), r["who"].lower()))


async def lv2_board_data(client, gid: int, scope: str, uid: int, private: bool, now: datetime,
                         snap: list[dict]) -> Optional[dict]:
    """Everything the /live picture needs (avatars fetched here, before the render thread). None if nothing is live."""
    mine = [s for s in snap if lv_visible(s, scope, uid, private)]
    games = [g for g in lv_games_of(mine).values() if g["ev"].get("state") == "in" and not g["ev"].get("final")]
    games.sort(key=lambda g: (event_time(g["ev"]) or now, g["id"]))
    out, uids = [], set()
    for g in games:
        rows = lv2_game_rows(g)
        if not rows:
            continue
        el = lv2_elapsed(g["ev"], g["path"])
        for r in rows:
            n = r.get("num")
            r["pace"] = lv2_pace(n["value"], n["line"], el, r["text"]) if n and r["state"] not in ("cleared", "dead") else None
            if r.get("uid"):
                uids.add(r["uid"])
        away, home = (dict(t) for t in lv_sides(g["ev"]))
        await lv2_attach_logos(away, home)
        ac = lv_team_colour(away)
        out.append({"league": LEAGUE_NAMES.get(g["path"] or "", ""), "away": dict(away, colour=ac),
                    "home": dict(home, colour=lv_team_colour(home, avoid=ac)), "status": lv_status_text(g["ev"]),
                    "elapsed": el, "rows": rows})
        if len(out) >= LV2_GAMES:
            break
    if not out:
        return None
    avatars = {}
    for u in list(uids)[:24]:
        user = await known_user(client, u)
        avatars[u] = await avatar_bytes(user) if user is not None else None
    heads = await design_rows_heads([r for g in out for r in g["rows"]])
    tonight = [(lv_clock(t), name, n) for t, name, n in lv_tonight(mine, now)]
    more = max(0, len([g for g in lv_games_of(mine).values() if g["ev"].get("state") == "in"]) - len(out))
    return {"title": "LIVE NOW", "who": "everyone" if scope == "a" else "just you" if private else "mine",
            "updated": lv_clock(now), "games": out, "tonight": tonight, "avatars": avatars, "more_games": more,
            "heads": heads}


def _lv2_pace_bar(d, x: int, y: int, w: int, h: int, value: float, line: float, pace: Optional[float], side: str,
                  state: str) -> None:
    """The graph: a filled bar for now, a ghost bar for where it's headed, and a white tick at the line."""
    top = max(line * 1.5, value, pace or 0, 1)
    sx = lambda v: x + w * min(1.0, max(0.0, v / top))
    d.rounded_rectangle((x, y, x + w, y + h), h // 2, fill=(44, 44, 58))
    good = (value > line) if side == "over" else (value <= line)
    col = {"cleared": ART_GREEN, "dead": ART_RED, "close": ART_AMBER}.get(state) or (ART_GREEN if good and side == "over"
                                                                                     else ART_BLUE)
    if side == "under":
        col = ART_RED if value > line else (ART_AMBER if state == "close" else ART_GREEN)
    if pace is not None and pace > value:
        on = (pace > line) if side == "over" else (pace <= line)
        ghost = _brand_mix(ART_GREEN if on else ART_RED, (44, 44, 58), 0.55)
        d.rounded_rectangle((x, y, sx(pace), y + h), h // 2, fill=ghost)
    if value > 0:
        d.rounded_rectangle((x, y, max(x + h, sx(value)), y + h), h // 2, fill=col)
    lx = sx(line)
    d.rectangle((lx - 2, y - 7, lx + 2, y + h + 7), fill=(255, 255, 255))


async def lv2_live_payload(client, gid: int, scope: str, uid: int, private: bool, now: Optional[datetime] = None,
                           snap: Optional[list] = None, until: Optional[datetime] = None):
    """(embed, signature, picture or None) for /live: the picture when something is in play, text otherwise."""
    now = now or datetime.now(timezone.utc)
    snap = snap if snap is not None else await lv_snapshot(gid, now, deep=True)
    embed, sig = await lv_live_embed(client, gid, scope, uid, private, now, snap=snap, until=until)
    try:
        data = await lv2_board_data(client, gid, scope, uid, private, now, snap)
    except Exception:
        log.warning("Live board data failed", exc_info=True)
        data = None
    if data is None:
        return embed, sig, None
    try:
        png = await asyncio.to_thread(locked_render, render_live_board, data)
    except Exception:
        log.warning("Live board render failed", exc_info=True)
        return embed, sig, None
    lines = []
    for g in data["games"]:
        c = lv_counts(g["rows"])
        bits = " · ".join(f"{LV_ICON[k]} {c[k]}" for k in ("cleared", "close", "live", "ahead", "behind", "dead") if c.get(k))
        sc = lambda t: f" {t['score']:g}" if t.get("score") is not None else ""
        lines.append(f"**{lv_abbr(g['away'])}{sc(g['away'])} · {lv_abbr(g['home'])}{sc(g['home'])}** · {clip(g['status'], 24)} · "
                     f"{len(g['rows'])} leg{'s' if len(g['rows']) != 1 else ''}" + (f" · {bits}" if bits else ""))
    if data["tonight"]:
        lines.append("⏰ Later: " + " · ".join(f"{t} {name}" for t, name, _ in data["tonight"]))
    embed.description = clip("\n".join(lines), 4000)
    f, name = await lv2_animated(png, "live")
    embed.set_image(url=f"attachment://{name}")
    return embed, sig, f


# ---- /gamecard: the game tracker card for any game, on demand ------------------------------------------------

def lv2_card_games(gid: int, snap: list[dict], now: datetime, uid: int) -> list[dict]:
    """Games the group has legs on: live first, then later today, then tonight's finals."""
    vis = [s for s in snap if s["public"]]         # the card is posted in the channel: hidden slips stay out
    games = list(lv_games_of(vis).values())
    start_of = lambda g: event_time(g["ev"]) or now
    _, end = lv_night_bounds(lv_night(now))
    keep = [g for g in games if g["ev"].get("state") == "in"
            or (g["ev"].get("state") == "pre" and start_of(g) <= end + timedelta(hours=12))
            or ((g["ev"].get("final") or g["ev"].get("state") == "post") and start_of(g) >= now - timedelta(hours=14))]
    order = {"in": 0, "pre": 1, "post": 2}
    keep.sort(key=lambda g: (order.get("post" if g["ev"].get("final") else g["ev"].get("state"), 3), start_of(g)))
    return keep


def lv2_game_label(g: dict) -> str:
    ev = g["ev"]
    n = len(g["rows"])
    state = "Final" if (ev.get("final") or ev.get("state") == "post") else (
        "LIVE " + (ev.get("detail") or "") if ev.get("state") == "in" else lv_status_text(ev))
    return clip(f"{lv_score_line(ev)} · {state} · {n} leg{'s' if n != 1 else ''}", 100)


async def gamecard_autocomplete(interaction: discord.Interaction, current: str) -> list:
    try:
        now = datetime.now(timezone.utc)
        snap = await asyncio.wait_for(lv_snapshot(interaction.guild_id, now), 2.5)
        games = lv2_card_games(interaction.guild_id, snap, now, interaction.user.id)
    except Exception:
        return []
    cur = (current or "").lower()
    out = []
    for g in games:
        label = lv2_game_label(g)
        if cur and cur not in label.lower():
            continue
        out.append(app_commands.Choice(name=label, value=str(g["id"])[:100]))
    return out[:25]


async def gamecard_payload(client, gid: int, uid: int, game: Optional[str], now: Optional[datetime] = None):
    """(embed, file) for one game's card, or (message, None) when there's no such game."""
    now = now or datetime.now(timezone.utc)
    snap = await lv_snapshot(gid, now, deep=True)
    games = lv2_card_games(gid, snap, now, uid)
    if not games:
        return ("No games with the group's legs on them right now or later today. Log a slip and its games show up "
                "here."), None
    g = None
    if game:
        g = next((x for x in games if str(x["id"]) == str(game)), None)
        if g is None:
            q = game.lower()
            g = next((x for x in games if q in lv2_game_label(x).lower()), None)
        if g is None:
            return "I couldn't find that game. Start typing a team and pick it from the list.", None
    else:
        g = games[0]                         # the live game first, else the next one up
    rows = lv2_game_rows(g)
    final = bool(g["ev"].get("final") or g["ev"].get("state") == "post")
    embed, f = await lv_card_payload(client, gid, g["ev"], g["path"], rows, final, now)
    return embed, f


HELP_EXTRA.append(("📡 Live, bigger", (
    "`/live` is now a big picture: every game in play, each leg's number, a bar for now, a faded bar for where it's "
    "headed at this rate, and a tick at the line. `/gamecard` pulls up the score card for any game the group is on "
    "(pick it from the list).")))


# ---- real Discord pictures on cards, and a pulsing LIVE dot ---------------------------------------------------

_USER_CACHE: dict = {}


async def known_user(client, uid):
    """The Discord user for an id: from the cache, else one API lookup (kept 6 hours). Without the members intent
    most people aren't cached, which is why cards used to show initials instead of profile pictures."""
    if client is None or not uid:
        return None
    try:
        uid = int(uid)
    except (TypeError, ValueError):
        return None
    u = client.get_user(uid) if hasattr(client, "get_user") else None
    if u is not None:
        return u
    hit = _USER_CACHE.get(uid)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    u = None
    if hasattr(client, "fetch_user"):
        try:
            u = await asyncio.wait_for(client.fetch_user(uid), 5)
        except Exception:
            u = None
    _USER_CACHE[uid] = (time.monotonic() + (6 * 3600 if u is not None else 900), u)
    if len(_USER_CACHE) > 2000:
        for k in list(_USER_CACHE)[:1000]:
            _USER_CACHE.pop(k, None)
    return u


LV2_PULSE_FRAMES = 10


def lv2_pulse_gif(png: io.BytesIO) -> Optional[io.BytesIO]:
    """The same picture as an animated GIF whose LIVE dot fades in and out. None when there's no dot to pulse."""
    from PIL import Image, ImageDraw
    boxes = getattr(png, "pulse", None)
    if not boxes:
        return None
    png.seek(0)
    base = Image.open(png).convert("RGB")
    png.seek(0)
    red = ART_RED
    samples = []
    for (x0, y0, x1, y1) in boxes:
        samples.append(base.getpixel((max(0, int(x0) - 6), int((y0 + y1) / 2))))
    levels = [0.25 + 0.75 * (0.5 - 0.5 * math.cos(2 * math.pi * k / LV2_PULSE_FRAMES)) for k in range(LV2_PULSE_FRAMES)]
    # one palette for every frame: the picture's own colours plus every shade of the fade, so the pulse is smooth
    fades = []
    for bg in samples:
        for t in levels:
            for c in (_brand_mix(red, bg, 1 - t), _brand_mix(red, bg, 1 - t * 0.35)):
                if c not in fades:
                    fades.append(c)
    fades = fades[:96]
    room = 256 - len(fades)
    own = base.quantize(colors=room, method=Image.Quantize.MEDIANCUT).getpalette()[:room * 3]
    own += [0] * (room * 3 - len(own))
    pal = Image.new("P", (1, 1))
    pal.putpalette(own + [v for c in fades for v in c])
    frames = []
    for t in levels:
        f = base.copy()
        fd = ImageDraw.Draw(f)
        for (x0, y0, x1, y1), bg in zip(boxes, samples):
            r = (x1 - x0) / 2
            cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
            glow = r * (1.0 + 0.6 * t)
            fd.ellipse((cx - glow, cy - glow, cx + glow, cy + glow), fill=_brand_mix(red, bg, 1 - t * 0.35))
            fd.ellipse((cx - r, cy - r, cx + r, cy + r), fill=_brand_mix(red, bg, 1 - t))
        frames.append(f.quantize(palette=pal, dither=Image.Dither.NONE))
    out = io.BytesIO()
    frames[0].save(out, "GIF", save_all=True, append_images=frames[1:], duration=110, loop=0, optimize=False,
                   disposal=1)
    out.seek(0)
    return out


async def lv2_animated(png: io.BytesIO, stem: str):
    """(file, filename): the pulsing GIF when the picture has a LIVE dot, else the PNG."""
    try:
        gif = await asyncio.to_thread(lv2_pulse_gif, png)
    except Exception:
        log.warning("Pulsing dot failed; sending the still picture", exc_info=True)
        gif = None
    if gif is not None and gif.getbuffer().nbytes < 7 * 1024 * 1024:
        return discord.File(gif, filename=f"{stem}.gif"), f"{stem}.gif"
    png.seek(0)
    return discord.File(png, filename=f"{stem}.png"), f"{stem}.png"


# ---- team crests: an original emblem per team, from its colours (never a real logo) ----------------------------

_CREST_CACHE: dict = {}
LV2_SPORT_OF_LEAGUE = {"NFL": "football", "College football": "football", "NBA": "basketball", "WNBA": "basketball",
                       "College basketball": "basketball", "NHL": "hockey", "MLB": "baseball"}


def lv2_sport(league: Optional[str]) -> str:
    return LV2_SPORT_OF_LEAGUE.get(league or "", "soccer" if league else "other")


def _crest_glyph(d, cx: float, cy: float, s: float, sport: str, ink: tuple) -> None:
    """A small sport mark: a football, basketball, puck, baseball or soccer ball, drawn with plain shapes."""
    w = max(2, int(s * 0.09))
    if sport == "football":
        d.ellipse((cx - s * 0.62, cy - s * 0.36, cx + s * 0.62, cy + s * 0.36), outline=ink, width=w)
        d.line((cx - s * 0.26, cy, cx + s * 0.26, cy), fill=ink, width=w)
        for k in (-0.14, 0, 0.14):
            d.line((cx + s * k, cy - s * 0.1, cx + s * k, cy + s * 0.1), fill=ink, width=max(1, w // 2))
    elif sport == "basketball":
        d.ellipse((cx - s * 0.45, cy - s * 0.45, cx + s * 0.45, cy + s * 0.45), outline=ink, width=w)
        d.line((cx - s * 0.45, cy, cx + s * 0.45, cy), fill=ink, width=w)
        d.line((cx, cy - s * 0.45, cx, cy + s * 0.45), fill=ink, width=w)
        d.arc((cx - s * 0.75, cy - s * 0.45, cx - s * 0.05, cy + s * 0.45), -60, 60, fill=ink, width=w)
        d.arc((cx + s * 0.05, cy - s * 0.45, cx + s * 0.75, cy + s * 0.45), 120, 240, fill=ink, width=w)
    elif sport == "hockey":
        d.ellipse((cx - s * 0.55, cy - s * 0.12, cx + s * 0.55, cy + s * 0.3), fill=ink)
        d.ellipse((cx - s * 0.55, cy - s * 0.3, cx + s * 0.55, cy + s * 0.12), outline=ink, width=w)
    elif sport == "baseball":
        d.ellipse((cx - s * 0.45, cy - s * 0.45, cx + s * 0.45, cy + s * 0.45), outline=ink, width=w)
        d.arc((cx - s * 0.85, cy - s * 0.5, cx - s * 0.12, cy + s * 0.5), -50, 50, fill=ink, width=max(1, w // 2 + 1))
        d.arc((cx + s * 0.12, cy - s * 0.5, cx + s * 0.85, cy + s * 0.5), 130, 230, fill=ink, width=max(1, w // 2 + 1))
    elif sport == "soccer":
        d.ellipse((cx - s * 0.45, cy - s * 0.45, cx + s * 0.45, cy + s * 0.45), outline=ink, width=w)
        pts = [(cx + s * 0.18 * math.cos(math.radians(a)), cy + s * 0.18 * math.sin(math.radians(a)))
               for a in range(-90, 270, 72)]
        d.polygon(pts, fill=ink)
    else:
        d.regular_polygon((cx, cy, s * 0.4), 5, fill=ink)


def team_crest_img(abbr: str, colour: tuple, alt: Optional[str], sport: str, size: int):
    """An RGBA emblem for one team: shape and stripe pattern picked from the abbreviation (so every team looks
    different, and the same every time), in the team's colours, with a sport mark and the abbreviation."""
    from PIL import Image, ImageDraw, ImageFilter
    key = (abbr, colour, alt, sport, size)
    hit = _CREST_CACHE.get(key)
    if hit is not None:
        return hit.copy()
    S = 4
    n = size * S
    seed = sum((i + 1) * ord(ch) for i, ch in enumerate(abbr or "?"))
    shape, pattern = seed % 3, (seed // 3) % 4
    second = _lv_hex(alt)
    if second is None or sum(abs(a - b) for a, b in zip(second, colour)) < 110 or _lv_lum(second) < 30:
        second = _brand_mix(colour, (255, 255, 255), 0.7)
    m = int(n * 0.06)
    if shape == 0:      # shield
        poly = [(m, m), (n - m, m), (n - m, n * 0.55), (n / 2, n - m), (m, n * 0.55)]
    elif shape == 1:    # hexagon
        poly = [(n / 2 + (n / 2 - m) * math.cos(math.radians(a)), n / 2 + (n / 2 - m) * math.sin(math.radians(a)))
                for a in range(-90, 270, 60)]
    else:               # diamond-cut badge
        c = n * 0.22
        poly = [(m + c, m), (n - m - c, m), (n - m, m + c), (n - m, n - m - c), (n - m - c, n - m), (m + c, n - m),
                (m, n - m - c), (m, m + c)]
    mask = Image.new("L", (n, n), 0)
    ImageDraw.Draw(mask).polygon(poly, fill=255)
    body = _vgrad((n, n), _brand_mix(colour, (255, 255, 255), 0.18), _brand_mix(colour, (0, 0, 0), 0.38)).convert("RGBA")
    stripe = Image.new("RGBA", (n, n), (0, 0, 0, 0))
    sd = ImageDraw.Draw(stripe)
    band = second + (235,)
    if pattern == 0:    # diagonal sash
        sd.polygon([(0, n * 0.62), (n * 0.62, 0), (n * 0.86, 0), (0, n * 0.86)], fill=band)
    elif pattern == 1:  # chevron
        sd.polygon([(0, n * 0.48), (n / 2, n * 0.72), (n, n * 0.48), (n, n * 0.62), (n / 2, n * 0.86), (0, n * 0.62)], fill=band)
    elif pattern == 2:  # split halves
        sd.rectangle((n / 2, 0, n, n), fill=second + (90,))
        sd.rectangle((n / 2 - n * 0.03, 0, n / 2 + n * 0.03, n), fill=band)
    else:               # two bands
        sd.rectangle((0, n * 0.66, n, n * 0.72), fill=band)
        sd.rectangle((0, n * 0.77, n, n * 0.8), fill=band)
    body.alpha_composite(stripe)
    out = Image.new("RGBA", (n, n), (0, 0, 0, 0))
    glow = Image.new("RGBA", (n, n), colour + (0,))
    gm = mask.filter(ImageFilter.GaussianBlur(n * 0.04)).point(lambda v: int(v * 0.45))
    glow.putalpha(gm)
    out.alpha_composite(glow)
    out.paste(body, (0, 0), mask)
    od = ImageDraw.Draw(out)
    od.polygon(poly, outline=(255, 255, 255, 210), width=int(n * 0.035))
    ink = (255, 255, 255, 235)
    _crest_glyph(od, n / 2, n * 0.27, n * 0.27, sport, ink)
    txt = (abbr or "?")[:4]
    f = art_font(int(n * (0.25 if len(txt) <= 2 else 0.22 if len(txt) == 3 else 0.18)), True)
    tw = od.textlength(txt, font=f)
    bb = f.getbbox(txt)
    ty = n * 0.62 - (bb[1] + bb[3]) / 2
    od.text((n / 2 - tw / 2 + n * 0.012, ty + n * 0.012), txt, font=f, fill=(0, 0, 0, 120))
    od.text((n / 2 - tw / 2, ty), txt, font=f, fill=(255, 255, 255, 255))
    small = out.resize((size, size), Image.LANCZOS)
    _CREST_CACHE[key] = small
    if len(_CREST_CACHE) > 300:
        for k in list(_CREST_CACHE)[:150]:
            _CREST_CACHE.pop(k, None)
    return small.copy()


def lv2_crest(img, cx: int, cy: int, r: int, team: dict, colour: tuple, sport: str) -> None:
    """Paste a team's crest centred at (cx, cy), about the size of a radius-r badge."""
    size = int(r * 2.3)
    if team.get("logo_bytes"):
        try:
            plate = _lv2_logo_plate(team["logo_bytes"], size, colour)
            img.paste(plate, (int(cx - size / 2), int(cy - size / 2)), plate)
            return
        except Exception:
            pass                               # a broken image: fall back to the crest
    crest = team_crest_img(lv_abbr(team), colour, team.get("alt_color"), sport, size)
    img.paste(crest, (int(cx - size / 2), int(cy - size / 2)), crest)


# ---- team logos from the scoreboard feed (the crest is only the fallback) --------------------------------------

_LOGO_CACHE: dict = {}
LV2_LOGO_HOSTS = ("a.espncdn.com", "a1.espncdn.com", "a2.espncdn.com", "a3.espncdn.com", "a4.espncdn.com")


async def team_logo_bytes(url: Optional[str]) -> Optional[bytes]:
    """The team's logo image from ESPN's own scoreboard feed (kept a day). Only ESPN's image host is fetched."""
    if not url:
        return None
    from urllib.parse import urlsplit
    parts = urlsplit(url)
    if parts.scheme != "https" or parts.hostname not in LV2_LOGO_HOSTS:
        return None
    hit = _LOGO_CACHE.get(url)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    raw = None
    try:
        import aiohttp
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=8)) as session:
            async with session.get(url) as resp:
                if resp.status == 200 and int(resp.headers.get("Content-Length") or 0) <= 1_500_000:
                    data = b""
                    while len(data) <= 1_500_000:
                        chunk = await resp.content.read(65536)
                        if not chunk:
                            break
                        data += chunk
                    raw = data if 0 < len(data) <= 1_500_000 else None
    except Exception:
        raw = None
    _LOGO_CACHE[url] = (time.monotonic() + (86400 if raw else 1800), raw)
    if len(_LOGO_CACHE) > 400:
        for k in list(_LOGO_CACHE)[:200]:
            _LOGO_CACHE.pop(k, None)
    return raw


async def lv2_attach_logos(*teams: dict) -> None:
    """Fetch each team's logo before the render thread (renderers never touch the network)."""
    for t in teams:
        if t is not None and not t.get("logo_bytes"):
            t["logo_bytes"] = await team_logo_bytes(t.get("logo"))


def _lv2_logo_plate(raw: bytes, size: int, colour: tuple):
    """The logo centred on a dark disc with a ring in the team's colour."""
    from PIL import Image, ImageDraw, ImageFilter
    logo = Image.open(io.BytesIO(raw))
    sec_check_image(logo)
    logo = logo.convert("RGBA")
    S = 3
    n = size * S
    out = Image.new("RGBA", (n, n), (0, 0, 0, 0))
    glow = Image.new("RGBA", (n, n), colour + (0,))
    gm = Image.new("L", (n, n), 0)
    ImageDraw.Draw(gm).ellipse((n * 0.04, n * 0.04, n * 0.96, n * 0.96), fill=150)
    glow.putalpha(gm.filter(ImageFilter.GaussianBlur(n * 0.04)))
    out.alpha_composite(glow)
    d = ImageDraw.Draw(out)
    d.ellipse((n * 0.06, n * 0.06, n * 0.94, n * 0.94), fill=(250, 250, 252, 255), outline=colour + (255,),
              width=max(2, int(n * 0.04)))
    box = int(n * 0.66)
    logo.thumbnail((box, box), Image.LANCZOS)
    out.alpha_composite(logo, (int((n - logo.width) / 2), int((n - logo.height) / 2)))
    return out.resize((size, size), Image.LANCZOS)


# ==========================================================================
# r26: the ask channel. Any message there is a question for the bot (no @mention needed), and the bot posts a
# news feed there: injury-report changes for players on the group's open slips, players coming off the report,
# and PrizePicks-style reboots when a player doesn't play.
# ==========================================================================

NEWS_EVERY_MIN = 10           # how often the injury reports are checked per server
NEWS_MAX_POSTS = 6            # updates posted one by one per check; more than this become one roundup
NEWS_STATUS_ICON = {"out": "⛔", "doubtful": "🟠", "questionable": "🟡", "day-to-day": "🟡", "suspension": "🚫",
                    "probable": "🟢", "active": "✅"}


def news_db():
    c = db()
    c.execute("""CREATE TABLE IF NOT EXISTS news_seen (
                     guild_id INTEGER NOT NULL, key TEXT NOT NULL, status TEXT, detail TEXT, posted_at TEXT,
                     PRIMARY KEY (guild_id, key))""")
    return c


def ask_channel_id(guild_id: int) -> Optional[int]:
    v = get_setting(guild_id, "ask_channel")
    return int(v) if v and v.isdigit() else None


def is_ask_channel(channel) -> bool:
    """The ask channel itself, or a thread inside it."""
    gid = getattr(getattr(channel, "guild", None), "id", None)
    if gid is None:
        return False
    cid = ask_channel_id(gid)
    return bool(cid) and (getattr(channel, "id", None) == cid or getattr(channel, "parent_id", None) == cid)


def news_icon(status: str) -> str:
    s = (status or "").lower()
    return next((v for k, v in NEWS_STATUS_ICON.items() if s.startswith(k)), "🩹")


async def news_watchlist(gid: int, now: datetime) -> dict[str, dict]:
    """{player key: {name, paths, slips: [(who, pick id, description)]}} for every player on the group's open,
    public slips (and the players the group tracks with /player)."""
    since = iso(now - timedelta(days=AUTOPILOT_DAYS))
    out: dict[str, dict] = {}
    rows = db().execute("SELECT * FROM picks WHERE guild_id = ? AND status = 'open' AND created_at >= ? "
                        "AND (hidden IS NULL OR hidden = 0) ORDER BY id DESC LIMIT 60", (gid, since)).fetchall()
    for p in rows:
        legs = get_legs(p["id"])
        texts = [x["text"] for x in legs if x["status"] == "open"] or ([] if legs else [p["description"]])
        paths = prop_paths_for(p)
        for text in texts:
            leg = prop_of(text)
            if not leg:
                continue
            for part in leg.get("combo") or [leg]:
                fams = {STATS[k][1] for k in part["stats"]}
                ok = [x for x in paths if FAMILY_OF_PATH.get(x) in fams]
                w = out.setdefault(part["player"], {"name": part.get("display") or part["player"].title(),
                                                    "paths": [], "slips": []})
                w["paths"] = list(dict.fromkeys(w["paths"] + ok))
                tag = (p["bettor_name"], p["id"], p["description"])
                if tag not in w["slips"]:
                    w["slips"].append(tag)
    for r in db().execute("SELECT name, sport FROM players WHERE guild_id = ? LIMIT 60", (gid,)).fetchall():
        key = norm_name(r["name"])
        paths = [x for x in leagues_for(r["sport"]) if x in PROP_PATHS] if r["sport"] else []
        w = out.setdefault(key, {"name": r["name"], "paths": [], "slips": []})
        w["paths"] = list(dict.fromkeys(w["paths"] + paths)) or list(PROP_PATHS)
    return out


async def news_status(watch: dict) -> dict[str, Optional[dict]]:
    """{player key: injury entry or None when he isn't on any report}. Players whose name fits more than one
    listed player are left out (no guessing)."""
    reports: dict[str, dict] = {}
    failed: set = set()
    for path in {x for w in watch.values() for x in w["paths"]}:
        reports[path] = await fetch_injuries(path)
        if path not in _injury_cache:          # a good fetch is always cached: this one failed
            failed.add(path)
    out: dict[str, Optional[dict]] = {}
    for key, w in watch.items():
        found = []
        for path in w["paths"]:
            for k, v in (reports.get(path) or {}).items():
                sc = name_score(key, k)
                if sc >= 2:
                    found.append((sc, dict(v, path=path)))
        if not found and failed.intersection(w["paths"]):
            continue                           # his report didn't load: no news either way
        if found:
            best = max(s for s, _ in found)
            top = {(v["name"], v.get("team") or ""): v for s, v in found if s == best}
            if any(v.get("ambiguous") for v in top.values()):
                top[("", "")] = {}                 # the report itself lists two players by this name
            out[key] = next(iter(top.values())) if len(top) == 1 else None
            if len(top) > 1:
                out.pop(key)
        else:
            out[key] = None
        if out.get(key) is None and "football/nfl" in w["paths"] and "sleeper_injury" in globals():
            try:
                sl = await sleeper_injury(key)
            except Exception:
                sl = None
            if sl:
                out[key] = sl
    return out


def news_slips_line(w: dict) -> str:
    bits = [f"{clip(who, 24)}'s {clip(desc, 30)} (`#{pid}`)" for who, pid, desc in w["slips"][:4]]
    more = len(w["slips"]) - 4
    return ("On: " + ", ".join(bits) + (f" and {more} more" if more > 0 else "")) if bits else "A player you track"


async def news_reboots(gid: int, now: datetime) -> list[tuple[str, str]]:
    """(key, line) for legs that just got voided because the player didn't play."""
    since = iso(now - timedelta(hours=36))
    rows = db().execute(
        """SELECT l.pick_id, l.idx, l.text, l.note, p.bettor_name, p.description, p.platform, p.hidden,
                  (SELECT COUNT(*) FROM legs l2 WHERE l2.pick_id = l.pick_id) AS n
           FROM legs l JOIN picks p ON p.id = l.pick_id
           WHERE p.guild_id = ? AND l.status = 'push' AND l.note LIKE '%didn''t play%'
             AND COALESCE(p.settled_at, p.created_at) >= ?""", (gid, since)).fetchall()
    out = []
    for r in rows:
        if r["hidden"]:
            continue
        dfs = is_dfs(r["platform"] or "")
        n = r["n"] or 1
        tail = (f" {clip(r['bettor_name'], 30)}'s {n}-pick drops to a {n - 1}-pick (`#{r['pick_id']}`)." if dfs and n > 2
                else f" That leg is voided on {clip(r['bettor_name'], 30)}'s {clip(r['description'], 40)} (`#{r['pick_id']}`).")
        out.append((f"dnp:{r['pick_id']}:{r['idx']}",
                    f"🔁 **Reboot:** {clip(r['note'], 120)}.{tail}"))
    return out


async def news_job(client, now: Optional[datetime] = None) -> None:
    """Every 10 minutes per server with an ask channel: post what changed on the injury reports and any reboots."""
    now = now or datetime.now(timezone.utc)
    c = news_db()
    for r in db().execute("SELECT guild_id, value FROM settings WHERE key = 'ask_channel' AND value IS NOT NULL").fetchall():
        gid = r["guild_id"]
        try:
            if not server_on(gid, "newsfeed"):
                continue
            last = get_setting(gid, "news_checked")
            if last and datetime.fromisoformat(last) > now - timedelta(minutes=NEWS_EVERY_MIN):
                continue
            set_setting(gid, "news_checked", iso(now))
            channel = client.get_channel(int(r["value"])) if str(r["value"]).isdigit() else None
            if channel is None:
                continue
            first = c.execute("SELECT 1 FROM news_seen WHERE guild_id = ? LIMIT 1", (gid,)).fetchone() is None
            watch = await news_watchlist(gid, now)
            status = await news_status(watch) if watch else {}
            updates: list[tuple[str, str]] = []
            for key, inj in status.items():
                w = watch[key]
                row = c.execute("SELECT status, detail FROM news_seen WHERE guild_id = ? AND key = ?",
                                (gid, f"inj:{key}")).fetchone()
                was = row["status"] if row else None
                now_st = inj["status"] if inj else None
                if (was or "").lower() == (now_st or "").lower():
                    continue                       # same status ("Out" vs "OUT" from the backup feed is no news)
                c.execute("INSERT OR REPLACE INTO news_seen (guild_id, key, status, detail, posted_at) VALUES (?,?,?,?,?)",
                          (gid, f"inj:{key}", now_st, (inj or {}).get("comment"), iso(now)))
                if inj:
                    head = (f"{news_icon(now_st)} **{clip(inj['name'], 60)}** ({clip(inj.get('team') or '', 40)}) is "
                            f"**{clip(now_st, 30)}**" + (f" (was {clip(was, 20)})" if was else ""))
                    body = (f"\n> {clip(inj['comment'], 220)}" if inj.get("comment") else "")
                    updates.append((key, f"{head}{body}\n-# {news_slips_line(w)}"))
                elif was and w["slips"]:
                    updates.append((key, f"✅ **{clip(w['name'], 60)}** is off the injury report (was {clip(was, 20)}).\n"
                                         f"-# {news_slips_line(w)}"))
            for key, line in await news_reboots(gid, now):
                if c.execute("SELECT 1 FROM news_seen WHERE guild_id = ? AND key = ?", (gid, key)).fetchone():
                    continue
                c.execute("INSERT INTO news_seen (guild_id, key, status, posted_at) VALUES (?,?,?,?)",
                          (gid, key, "posted", iso(now)))
                updates.append((key, line))
            c.commit()
            if not updates:
                continue
            if first:
                listed = [u for k, u in updates if not k.startswith("dnp:")]
                text = ("📰 **Injury watch is on.** I'll post here when anyone on the group's open slips shows up on "
                        "(or comes off) an injury report, and when a player doesn't play.\n\nOn the reports right now:\n"
                        + "\n".join(listed[:12]))
                for chunk in split_message(text):
                    await channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())
                continue
            if len(updates) > NEWS_MAX_POSTS:
                text = "📰 **News roundup**\n\n" + "\n\n".join(u for _, u in updates)
                for chunk in split_message(text):
                    await channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())
            else:
                for _, u in updates:
                    await channel.send(clip(u, 1990), allowed_mentions=discord.AllowedMentions.none())
        except Exception:
            log.warning("News feed failed for guild %s", gid, exc_info=True)
    # forget old reboot marks
    c.execute("DELETE FROM news_seen WHERE key LIKE 'dnp:%' AND posted_at < ?", (iso(now - timedelta(days=7)),))
    c.commit()


EXTRA_JOBS.append(("news_feed", news_job))
SERVER_TOGGLES.append(("newsfeed", "News feed in the ask channel", "optout"))
HELP_EXTRA.append(("💬 Ask channel", (
    "Admins: `/admin askchannel` picks a channel where **anything you type is a question for the bot** (no @mention), "
    "and screenshots get a breakdown instead of being logged. The bot also posts news there: players on the group's "
    "open slips landing on (or coming off) the injury report, and 🔁 reboots when a player doesn't play.")))


async def ask_channel_message(client, message) -> None:
    """A message in the ask channel: screenshots get a breakdown (never logged), words get an answer."""
    images = image_attachments(message)
    if images:
        pics = images
        if len(pics) > 1 and hasattr(client, "review_slips"):
            await client.review_slips(message, message, pics)
        else:
            await client.review_slip(message, message, pics[0])
        return
    ref = message.reference.resolved if getattr(message, "reference", None) else None
    if isinstance(ref, discord.Message) and not ref.author.bot and not client.mentions_me(message):
        return                                   # people talking to each other in a reply
    words = text_slip_words(message)
    if len(words.strip()) < 4:
        return                                   # "lol", "ok", an emoji
    if text_route(words) == "status":
        await client.slip_status(message)
        return
    await client.handle_ask(message)


# ==========================================================================
# r29: more data providers. Official free feeds back up ESPN for live stats (NHL.com, MLB Stats API, Sleeper for
# the NFL) and fill in stats ESPN's box score doesn't carry (total bases, stolen bases...). Sleeper's injury
# statuses back up ESPN's NFL injury report in the news feed. No keys needed for any of them.
# ==========================================================================

NHL_WEB = "https://api-web.nhle.com/v1"
MLB_API = "https://statsapi.mlb.com/api/v1"
SLEEPER = "https://api.sleeper.app/v1"
HEALTH_NAMES.update({"api-web.nhle.com": "NHL.com", "statsapi.mlb.com": "MLB Stats API", "api.sleeper.app": "Sleeper"})
ALT_SOURCES = {"hockey/nhl": "NHL.com", "baseball/mlb": "MLB Stats API", "football/nfl": "Sleeper"}
_ALT_CACHE: dict = {}

async def _alt_get(url: str, params: dict, ttl: float) -> Optional[dict]:
    key = (url, tuple(sorted(params.items())))
    hit = _ALT_CACHE.get(key)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    try:
        data = await _get_json(url, params)
    except Exception:
        log.debug("Backup feed failed: %s", url, exc_info=True)
        data = None
    _ALT_CACHE[key] = (time.monotonic() + (ttl if data is not None else 120), data)
    if len(_ALT_CACHE) > 600:
        for k in list(_ALT_CACHE)[:300]:
            _ALT_CACHE.pop(k, None)
    return data


def _alt_live(ev: dict) -> bool:
    return ev.get("state") == "in"


def _alt_nick(t: dict) -> str:
    """'Celtics' from ESPN's short name (or the last word of the full name)."""
    return norm_team(t.get("short") or (t.get("name") or "").split(" ")[-1])


def _alt_pick(cands: list, ev: dict):
    """The candidate (start time or None, value) closest to ESPN's start; None when even the best is 6h+ off."""
    if not cands:
        return None
    t = event_time(ev)
    timed = [(abs((c - t).total_seconds()), v) for c, v in cands if c is not None and t is not None]
    if timed:
        gap, v = min(timed, key=lambda x: x[0])
        return v if gap <= 6 * 3600 else None
    return cands[0][1]


def _alt_when(text) -> Optional[datetime]:
    try:
        return datetime.fromisoformat(str(text).replace("Z", "+00:00")) if text else None
    except ValueError:
        return None


def _alt_days(ev: dict) -> list[str]:
    """The game's date in US Eastern time (the leagues' own calendars), and the day before, as YYYY-MM-DD."""
    t = event_time(ev)
    if t is None:
        return []
    et = t.astimezone(ZoneInfo("America/New_York")).date()
    return [et.isoformat(), (et - timedelta(days=1)).isoformat()]


# ---- NHL.com -------------------------------------------------------------------------------------------------

ALT_NHL_ABBR = {"NJ": "NJD", "TB": "TBL", "LA": "LAK", "SJ": "SJS", "UTAH": "UTA", "MON": "MTL", "WAS": "WSH"}


async def alt_nhl_box(ev: dict) -> Optional[dict]:
    away, home = lv_sides(ev)
    want = {_alt_nick(away), _alt_nick(home)}
    want_ab = {ALT_NHL_ABBR.get((t.get("abbr") or "").upper(), (t.get("abbr") or "").upper()) for t in (away, home)}
    gid = None
    for day in _alt_days(ev):
        data = await _alt_get(f"{NHL_WEB}/score/{day}", {}, 120 if _alt_live(ev) else 1800)
        cands = []
        for g in (data or {}).get("games") or []:
            if not isinstance(g, dict):
                continue
            names = {norm_team(((g.get(s) or {}).get("name") or {}).get("default") or "") for s in ("awayTeam", "homeTeam")}
            abbrs = {str((g.get(s) or {}).get("abbrev") or "").upper() for s in ("awayTeam", "homeTeam")}
            if want <= names or ("" not in want_ab and want_ab <= abbrs):
                cands.append((_alt_when(g.get("startTimeUTC")), g.get("id")))
        gid = _alt_pick(cands, ev)
        if gid:
            break
    if not gid:
        return None
    box = await _alt_get(f"{NHL_WEB}/gamecenter/{gid}/boxscore", {}, 60 if _alt_live(ev) else 6 * 3600)
    if not box:
        return None
    state = {"OFF": "post", "FINAL": "post", "LIVE": "in", "CRIT": "in"}.get(box.get("gameState"), "pre")
    players = []
    for side in ("awayTeam", "homeTeam"):
        grp = ((box.get("playerByGameStats") or {}).get(side)) or {}
        for pos in ("forwards", "defense", "goalies"):
            for p in grp.get(pos) or []:
                name = ((p.get("name") or {}).get("default")) or ""
                full = " ".join(x for x in ((p.get("firstName") or {}).get("default"), (p.get("lastName") or {}).get("default"))
                                if x) or name
                toi = str(p.get("toi") or "00:00")
                comps = {"g": p.get("goals"), "a": p.get("assists"), "sog": p.get("sog"), "hits_nhl": p.get("hits"),
                         "blocked": p.get("blockedShots")} if pos != "goalies" else {"saves": p.get("saves")}
                players.append({"name": full, "norm": norm_name(full), "dnp": toi in ("00:00", "0:00", ""),
                                "comps": {k: float(v) for k, v in comps.items() if isinstance(v, (int, float))}})
    return {"state": state, "players": players}


# ---- MLB Stats API -------------------------------------------------------------------------------------------

async def alt_mlb_box(ev: dict) -> Optional[dict]:
    away, home = lv_sides(ev)
    want = {norm_team(away.get("name") or ""), norm_team(home.get("name") or "")}
    pk, state = None, "pre"
    for day in _alt_days(ev):
        data = await _alt_get(f"{MLB_API}/schedule", {"sportId": 1, "date": day}, 120 if _alt_live(ev) else 1800)
        cands = []
        for d in (data or {}).get("dates") or []:
            for g in d.get("games") or []:
                t = g.get("teams") or {}
                names = {norm_team(((t.get(s) or {}).get("team") or {}).get("name") or "") for s in ("away", "home")}
                if want <= names and g.get("gamePk"):
                    cands.append((_alt_when(g.get("gameDate")), g))
        g = _alt_pick(cands, ev)           # a doubleheader lists both games: the one at ESPN's start time
        if g:
            pk = g.get("gamePk")
            st = ((g.get("status") or {}).get("abstractGameState") or "").lower()
            state = {"final": "post", "live": "in"}.get(st, "pre")
            break
    if not pk:
        return None
    box = await _alt_get(f"{MLB_API}/game/{pk}/boxscore", {}, 60 if state == "in" else 6 * 3600)
    if not box:
        return None
    players = []
    for side in ("away", "home"):
        for p in (((box.get("teams") or {}).get(side) or {}).get("players") or {}).values():
            name = (p.get("person") or {}).get("fullName") or ""
            bat = (p.get("stats") or {}).get("batting") or {}
            pit = (p.get("stats") or {}).get("pitching") or {}
            comps = {}
            # both the box-score names and the per-game ("c_") names the tracker uses for PrizePicks stats
            for cs, k in ((("h", "c_h"), "hits"), (("r", "c_r"), "runs"), (("rbi", "c_rbi"), "rbi"),
                          (("hr", "c_hr"), "homeRuns"), (("bb", "c_bb"), "baseOnBalls"), (("so_bat",), "strikeOuts"),
                          (("c_tb",), "totalBases"), (("c_sb",), "stolenBases"), (("c_2b",), "doubles"),
                          (("c_3b",), "triples"), (("c_hbp",), "hitByPitch")):
                if isinstance(bat.get(k), (int, float)):
                    for c in cs:
                        comps[c] = float(bat[k])
            for cs, k in ((("k", "c_pk"), "strikeOuts"), (("h_allowed",), "hits"), (("er", "c_er"), "earnedRuns"),
                          (("bb_allowed",), "baseOnBalls"), (("outs", "c_outs"), "outs"),
                          (("c_pitches",), "numberOfPitches")):
                if isinstance(pit.get(k), (int, float)):
                    for c in cs:
                        comps[c] = float(pit[k])
            if "c_pitches" not in comps and isinstance(pit.get("pitchesThrown"), (int, float)):
                comps["c_pitches"] = float(pit["pitchesThrown"])
            players.append({"name": name, "norm": norm_name(name), "dnp": not bat and not pit, "comps": comps})
    return {"state": state, "players": players}


# ---- Sleeper (NFL) -------------------------------------------------------------------------------------------

_SLEEPER_PLAYERS: dict = {"at": 0.0, "by_id": {}, "by_name": {}}


async def sleeper_players() -> dict:
    """{player id: {name, norm, team, pos, injury, body, notes}} from Sleeper's player list (fetched at most daily,
    as Sleeper asks)."""
    if _SLEEPER_PLAYERS["by_id"] and time.monotonic() - _SLEEPER_PLAYERS["at"] < 20 * 3600:
        return _SLEEPER_PLAYERS["by_id"]
    if _SLEEPER_PLAYERS["at"] and time.monotonic() - _SLEEPER_PLAYERS["at"] < 600 and not _SLEEPER_PLAYERS["by_id"]:
        return {}                                  # failed recently: don't hammer it
    _SLEEPER_PLAYERS["at"] = time.monotonic()
    try:
        raw = await _get_json(f"{SLEEPER}/players/nfl", {})
    except Exception:
        log.warning("Sleeper player list failed", exc_info=True)
        return _SLEEPER_PLAYERS["by_id"]
    by_id, by_name = {}, {}
    if not isinstance(raw, dict):
        log.warning("Sleeper player list wasn't readable")
        return _SLEEPER_PLAYERS["by_id"]
    for pid, p in raw.items():
        if not isinstance(p, dict) or not p.get("full_name") or p.get("position") in (None, "DEF"):
            continue
        rec = {"name": p["full_name"], "norm": norm_name(p["full_name"]), "team": (p.get("team") or "").upper(),
               "pos": p.get("position") or "", "injury": p.get("injury_status") or "",
               "body": p.get("injury_body_part") or "", "notes": p.get("injury_notes") or ""}
        by_id[str(pid)] = rec
        by_name.setdefault(rec["norm"], []).append(str(pid))
    _SLEEPER_PLAYERS.update(by_id=by_id, by_name=by_name)
    return by_id


SLEEPER_COMPS = {"pass_yds": "pass_yd", "pass_td": "pass_td", "pass_int": "pass_int", "pass_cmp": "pass_cmp",
                 "pass_att": "pass_att", "rush_yds": "rush_yd", "rush_att": "rush_att", "rush_td": "rush_td", "rec": "rec",
                 "rec_yds": "rec_yd", "rec_td": "rec_td", "targets": "rec_tgt", "long_rec": "rec_lng",
                 "long_rush": "rush_lng", "fum_lost": "fum_lost", "fg_made": "fgm", "sacks": "idp_sack",
                 "tackles": "idp_tkl", "def_int": "idp_int"}
SLEEPER_TEAM = {"WSH": "WAS", "JAC": "JAX", "LA": "LAR"}


async def alt_nfl_box(ev: dict) -> Optional[dict]:
    week, season = ev.get("week"), ev.get("season")
    if not week or not season:
        return None
    kind = {1: "pre", 2: "regular", 3: "post"}.get(ev.get("season_type") or 2, "regular")
    stats = await _alt_get(f"{SLEEPER}/stats/nfl/{kind}/{season}/{week}", {}, 120 if _alt_live(ev) else 3 * 3600)
    if not stats or not isinstance(stats, dict):
        return None
    people = await sleeper_players()
    teams = {SLEEPER_TEAM.get((t.get("abbr") or "").upper(), (t.get("abbr") or "").upper()) for t in ev.get("teams") or []}
    players = []
    for pid, s in stats.items():
        who = people.get(str(pid))
        if not who or not isinstance(s, dict) or (teams and who["team"] and who["team"] not in teams):
            continue
        comps = {c: float(s[k]) for c, k in SLEEPER_COMPS.items() if isinstance(s.get(k), (int, float))}
        if s.get("gp"):                       # he played: a stat Sleeper leaves out is a zero
            for c in ("pass_yds", "pass_td", "pass_int", "rush_yds", "rush_td", "rec", "rec_yds", "rec_td", "fum_lost"):
                comps.setdefault(c, 0.0)
        players.append({"name": who["name"], "norm": who["norm"], "dnp": False, "comps": comps})
    return {"state": ev.get("state") or "pre", "players": players}


# ---- the hook: ESPN first, the backup feed when ESPN comes up short -----------------------------------------

ALT_BOX = {"hockey/nhl": alt_nhl_box, "baseball/mlb": alt_mlb_box, "football/nfl": alt_nfl_box}


def alt_value(pl: dict, stat_key: str) -> Optional[tuple[float, str]]:
    _, _, parts, _ = STATS[stat_key]
    total, shown = 0.0, []
    for comp, w in parts:
        v = pl["comps"].get(comp)
        if v is None:
            return None
        total += v * w
        shown.append((comp, v))
    detail = "" if len(parts) == 1 or len(parts) > 6 else \
        " (" + ", ".join(f"{v:g} {COMP_SHORT.get(c, c)}" for c, v in shown) + ")"
    return round(total, 2), detail


async def alt_try(out: dict, leg: dict, path: str, ev: dict, cand: dict, stat_key: str) -> dict:
    """Fill in a prop from the league's own feed when ESPN's box score didn't have it."""
    fn = ALT_BOX.get(path)
    if fn is None or out.get("value") is not None or ev.get("state") == "pre":
        return out
    try:
        box = await fn(ev)
    except Exception:
        log.debug("Backup box score failed", exc_info=True)
        return out
    if not box or not box["players"]:
        return out
    target = norm_name(cand.get("name") or leg["player"])
    scored = [(name_score(target, p["norm"]), p) for p in box["players"]]
    best = max((s for s, _ in scored), default=0)
    top = [p for s, p in scored if s == best and s >= 2]
    if len(top) != 1:
        return out                             # nobody, or two players it could be: no guessing
    pl = top[0]
    if box["state"] in ("in", "post"):
        out["state"] = box["state"] if out["state"] != "post" else "post"
    src = ALT_SOURCES.get(path, "backup feed")
    if pl["dnp"]:
        if out["state"] == "post" and box["state"] == "post":
            out["result"], out["why"] = "push", f"{pl['name']} didn't play (per {src})"
        return out
    got = alt_value(pl, stat_key)
    if got is None:
        return out
    out["source"] = src
    return track_judge(out, leg, (got[0], got[1] + f" · {src}"), pl["name"])


# ---- injuries: Sleeper backs up ESPN's NFL report ----------------------------------------------------------

SLEEPER_INJURY = {"out": "Out", "ir": "Out", "pup": "Out", "sus": "Suspension", "doubtful": "Doubtful",
                  "questionable": "Questionable", "cov": "Out", "na": None}


async def sleeper_injury(player_norm: str) -> Optional[dict]:
    """An NFL player's injury status from Sleeper ({name, status, comment, team}), when it names one player."""
    await sleeper_players()
    ids = _SLEEPER_PLAYERS["by_name"].get(player_norm) or []
    if len(ids) != 1:
        return None
    p = _SLEEPER_PLAYERS["by_id"][ids[0]]
    st = SLEEPER_INJURY.get((p["injury"] or "").lower().strip(), p["injury"] or None)
    if not st:
        return None
    comment = " · ".join(x for x in (p["body"], p["notes"]) if x)
    return {"name": p["name"], "status": st, "comment": comment, "team": p["team"], "path": "football/nfl",
            "source": "Sleeper"}


def data_sources_line() -> str:
    """For /admin status: every feed the bot reads and how it's doing."""
    now = time.time()
    parts = []
    for host, label in HEALTH_NAMES.items():
        h = DATA_HEALTH.get(host)
        if not h:
            parts.append(f"⚪ {label}")
            continue
        bad = h.get("streak", 0) >= 3
        parts.append(f"{'🔴' if bad else '🟢'} {label}")
    return " · ".join(parts)


